// ============================================================
// Country PES Overview Dashboard
// For Admin 0 popup
//
// Existing four-layer deployment.
//
// Data sources:
//   - PES Applications - Points
//       Full application population, including applications
//       without polygon geometry.
//
//   - PES Contracts
//       Contracted hectares, planted hectares and observed trees.
//
// IMPORTANT:
// Make sure the layer names in the web map are exactly:
//   - PES Applications - Points
//   - PES Contracts
// ============================================================


// ============================================================
// COUNTRY FIELD
// ============================================================

// Adjust this field if your Admin 0 layer uses a different country name field.
var country = $feature.admin0_pse_name;


// ============================================================
// APPLICATIONS POINTS VIEW
// Full population of applications
// ============================================================

var apps = Filter(
    FeatureSetByName(
        $map,
        "PES Applications - Points",
        [
            "StageCategory",
            "StageOrder",
            "IsContract",
            "HasMonitoring",
            "MonitoringOverdue",
            "VisitCount",
            "VisitsCompleted",
            "EstimatedArea",
            "ActivityType",
            "BeneficiaryGender",
            "FireRiskCategory",
            "LandCoverChanged",
            "Country"
        ],
        false
    ),
    "Country = @country AND StageCategory NOT IN ('Rejected', 'Archived')"
);


// ============================================================
// CONTRACTS VIEW
// Contracted area, planted area and observed trees
// ============================================================

var cons = Filter(
    FeatureSetByName(
        $map,
        "PES Contracts",
        [
            "contractedpesarea",
            "plantedareameasured",
            "observednumberoftrees",
            "country"
        ],
        false
    ),
    "country = @country"
);


// ============================================================
// EMPTY STATE
// ============================================================

var total = Count(apps);

if (total == 0) {
    return {
        type: "text",
        text: "<i>No active PES applications in " + country + " yet.</i>"
    };
}


// ============================================================
// APPLICATION COUNTS
// ============================================================

var inReview = Count(Filter(apps, "StageOrder >= 1 AND StageOrder <= 4"));
var validated = Count(Filter(apps, "StageOrder = 5"));
var recommended = Count(Filter(apps, "StageOrder = 6"));
var approved = Count(Filter(apps, "StageOrder = 7"));

var contracts = Count(Filter(apps, "IsContract = 1"));
var monitored = Count(Filter(apps, "HasMonitoring = 1"));
var overdue = Count(Filter(apps, "MonitoringOverdue = 1"));


// ============================================================
// VISIT SCHEDULE AGGREGATION
// ============================================================

var scheduled = Filter(apps, "VisitCount > 0");

var visitsDone = DefaultValue(Sum(scheduled, "VisitsCompleted"), 0);
var visitsExpected = DefaultValue(Sum(scheduled, "VisitCount"), 0);

var visitPct = 0;

if (visitsExpected > 0) {
    visitPct = Round((visitsDone / visitsExpected) * 100, 0);
}

if (visitPct < 0) {
    visitPct = 0;
}

if (visitPct > 100) {
    visitPct = 100;
}


// ============================================================
// AREA AND TREE AGGREGATION
// ============================================================

// Estimated area comes from Applications Points.
var estimatedHa = DefaultValue(Sum(apps, "EstimatedArea"), 0);

// Contracted / planted / observed trees come from PES Contracts.
var contractedHa = DefaultValue(Sum(cons, "contractedpesarea"), 0);
var plantedHa = DefaultValue(Sum(cons, "plantedareameasured"), 0);
var treesObs = DefaultValue(Sum(cons, "observednumberoftrees"), 0);

var areaPct = 0;

if (contractedHa > 0) {
    areaPct = Round((plantedHa / contractedHa) * 100, 1);
}

if (areaPct < 0) {
    areaPct = 0;
}

if (areaPct > 100) {
    areaPct = 100;
}


// ============================================================
// FIRE RISK AND LAND COVER CHANGE
// ============================================================

var fireLow = Count(Filter(apps, "FireRiskCategory = 'Low'"));
var fireMod = Count(Filter(apps, "FireRiskCategory = 'Moderate'"));
var fireHigh = Count(Filter(apps, "FireRiskCategory = 'High'"));
var fireVHigh = Count(Filter(apps, "FireRiskCategory = 'Very High'"));

var fireAny = fireLow + fireMod + fireHigh + fireVHigh;

var lcChangedCnt = Count(Filter(apps, "LandCoverChanged = 1"));
var lcKnownCnt = Count(Filter(apps, "LandCoverChanged IS NOT NULL"));


// ============================================================
// BENEFICIARY GENDER
// ============================================================

var femaleCnt = Count(Filter(apps, "BeneficiaryGender = 'Female'"));
var maleCnt = Count(Filter(apps, "BeneficiaryGender = 'Male'"));

var genderCnt = femaleCnt + maleCnt;


// ============================================================
// HTML HELPERS
// ============================================================

function tile(value, labelText, color) {
    return "<div style=\"flex:1 1 30%; min-width:80px; background:#f5f9f9; border:1px solid #e0e0e0; border-radius:6px; padding:8px 4px; text-align:center;\">"
        + "<div style=\"font-size:18px; font-weight:700; color:" + color + ";\">" + value + "</div>"
        + "<div style=\"font-size:9px; color:#666; text-transform:uppercase; letter-spacing:0.5px; margin-top:2px;\">" + labelText + "</div>"
        + "</div>";
}


function distBar(labelText, cnt, totalCnt, barColor) {
    if (cnt == 0 || totalCnt == 0) {
        return "";
    }

    var pct = Round((cnt / totalCnt) * 100, 0);

    if (pct < 0) {
        pct = 0;
    }

    if (pct > 100) {
        pct = 100;
    }

    return "<div style=\"margin-bottom:6px;\">"
        + "<div style=\"display:flex; justify-content:space-between; font-size:10px; color:#555; margin-bottom:2px;\">"
        + "<span style=\"font-weight:600;\">" + labelText + "</span>"
        + "<span style=\"font-weight:700; color:" + barColor + ";\">" + cnt + " (" + pct + "%)</span>"
        + "</div>"
        + "<div style=\"background:#e0e0e0; border-radius:4px; height:12px; width:100%; overflow:hidden;\">"
        + "<div style=\"background:" + barColor + "; height:12px; width:" + pct + "%; border-radius:4px;\"></div>"
        + "</div>"
        + "</div>";
}


function card(titleText, accentColor, body) {
    if (IsEmpty(body) || body == "") {
        return "";
    }

    return "<div style=\"background:#f7fafa; border-left:4px solid " + accentColor + "; border-radius:4px; margin-bottom:10px; padding:8px 12px 8px 8px;\">"
        + "<div style=\"font-size:10px; font-weight:700; color:" + accentColor + "; text-transform:uppercase; letter-spacing:0.8px; margin-bottom:8px;\">" + titleText + "</div>"
        + body
        + "</div>";
}


function progressBlock(titleText, doneTxt, pct, barColor) {
    if (pct < 0) {
        pct = 0;
    }

    if (pct > 100) {
        pct = 100;
    }

    return "<div style=\"background:#f5f9f9; border-radius:6px; padding:8px 12px; margin-bottom:10px; border:1px solid #e0e0e0;\">"
        + "<div style=\"display:flex; justify-content:space-between; font-size:11px; color:#666; margin-bottom:4px;\">"
        + "<span>" + titleText + "</span>"
        + "<span style=\"font-weight:700; color:" + barColor + ";\">" + doneTxt + "</span>"
        + "</div>"
        + "<div style=\"background:#e0e0e0; border-radius:6px; height:10px; width:100%; overflow:hidden;\">"
        + "<div style=\"background:" + barColor + "; height:10px; width:" + pct + "%; border-radius:6px;\"></div>"
        + "</div>"
        + "</div>";
}


// ============================================================
// ACTIVITY MIX
// Dynamic grouping, no hard-coded activity list.
// ============================================================

var activityRows = "";

var byActivity = OrderBy(
    GroupBy(
        apps,
        ["ActivityType"],
        [
            {
                name: "cnt",
                expression: "1",
                statistic: "COUNT"
            }
        ]
    ),
    "cnt DESC"
);

for (var g in byActivity) {
    var actName = DefaultValue(g["ActivityType"], "Unspecified");
    activityRows = activityRows + distBar(actName, g["cnt"], total, "#0d7377");
}


// ============================================================
// FIRE RISK PROFILE
// ============================================================

var fireRows = "";

if (fireAny > 0) {
    fireRows =
        distBar("Low", fireLow, fireAny, "#4caf50")
        + distBar("Moderate", fireMod, fireAny, "#ffb300")
        + distBar("High", fireHigh, fireAny, "#ef6c00")
        + distBar("Very High", fireVHigh, fireAny, "#c62828");

    if (lcKnownCnt > 0) {
        fireRows = fireRows
            + "<div style=\"font-size:10px; color:#666; margin-top:6px;\">&#127793; Land cover change: <b>"
            + lcChangedCnt + " of " + lcKnownCnt
            + "</b> parcel(s) have a different dominant land cover than at application time</div>";
    }
}


// ============================================================
// GENDER SPLIT
// ============================================================

var genderHtml = "";

if (genderCnt > 0) {
    var femPct = Round((femaleCnt / genderCnt) * 100, 0);

    if (femPct < 0) {
        femPct = 0;
    }

    if (femPct > 100) {
        femPct = 100;
    }

    var malePct = 100 - femPct;

    genderHtml =
        "<div style=\"display:flex; justify-content:space-between; font-size:10px; color:#555; margin-bottom:2px;\">"
        + "<span style=\"font-weight:600;\">Female " + femaleCnt + " (" + femPct + "%)</span>"
        + "<span style=\"font-weight:600;\">Male " + maleCnt + " (" + malePct + "%)</span>"
        + "</div>"
        + "<div style=\"display:flex; height:12px; border-radius:4px; overflow:hidden;\">"
        + "<div style=\"width:" + femPct + "%; background:#9c27b0;\"></div>"
        + "<div style=\"flex:1; background:#42a5f5;\"></div>"
        + "</div>";
}


// ============================================================
// STAGE DISTRIBUTION
// ============================================================

var stageRows =
    distBar("In review", inReview, total, "#90a4ae")
    + distBar("Validated", validated, total, "#ffb300")
    + distBar("Recommended", recommended, total, "#c0ca33")
    + distBar("Approved / contract stage", approved, total, "#2e7d32");


// ============================================================
// OPTIONAL SUMMARY FLAGS
// ============================================================

var alertText = "";

if (overdue > 0) {
    alertText =
        "<div style=\"background:#fbe9e7; color:#d84315; border-radius:6px; padding:6px 8px; margin-bottom:10px; font-size:11px; font-weight:700; text-align:center;\">"
        + "&#9888; " + overdue + " application(s) have overdue or unscheduled remaining monitoring visits"
        + "</div>";
}


// ============================================================
// BUILD DASHBOARD
// ============================================================

var html =
    "<div style=\"font-family:Segoe UI,sans-serif; font-size:13px; color:#1a1a2e;\">"

    // Header
    + "<div style=\"background:#0d7377; color:white; padding:10px 12px; border-radius:6px 6px 0 0; margin-bottom:10px;\">"
    + "<div style=\"font-size:15px; font-weight:700;\">" + country + "</div>"
    + "<div style=\"font-size:10px; opacity:0.9; margin-top:2px; text-transform:uppercase; letter-spacing:0.8px;\">PES Programme Overview</div>"
    + "</div>"

    // Optional alert
    + alertText

    // KPI row 1
    + "<div style=\"display:flex; gap:6px; margin-bottom:6px; flex-wrap:wrap;\">"
    + tile(total, "Active applications", "#0d7377")
    + tile(contracts, "Contracts", "#2e7d32")
    + tile(overdue, "Visits overdue", IIf(overdue > 0, "#d84315", "#9e9e9e"))
    + "</div>"

    // KPI row 2
    + "<div style=\"display:flex; gap:6px; margin-bottom:10px; flex-wrap:wrap;\">"
    + tile(Round(contractedHa, 0) + " ha", "Contracted area", "#0d7377")
    + tile(Round(plantedHa, 0) + " ha", "Planted area", "#4caf50")
    + tile(IIf(treesObs > 0, Text(treesObs, "#,###"), "-"), "Trees observed", "#607d8b")
    + "</div>"

    // Pipeline
    + card(
        "Pipeline by Stage",
        "#0d7377",
        stageRows
    )

    // Activity mix
    + card(
        "Activity Mix",
        "#14a085",
        activityRows
    )

    // Monitoring progress
    + IIf(
        visitsExpected > 0,
        progressBlock(
            "Monitoring visits completed",
            visitsDone + " of " + visitsExpected + " (" + visitPct + "%)",
            visitPct,
            IIf(overdue > 0, "#e64a19", "#2e7d32")
        ),
        ""
    )

    // Area progress
    + IIf(
        contractedHa > 0,
        progressBlock(
            "Planted vs contracted area",
            Round(plantedHa, 1) + " / " + Round(contractedHa, 1) + " ha (" + areaPct + "%)",
            areaPct,
            "#4caf50"
        ),
        ""
    )

    // Fire risk
    + card(
        "Fire Risk Profile - last 5 years",
        "#ef6c00",
        fireRows
    )

    // Gender
    + card(
        "Beneficiary Gender",
        "#9c27b0",
        genderHtml
    )

    // Footer
    + "<div style=\"text-align:center; font-size:10px; color:#aaa; margin-top:6px; padding-top:6px; border-top:1px solid #eee;\">"
    + monitored + " application(s) with completed visits"
    + "&nbsp;|&nbsp;" + Round(estimatedHa, 0) + " ha estimated at application"
    + "&nbsp;|&nbsp; excludes rejected and archived"
    + "</div>"

    + "</div>";


return {
    type: "text",
    text: html
};

// ============================================================
//  CB_Logging_Concessions — popup content (Arcade element)
//  House style: banner header, chips, KPI tiles, breadcrumb pill, timeline,
//  comparison bars, zoning donut, document cards with direct links.
//
//  DATA ACCESS: by default the popup reads the zoning layer and the documents
//  table FROM THE WEB MAP by layer name (add "CB_Concession_Zoning" and the
//  table "CB_Documents" to the map; they can stay hidden). Alternatively set
//  SOURCE = 'portal' and paste the service item id.
// ============================================================
Expects($feature, "*")

var SOURCE      = "map"                 // "map" (layers in the web map) | "portal" (by item id)
var PORTAL_URL  = "https://geosmarthosting.undp.org/portal"
var ITEM_ID     = "PASTE_ITEM_ID_HERE"
var NAME_ZONING = "Logging concessions - Zoning";  var ID_ZONING = 1
var NAME_DOCS   = "CB_Documents";          var ID_DOCS   = 7
var ACCENT      = "#5d4037"             // banner colour of this layer

// ---------- helpers ------------------------------------------------------------------------
function isBlank(x) { return IsEmpty(x) || Text(x) == "" || Text(x) == "null" }
function txt(x) { if (isBlank(x)) { return "" } var s = Text(x); s = Replace(s, "&", "&amp;"); s = Replace(s, "<", "&lt;"); return Replace(s, ">", "&gt;") }
function haTxt(x) { if (isBlank(x)) { return "" } var n = Number(x); if (IsNan(n) || n <= 0) { return "" } return Text(Round(n, 0), "#,###") + " ha" }
function dateTxt(x) { if (IsEmpty(x)) { return "" } return Text(Date(x), "DD MMM YYYY") }
function cat(dict, key, dflt) { if (!isBlank(key) && HasKey(dict, key)) { return dict[key] } return dflt }
function fsGet(name, id, fields, geom) {
  if (SOURCE == "portal" && ITEM_ID != "PASTE_ITEM_ID_HERE") { return FeatureSetByPortalItem(Portal(PORTAL_URL), ITEM_ID, id, fields, geom) }
  return FeatureSetByName($map, name, fields, geom)
}
function row(label, value) {
  if (isBlank(value)) { return "" }
  return "<tr><td style=\"color:#666; width:44%; padding:4px 6px 4px 0; font-size:12px; vertical-align:top;\">" + label + "</td>"
       + "<td style=\"font-weight:600; font-size:12px; padding:4px 0; vertical-align:top;\">" + value + "</td></tr>"
}
function table(rows) { if (isBlank(rows)) { return "" } return "<table style=\"width:100%; border-collapse:collapse;\">" + rows + "</table>" }
function section(title, accent, body) {
  if (isBlank(body)) { return "" }
  return "<div style=\"background:#f7fafa; border-left:4px solid " + accent + "; border-radius:4px; margin-bottom:10px; padding:8px 10px 8px 8px;\">"
       + "<div style=\"font-size:10px; font-weight:700; color:" + accent + "; text-transform:uppercase; letter-spacing:0.8px; margin-bottom:8px;\">" + title + "</div>" + body + "</div>"
}
function chip(label, bg, fg) { return "<div style=\"background:" + bg + "; color:" + fg + "; padding:5px 10px; border-radius:6px; font-size:11px; font-weight:700;\">" + label + "</div>" }
function tile(value, label, color) {
  return "<div style=\"flex:1 1 30%; min-width:80px; background:#f5f9f9; border:1px solid #e0e0e0; border-radius:6px; padding:8px 4px; text-align:center;\">"
       + "<div style=\"font-size:16px; font-weight:700; color:" + color + ";\">" + value + "</div>"
       + "<div style=\"font-size:9px; color:#666; text-transform:uppercase; letter-spacing:0.5px; margin-top:2px;\">" + label + "</div></div>"
}
function bar(label, value, color, maxv) {
  if (isBlank(value) || value <= 0 || maxv <= 0) { return "" }
  var pct = Round((value / maxv) * 100, 0)
  return "<div style=\"margin-bottom:6px;\"><div style=\"display:flex; justify-content:space-between; font-size:10px; color:#555; margin-bottom:2px;\">"
       + "<span style=\"font-weight:600;\">" + label + "</span><span style=\"font-weight:700; color:" + color + ";\">" + haTxt(value) + "</span></div>"
       + "<div style=\"background:#e0e0e0; border-radius:4px; height:12px; width:100%; overflow:hidden;\"><div style=\"background:" + color + "; height:12px; width:" + pct + "%; border-radius:4px;\"></div></div></div>"
}
function docIcon(name) {
  var n = Lower(Text(name))
  if (Find(".pdf", n) > -1) { return "&#128196;" }
  if (Find(".doc", n) > -1) { return "&#128221;" }
  if (Find(".xls", n) > -1) { return "&#128202;" }
  if (Find(".zip", n) > -1 || Find(".shp", n) > -1 || Find(".kml", n) > -1) { return "&#128506;" }
  if (Find(".jpg", n) > -1 || Find(".png", n) > -1 || Find(".jpeg", n) > -1) { return "&#128444;" }
  return "&#128196;"
}

// ---------- vocabularies -------------------------------------------------------------------
var FLAG = { "CMR": "🇨🇲", "CAF": "🇨🇫", "COD": "🇨🇩", "COG": "🇨🇬", "GNQ": "🇬🇶", "GAB": "🇬🇦" }
var SUBTYPE = { "ufa": "Unité forestière d'aménagement", "communal_forest": "Forêt communale", "timber_sale": "Vente de coupe",
  "pea": "Permis d'exploitation et d'aménagement", "ccf_exploitation": "Contrat de concession forestière", "ccf_conservation": "Concession forestière de conservation",
  "concession": "Concession forestière", "parcel": "Parcela forestal", "permit": "Permis forestier", "ufa_cfad": "UFA / CFAD (unité aménagée)" }
var STATUS = { "attributed": ["Attribuée", "#e8f5e9", "#2e7d32"], "provisional": ["Convention provisoire", "#fff8e1", "#ff8f00"], "final": ["Convention définitive", "#e8f5e9", "#1b5e20"],
  "in_process": ["En cours d'instruction", "#e3f2fd", "#1565c0"], "not_attributed": ["Non attribuée", "#eceff1", "#607d8b"], "rejected": ["Rejetée", "#ffebee", "#c62828"],
  "expired": ["Expirée / résiliée", "#efebe9", "#6d4c41"], "unknown": ["Statut non renseigné", "#eceff1", "#546e7a"] }
var MGMT = { "approved": ["Plan d'aménagement approuvé", "#e8f5e9", "#2e7d32"], "in_preparation": ["Aménagement en cours", "#fff8e1", "#ff8f00"],
  "under_revision": ["Plan en révision", "#e3f2fd", "#1565c0"], "not_planned": ["Non aménagée", "#eceff1", "#607d8b"], "unknown": ["Aménagement non renseigné", "#eceff1", "#90a4ae"] }
var ZONE = { "production": ["Production", "#c98a2b"], "conservation": ["Conservation", "#2e7d32"], "protection": ["Protection", "#00695c"],
  "community_development": ["Développement communautaire", "#a0522d"], "agriculture": ["Agriculture", "#d4b106"], "habitat": ["Habitat", "#8d6e63"],
  "savanna_protection": ["Mise en défens / reboisement", "#7cb342"], "concession": ["Zone concédée", "#5d4037"], "community_forest": ["Forêt communautaire", "#43a047"],
  "conflict": ["Zone conflictuelle", "#d32f2f"], "research": ["Recherche", "#7e57c2"], "unclassified": ["Non classée", "#bdbdbd"], "other": ["Autre", "#607d8b"] }
var DOCCAT = { "attribution_decree": ["Arrêtés, décrets et lettres d'attribution", "#5e35b1"], "convention": ["Conventions et contrats", "#1565c0"], "management_plan": ["Plans d'aménagement", "#2e7d32"],
  "simple_management_plan": ["Plans simples de gestion", "#2e7d32"], "specifications": ["Cahiers des charges", "#00838f"], "certificate": ["Certificats et permis", "#ef6c00"], "map": ["Cartes", "#3949ab"],
  "attestation": ["Attestations", "#6d4c41"], "minutes": ["Procès-verbaux", "#546e7a"], "application": ["Demandes et dossiers", "#8d6e63"], "evaluation": ["Rapports et évaluations", "#7b1fa2"], "other": ["Autres documents", "#78909c"] }
var NATIVE = {
  "CMR": [["desc_type", "Type"], ["nom_conces", "Nom de la concession"], ["statu_class", "Statut de classement"], ["date_class", "Date de classement"], ["rfa_ha", "RFA (FCFA/ha)"],
          ["sup_adm_ha", "Superficie administrative (ha)"], ["sup_sig_ha", "Superficie SIG (ha)"], ["statut_vc", "Statut vente de coupe"], ["destin", "Destination"], ["cyc_renouv", "Cycle de renouvellement"]],
  "CAF": [["num_permis", "Numéro de permis"], ["type_conv", "Type de convention"], ["date_conv", "Date de la convention"], ["statu_amgt", "Statut d'aménagement"], ["date_amgt", "Date d'aménagement"],
          ["sup_tax_ha", "Superficie taxable (ha)"], ["t_cert_af", "Certification aménagement"], ["b_cert_af", "Bureau certificateur"], ["s_cert_af", "Superficie certifiée (ha)"],
          ["t_cert_leg", "Certification origine légale"], ["t_cert_tra", "Certification traçabilité"], ["dat_exp", "Date d'expiration"]],
  "COD": [["num_ccf", "N° contrat de concession"], ["ref_ccf", "Référence du contrat"], ["num_ga", "N° garantie d'approvisionnement"], ["num_ccc", "N° CCC"], ["ancien_nom", "Ancien nom"],
          ["statu_ccf", "Statut du contrat"], ["date_attr", "Date d'attribution"], ["date_echea", "Échéance du contrat"], ["orig_capit", "Origine du capital"], ["statu_pg", "Statut plan de gestion"],
          ["statu_amgt", "Statut d'aménagement"], ["date_amgt", "Validation du plan d'aménagement"], ["statu_cert", "Statut certification"], ["type_cert", "Type de certification"],
          ["date_cert", "Date de certification"], ["dat_ech_ce", "Échéance certification"], ["statu_leg", "Statut de légalité"], ["date_legal", "Date de légalité"],
          ["sup_ccf_ha", "Superficie dans le CCF (ha)"], ["sup_exp_ha", "Superficie exploitable (ha)"]],
  "COG": [["nom_ufa", "UFA"], ["Code", "Code"], ["nom_dep", "Département"], ["statu_attr", "Statut d'attribution"], ["Sitatu_att", "Statut"], ["statu_amgt", "Statut d'aménagement"],
          ["Processus_", "Processus d'aménagement"], ["Types_de_p", "Type de plan d'aménagement"], ["type_cert", "Type de certificat"], ["Type_de_ce", "Certificat"], ["Situation_", "Situation de la certification"], ["Capital", "Origine du capital"]],
  "GNQ": [["num_regis", "N° de registre"], ["codigo", "Código"], ["nom_pblado", "Poblado"], ["local_dist", "Distrito"], ["estad_atrb", "Estado de atribución"], ["estad_expl", "Estado de explotación"],
          ["fech_atrb", "Fecha de atribución"], ["empr_explo", "Empresa explotadora"], ["nomb_propt", "Propietario"], ["auto_firma", "Autoridad firmante"], ["texto_ofic", "Texto oficial"]],
  "GAB": [["type_desc", "Type de permis"], ["num_permis", "Numéro de permis"], ["cat_titulaire", "Catégorie de titulaire"], ["code_titul", "Code titulaire"], ["num_lot", "Numéro de lot"], ["nbr_lot", "Nombre de lots"],
          ["ref_cons", "Concession de rattachement"], ["proces_agt", "Processus d'aménagement"], ["conformit", "Conformité"], ["nom_ferm", "Société fermière"], ["date_attri", "Date d'attribution"],
          ["nom_cfad", "CFAD"], ["nbr_permis", "Nombre de permis"], ["date_sgnt", "Signature du décret"], ["date_amgt", "Date d'aménagement"], ["date_d_rev", "Dernière révision du PA"],
          ["nbr_rev_pa", "Révisions du PA"], ["annee_ouv", "Année d'ouverture"], ["annee_fem", "Année de fermeture"], ["type_cert", "Certification"], ["bur_certif", "Bureau de certification"],
          ["cert_o_lgl", "Certification d'origine légale"], ["certif_tra", "Certification traçabilité"], ["etu_imp_env", "Étude d'impact"], ["observatn", "Observations"]] }

// ---------- core values ---------------------------------------------------------------------
var f = $feature
var iso = f.iso3
var name = DefaultValue(f.name, DefaultValue(f.reference, "Sans nom"))
var subType = cat(SUBTYPE, f.sub_type_std, DefaultValue(f.sub_type_raw, "Titre forestier"))
var st = cat(STATUS, f.status_std, null); var mg = cat(MGMT, f.status_mgmt_std, null)

// ---------- banner ----------------------------------------------------------------------------
var banner = "<div style=\"background:" + ACCENT + "; color:white; padding:10px 12px; border-radius:6px 6px 0 0; margin:0 0 10px 0;\">"
  + "<div style=\"font-size:15px; font-weight:700;\">" + txt(name) + "</div>"
  + "<div style=\"font-size:11px; opacity:0.9; margin-top:2px;\">" + cat(FLAG, iso, "") + " " + txt(f.country) + IIf(!isBlank(f.holder), " — " + txt(f.holder), "") + "</div>"
  + "<div style=\"font-size:10px; opacity:0.9; margin-top:4px; text-transform:uppercase; letter-spacing:0.8px;\">" + txt(subType) + IIf(!isBlank(f.reference) && f.reference != f.name, " · réf. " + txt(f.reference), "") + "</div></div>"

// ---------- chips ------------------------------------------------------------------------------
var chips = ""
if (!IsEmpty(st)) { chips += chip(st[0], st[1], st[2]) }
if (!IsEmpty(mg)) { chips += chip(mg[0], mg[1], mg[2]) }
if (!isBlank(f.cert_type)) { chips += chip("&#127942; Certifié " + txt(f.cert_type), "#e0f7fa", "#00838f") }
if (!isBlank(f.legality_cert)) { chips += chip("&#9878; Légalité " + txt(f.legality_cert), "#ede7f6", "#5e35b1") }
if (f.country_check == "mismatch") { chips += chip("&#9888; Pays incohérent", "#fbe9e7", "#d84315") }
if (f.retired == 1) { chips += chip("Retiré de la source", "#ffebee", "#c62828") }
var chipsHtml = IIf(chips == "", "", "<div style=\"display:flex; gap:6px; margin-bottom:10px; flex-wrap:wrap;\">" + chips + "</div>")

// ---------- breadcrumb ---------------------------------------------------------------------------
var crumbs = txt(f.country)
if (!isBlank(f.province)) { crumbs += " › " + txt(f.province) }
if (!isBlank(f.admin2)) { crumbs += " › " + txt(f.admin2) }
var crumbHtml = "<div style=\"background:#efebe9; border-radius:6px; padding:7px 8px; margin-bottom:10px; font-size:12px; color:" + ACCENT + "; font-weight:500;\">&#128205; " + crumbs + "</div>"

// ---------- related data (zoning + documents) ----------------------------------------------------
var uid = f.src_uid
var zoneRows = null; var nZones = 0; var totZones = 0
var zs = fsGet(NAME_ZONING, ID_ZONING, ["parent_uid", "zone_type_std", "area_calc_ha", "retired"], false)
if (!IsEmpty(zs)) {
  var mine = Filter(zs, "parent_uid = @uid AND retired = 0")
  nZones = Count(mine)
  if (nZones > 0) {
    zoneRows = OrderBy(GroupBy(mine, ["zone_type_std"], [{ name: "n", expression: "1", statistic: "COUNT" }, { name: "ha", expression: "area_calc_ha", statistic: "SUM" }]), "ha DESC")
    for (var z in zoneRows) { totZones += DefaultValue(z.ha, 0) }
  }
}
var docs = null; var nDocs = 0
var dt = fsGet(NAME_DOCS, ID_DOCS, ["parent_uid", "title", "category_std", "url", "size_bytes", "date_doc", "file_name", "retired"], false)
if (!IsEmpty(dt)) {
  docs = OrderBy(Filter(dt, "parent_uid = @uid AND retired = 0"), "category_std ASC, date_doc DESC, title ASC")
  nDocs = Count(docs)
}
if (nDocs == 0 && !isBlank(f.doc_count)) { nDocs = f.doc_count }

// ---------- KPI tiles ------------------------------------------------------------------------------
var area = f.area_adm_ha
var areaLbl = "Superficie administrative"
if (isBlank(area) || area <= 0) { area = f.area_sig_ha; areaLbl = "Superficie SIG" }
if (isBlank(area) || area <= 0) { area = f.area_calc_ha; areaLbl = "Superficie calculée" }
var tiles = "<div style=\"display:flex; gap:6px; margin-bottom:10px; flex-wrap:wrap;\">"
  + tile(DefaultValue(haTxt(area), "—"), areaLbl, ACCENT)
  + tile(IIf(nZones > 0, Text(nZones), "—"), "Séries d'aménagement", "#2e7d32")
  + tile(IIf(nDocs > 0, Text(nDocs), "—"), "Documents", "#1565c0")
  + tile(IIf(IsEmpty(f.date_attr), "—", Text(Date(f.date_attr), "YYYY")), "Attribution", "#607d8b")
  + "</div>"

// ---------- timeline (attribution -> expiry) -----------------------------------------------------------
var timeline = ""
if (!IsEmpty(f.date_attr) && !IsEmpty(f.date_expiry)) {
  var startMs = Number(Date(f.date_attr)); var endMs = Number(Date(f.date_expiry)); var nowMs = Number(Now())
  if (endMs > startMs) {
    var progress = Round(((nowMs - startMs) / (endMs - startMs)) * 100, 0)
    if (progress < 0) { progress = 0 }
    if (progress > 100) { progress = 100 }
    var daysLeft = Round((endMs - nowMs) / 86400000, 0)
    var remaining = "Titre échu"
    if (daysLeft > 0) { remaining = Text(Round(daysLeft / 365.25, 1)) + " an(s) restant(s)" }
    var pColor = "#4caf50"; if (progress > 75) { pColor = "#ff9800" }; if (progress >= 100) { pColor = "#f44336" }
    timeline = "<div style=\"background:#f5f9f9; border-radius:6px; padding:8px 12px; margin-bottom:10px; border:1px solid #e0e0e0;\">"
      + "<div style=\"display:flex; justify-content:space-between; font-size:11px; color:#666; margin-bottom:4px;\"><span>" + dateTxt(f.date_attr) + "</span>"
      + "<span style=\"font-weight:700; color:" + pColor + ";\">" + progress + " % de la durée écoulée</span><span>" + dateTxt(f.date_expiry) + "</span></div>"
      + "<div style=\"background:#e0e0e0; border-radius:6px; height:10px; width:100%; overflow:hidden;\"><div style=\"background:" + pColor + "; height:10px; width:" + progress + "%; border-radius:6px;\"></div></div>"
      + "<div style=\"text-align:center; font-size:10px; color:#888; margin-top:4px;\">" + remaining + "</div></div>"
  }
}

// ---------- zoning donut --------------------------------------------------------------------------------
var zoningCard = ""
if (nZones > 0 && totZones > 0) {
  var grad = ""; var cum = 0; var legend = ""
  for (var z in zoneRows) {
    var zz = cat(ZONE, z.zone_type_std, ["Autre", "#607d8b"])
    var share = Round(100 * DefaultValue(z.ha, 0) / totZones, 1)
    var start = cum; cum = Round(cum + share, 1)
    if (grad != "") { grad += ", " }
    grad += zz[1] + " " + start + "% " + cum + "%"
    legend += "<div style=\"display:flex; justify-content:space-between; font-size:11px; margin-bottom:3px;\">"
      + "<span><span style=\"display:inline-block; width:10px; height:10px; background:" + zz[1] + "; border-radius:2px; margin-right:6px;\"></span>" + txt(zz[0]) + " <span style=\"color:#999;\">(" + Text(z.n) + ")</span></span>"
      + "<span style=\"font-weight:700; color:" + zz[1] + ";\">" + haTxt(z.ha) + " · " + share + " %</span></div>"
  }
  if (cum < 100) { grad += ", #e0e0e0 " + cum + "% 100%" }
  zoningCard = "<div style=\"background:#f7fafa; border-left:4px solid #2e7d32; border-radius:4px; margin-bottom:10px; padding:8px 10px 8px 8px;\">"
    + "<div style=\"font-size:10px; font-weight:700; color:#2e7d32; text-transform:uppercase; letter-spacing:0.8px; margin-bottom:8px;\">Séries d'aménagement · " + Text(nZones) + " zone(s)</div>"
    + "<div style=\"display:flex; align-items:center; gap:14px;\">"
    + "<div style=\"width:84px; height:84px; flex-shrink:0; border-radius:50%; background:conic-gradient(" + grad + "); display:flex; align-items:center; justify-content:center;\">"
    + "<div style=\"width:54px; height:54px; background:white; border-radius:50%; display:flex; align-items:center; justify-content:center; text-align:center;\">"
    + "<div><div style=\"font-size:11px; font-weight:700; color:#2e7d32;\">" + Text(Round(totZones / 1000, 1)) + "k</div><div style=\"font-size:8px; color:#888;\">ha zonés</div></div></div></div>"
    + "<div style=\"flex:1;\">" + legend + "</div></div></div>"
}

// ---------- area comparison -------------------------------------------------------------------------------
var maxA = 0
var arrA = [f.area_adm_ha, f.area_sig_ha, f.area_calc_ha, f.taxable_area_ha, totZones]
for (var ai in arrA) { var av = arrA[ai]; if (!isBlank(av) && av > maxA) { maxA = av } }
var areaCard = section("Comparaison des superficies", "#1565c0",
    bar("Administrative (titre)", f.area_adm_ha, "#607d8b", maxA)
  + bar("SIG (source nationale)", f.area_sig_ha, "#1565c0", maxA)
  + bar("Calculée (géodésique)", f.area_calc_ha, ACCENT, maxA)
  + bar("Taxable", f.taxable_area_ha, "#ff9800", maxA)
  + bar("Séries d'aménagement", totZones, "#2e7d32", maxA))

// ---------- documents (name + link for each) --------------------------------------------------------------
var docsCard = ""
if (!IsEmpty(docs) && Count(docs) > 0) {
  var lastCat = ""; var list = ""; var k = 0
  for (var d in docs) {
    k += 1
    if (k > 60) { break }
    if (d.category_std != lastCat) {
      var cc = cat(DOCCAT, d.category_std, ["Documents", "#78909c"])
      list += "<div style=\"font-size:10px; font-weight:700; color:" + cc[1] + "; text-transform:uppercase; letter-spacing:0.6px; margin:8px 0 4px 0;\">" + cc[0] + "</div>"
      lastCat = d.category_std
    }
    var meta = ""
    if (!isBlank(d.size_bytes)) { meta += Text(Round(d.size_bytes / 1048576, 1)) + " Mo" }
    if (!IsEmpty(d.date_doc)) { meta += IIf(meta == "", "", " · ") + Text(Date(d.date_doc), "YYYY") }
    list += "<div style=\"display:flex; align-items:center; gap:8px; background:#fff; border:1px solid #e0e0e0; border-radius:6px; padding:6px 8px; margin-bottom:4px;\">"
      + "<div style=\"font-size:16px;\">" + docIcon(d.file_name) + "</div>"
      + "<div style=\"flex:1; min-width:0;\"><div style=\"font-size:12px; font-weight:600; color:#1a1a2e;\">" + txt(DefaultValue(d.title, d.file_name)) + "</div>"
      + "<div style=\"font-size:10px; color:#888;\">" + txt(DefaultValue(d.file_name, "")) + IIf(meta == "", "", " · " + meta) + "</div></div>"
      + "<a href=\"" + d.url + "\" target=\"_blank\" style=\"background:#1565c0; color:#fff; padding:4px 10px; border-radius:6px; font-size:11px; font-weight:700; text-decoration:none; white-space:nowrap;\">Ouvrir &#8599;</a></div>"
  }
  if (Count(docs) > 60) { list += "<div style=\"font-size:10px; color:#999;\">… " + Text(Count(docs) - 60) + " autre(s) document(s) non affiché(s)</div>" }
  docsCard = section("Documents · " + Text(Count(docs)), "#1565c0", list)
} else if (nDocs > 0) {
  docsCard = section("Documents · " + Text(nDocs), "#1565c0", "<div style=\"font-size:11px; color:#888;\">" + Text(nDocs) + " document(s) référencé(s). Ajoutez la table <b>CB_Documents</b> à la carte (ou renseignez ITEM_ID) pour afficher les liens.</div>")
}

// ---------- sections ----------------------------------------------------------------------------------------
var actorRows = row("Attributaire", txt(f.holder)) + row("Exploitant", txt(f.operator)) + row("Origine du capital", txt(f.capital_origin))
  + row("Unité de rattachement", txt(f.parent_ref)) + row("Statut (source)", txt(f.status_raw)) + row("Aménagement (source)", txt(f.status_mgmt_raw))
var dateRows = row("Attribution", dateTxt(f.date_attr)) + row("Convention provisoire", dateTxt(f.date_conv_prov)) + row("Convention définitive", dateTxt(f.date_conv_def))
  + row("Plan d'aménagement", dateTxt(f.date_plan)) + row("Échéance", dateTxt(f.date_expiry))
  + row("Certification", IIf(isBlank(f.cert_type), "", txt(f.cert_type) + IIf(isBlank(f.cert_body), "", " (" + txt(f.cert_body) + ")") + IIf(IsEmpty(f.date_cert), "", " · " + dateTxt(f.date_cert))))
  + row("Certificat de légalité", txt(f.legality_cert))

var native = Dictionary()
if (!isBlank(f.src_attrs_json)) { native = Dictionary(f.src_attrs_json) }
var fields = cat(NATIVE, iso, [])
var nativeRows = ""
for (var i in fields) {
  var key = fields[i][0]
  if (HasKey(native, key) && !isBlank(native[key])) {
    var v = native[key]
    if (TypeOf(v) == "Number" && v > 100000000000) { v = dateTxt(v) }
    if (TypeOf(v) == "Boolean") { v = IIf(v, "oui", "non") }
    nativeRows += row(fields[i][1], txt(v))
  }
}

var footer = "<div style=\"text-align:center; font-size:10px; color:#aaa; margin-top:10px; padding-top:8px; border-top:1px solid #eee;\">"
  + "Source : " + txt(f.src_layer) + IIf(isBlank(f.src_vintage), "", " (" + txt(f.src_vintage) + ")")
  + IIf(IsEmpty(f.src_last_edit), "", " &nbsp;|&nbsp; édition source " + dateTxt(f.src_last_edit)) + IIf(IsEmpty(f.loaded_at), "", " &nbsp;|&nbsp; chargé le " + dateTxt(f.loaded_at))
  + " &nbsp;|&nbsp; situation " + txt(f.situation) + "</div>"

// ---------- build ----------------------------------------------------------------------------------------------
var popup = "<div style=\"font-family:Segoe UI,sans-serif; font-size:13px; color:#1a1a2e;\">"
  + banner + chipsHtml + crumbHtml + tiles + timeline + zoningCard + areaCard
  + section("Titre et acteurs", ACCENT, table(actorRows))
  + section("Dates et certification", "#607d8b", table(dateRows))
  + section("Attributs nationaux · " + txt(f.country), "#00838f", table(nativeRows))
  + docsCard + footer + "</div>"

return { type: "text", text: popup }

// ============================================================
//  Zoning popup — one expression for CB_Concession_Zoning (1), CB_Community_Forest_Zoning (3)
//  and CB_Local_Territory_Zoning (5); the parent layer is derived from $feature.layer.
//  Reads the parent layer and the sibling zones FROM THE WEB MAP by name (or SOURCE = "portal").
// ============================================================
Expects($feature, "*")

var SOURCE     = "map"
var PORTAL_URL = "https://geosmarthosting.undp.org/portal"
var ITEM_ID    = "PASTE_ITEM_ID_HERE"
var PARENT = { "concession_zoning": ["Logging concessions - Limits", 0, "Concession / titre forestier", "#5d4037"],
               "community_forest_zoning": ["CB_Community_Forests", 2, "Forêt communautaire", "#1b5e20"],
               "local_territory_zoning": ["CB_Local_Territories", 4, "Terroir villageois (PSAT)", "#37474f"] }
var SELF = { "concession_zoning": ["CB_Concession_Zoning", 1], "community_forest_zoning": ["CB_Community_Forest_Zoning", 3], "local_territory_zoning": ["CB_Local_Territory_Zoning", 5] }

function isBlank(x) { return IsEmpty(x) || Text(x) == "" || Text(x) == "null" }
function txt(x) { if (isBlank(x)) { return "" } var s = Text(x); s = Replace(s, "&", "&amp;"); s = Replace(s, "<", "&lt;"); return Replace(s, ">", "&gt;") }
function haTxt(x) { if (isBlank(x)) { return "" } var n = Number(x); if (IsNan(n) || n <= 0) { return "" } return Text(Round(n, 0), "#,###") + " ha" }
function dateTxt(x) { if (IsEmpty(x)) { return "" } return Text(Date(x), "DD MMM YYYY") }
function cat(dict, key, dflt) { if (!isBlank(key) && HasKey(dict, key)) { return dict[key] } return dflt }
function fsGet(name, id, fields, geom) {
  if (SOURCE == "portal" && ITEM_ID != "PASTE_ITEM_ID_HERE") { return FeatureSetByPortalItem(Portal(PORTAL_URL), ITEM_ID, id, fields, geom) }
  return FeatureSetByName($map, name, fields, geom)
}
function row(label, value) {
  if (isBlank(value)) { return "" }
  return "<tr><td style=\"color:#666; width:44%; padding:4px 6px 4px 0; font-size:12px; vertical-align:top;\">" + label + "</td><td style=\"font-weight:600; font-size:12px; padding:4px 0; vertical-align:top;\">" + value + "</td></tr>"
}
function table(rows) { if (isBlank(rows)) { return "" } return "<table style=\"width:100%; border-collapse:collapse;\">" + rows + "</table>" }
function section(title, accent, body) {
  if (isBlank(body)) { return "" }
  return "<div style=\"background:#f7fafa; border-left:4px solid " + accent + "; border-radius:4px; margin-bottom:10px; padding:8px 10px 8px 8px;\">"
       + "<div style=\"font-size:10px; font-weight:700; color:" + accent + "; text-transform:uppercase; letter-spacing:0.8px; margin-bottom:8px;\">" + title + "</div>" + body + "</div>"
}
function chip(label, bg, fg) { return "<div style=\"background:" + bg + "; color:" + fg + "; padding:5px 10px; border-radius:6px; font-size:11px; font-weight:700;\">" + label + "</div>" }
function tile(value, label, color) {
  return "<div style=\"flex:1 1 30%; min-width:80px; background:#f5f9f9; border:1px solid #e0e0e0; border-radius:6px; padding:8px 4px; text-align:center;\">"
       + "<div style=\"font-size:16px; font-weight:700; color:" + color + ";\">" + value + "</div><div style=\"font-size:9px; color:#666; text-transform:uppercase; letter-spacing:0.5px; margin-top:2px;\">" + label + "</div></div>"
}

var ZONE = { "production": ["Production", "#c98a2b", "Exploitation forestière / production ligneuse"], "conservation": ["Conservation", "#2e7d32", "Conservation de la biodiversité"],
  "protection": ["Protection", "#00695c", "Protection (berges, pentes, sites sacrés, aires protégées)"], "community_development": ["Développement rural / communautaire", "#a0522d", "Usages des communautés (chasse, pêche, cueillette, PFNL)"],
  "agriculture": ["Agriculture", "#d4b106", "Cultures, élevage, agroforesterie, pisciculture"], "habitat": ["Habitat", "#8d6e63", "Villages, campements"],
  "savanna_protection": ["Mise en défens / reboisement", "#7cb342", "Savanes mises en défens, reboisement, RNA"], "concession": ["Zone concédée", "#5d4037", "Concessions et titres tiers"],
  "community_forest": ["Forêt communautaire", "#43a047", "CFCL / forêt des communautés locales"], "conflict": ["Zone conflictuelle", "#d32f2f", "Litiges"],
  "research": ["Recherche", "#7e57c2", "Recherche scientifique"], "unclassified": ["Non classée", "#bdbdbd", "Zonage non renseigné dans la source"], "other": ["Autre", "#607d8b", "Autre affectation"] }
var STATUS = { "attributed": ["Attribuée / validée", "#e8f5e9", "#2e7d32"], "provisional": ["Provisoire", "#fff8e1", "#ff8f00"], "final": ["Définitive", "#e8f5e9", "#1b5e20"], "in_process": ["En cours", "#e3f2fd", "#1565c0"],
  "not_attributed": ["Non attribuée", "#eceff1", "#607d8b"], "rejected": ["Rejetée", "#ffebee", "#c62828"], "expired": ["Expirée", "#efebe9", "#6d4c41"], "unknown": ["Non renseigné", "#eceff1", "#546e7a"] }
var FLAG = { "CMR": "🇨🇲", "CAF": "🇨🇫", "COD": "🇨🇩", "COG": "🇨🇬", "GNQ": "🇬🇶", "GAB": "🇬🇦" }

var f = $feature
var lay = DefaultValue(f.layer, "concession_zoning")
var P = cat(PARENT, lay, ["Logging concessions - Limits", 0, "Unité parente", "#5d4037"])
var S = cat(SELF, lay, ["CB_Concession_Zoning", 1])
var z = cat(ZONE, f.zone_type_std, ["Autre", "#607d8b", ""])
var ACCENT = z[1]
var title = DefaultValue(f.zone_name, DefaultValue(f.zone_type_raw, z[0]))

var banner = "<div style=\"background:" + ACCENT + "; color:white; padding:10px 12px; border-radius:6px 6px 0 0; margin:0 0 10px 0;\">"
  + "<div style=\"font-size:15px; font-weight:700;\">" + txt(title) + "</div>"
  + "<div style=\"font-size:11px; opacity:0.9; margin-top:2px;\">" + cat(FLAG, f.iso3, "") + " " + txt(f.country) + IIf(!isBlank(f.parent_name), " — " + txt(f.parent_name), "") + "</div>"
  + "<div style=\"font-size:10px; opacity:0.9; margin-top:4px; text-transform:uppercase; letter-spacing:0.8px;\">" + txt(z[0]) + " · " + txt(f.sub_type_raw) + "</div></div>"

var st = cat(STATUS, f.status_std, null)
var chips = chip(txt(z[0]), "#fff", ACCENT)
if (!IsEmpty(st)) { chips += chip(st[0], st[1], st[2]) }
if (f.geom_quality == "bbox") { chips += chip("&#9888; Emprise approximative", "#fbe9e7", "#d84315") }
if (isBlank(f.parent_uid)) { chips += chip("Unité parente non identifiée", "#eceff1", "#607d8b") }
if (f.retired == 1) { chips += chip("Retiré de la source", "#ffebee", "#c62828") }
var chipsHtml = "<div style=\"display:flex; gap:6px; margin-bottom:10px; flex-wrap:wrap;\">" + chips + "</div>"

var crumbs = txt(f.country)
if (!isBlank(f.province)) { crumbs += " › " + txt(f.province) }
if (!isBlank(f.admin2)) { crumbs += " › " + txt(f.admin2) }
if (!isBlank(f.admin3)) { crumbs += " › " + txt(f.admin3) }
if (!isBlank(f.admin4)) { crumbs += " › " + txt(f.admin4) }
var crumbHtml = "<div style=\"background:#f1f8e9; border-radius:6px; padding:7px 8px; margin-bottom:10px; font-size:12px; color:#33691e; font-weight:500;\">&#128205; " + crumbs + "</div>"

// ---------- parent and siblings ---------------------------------------------------------------------
var puid = f.parent_uid
var parent = null; var sib = null; var nSib = 0; var totSib = 0; var rows = null
if (!isBlank(puid)) {
  var pfs = fsGet(P[0], P[1], ["src_uid", "name", "reference", "holder", "community", "status_std", "area_calc_ha", "area_adm_ha", "sub_type_raw", "doc_count"], false)
  if (!IsEmpty(pfs)) { parent = First(Filter(pfs, "src_uid = @puid")) }
  var zfs = fsGet(S[0], S[1], ["parent_uid", "zone_type_std", "area_calc_ha", "retired"], false)
  if (!IsEmpty(zfs)) {
    sib = Filter(zfs, "parent_uid = @puid AND retired = 0")
    nSib = Count(sib)
    if (nSib > 0) {
      rows = OrderBy(GroupBy(sib, ["zone_type_std"], [{ name: "n", expression: "1", statistic: "COUNT" }, { name: "ha", expression: "area_calc_ha", statistic: "SUM" }]), "ha DESC")
      for (var r in rows) { totSib += DefaultValue(r.ha, 0) }
    }
  }
}

var area = f.area_sig_ha
if (isBlank(area) || area <= 0) { area = f.area_adm_ha }
if (isBlank(area) || area <= 0) { area = f.area_calc_ha }
var share = IIf(totSib > 0 && !isBlank(f.area_calc_ha), Round(100 * f.area_calc_ha / totSib, 1), null)
var tiles = "<div style=\"display:flex; gap:6px; margin-bottom:10px; flex-wrap:wrap;\">"
  + tile(DefaultValue(haTxt(area), "—"), "Superficie de la zone", ACCENT)
  + tile(IIf(IsEmpty(share), "—", Text(share) + " %"), "Part de l'unité", "#2e7d32")
  + tile(IIf(nSib > 0, Text(nSib), "—"), "Zones dans l'unité", "#607d8b") + "</div>"

var meaning = "<div style=\"font-size:11px; color:#4b5563; margin:-4px 0 10px 0;\">" + txt(z[2]) + "</div>"

// ---------- donut of the unit ---------------------------------------------------------------------------
var donut = ""
if (nSib > 1 && totSib > 0) {
  var grad = ""; var cum = 0; var legend = ""
  for (var r in rows) {
    var zz = cat(ZONE, r.zone_type_std, ["Autre", "#607d8b", ""])
    var sh = Round(100 * DefaultValue(r.ha, 0) / totSib, 1)
    var start = cum; cum = Round(cum + sh, 1)
    if (grad != "") { grad += ", " }
    grad += zz[1] + " " + start + "% " + cum + "%"
    var me = IIf(r.zone_type_std == f.zone_type_std, " &#9664;", "")
    legend += "<div style=\"display:flex; justify-content:space-between; font-size:11px; margin-bottom:3px;\"><span><span style=\"display:inline-block; width:10px; height:10px; background:" + zz[1] + "; border-radius:2px; margin-right:6px;\"></span>"
      + txt(zz[0]) + " <span style=\"color:#999;\">(" + Text(r.n) + ")</span>" + me + "</span><span style=\"font-weight:700; color:" + zz[1] + ";\">" + haTxt(r.ha) + " · " + sh + " %</span></div>"
  }
  if (cum < 100) { grad += ", #e0e0e0 " + cum + "% 100%" }
  donut = "<div style=\"background:#f7fafa; border-left:4px solid " + P[3] + "; border-radius:4px; margin-bottom:10px; padding:8px 10px 8px 8px;\">"
    + "<div style=\"font-size:10px; font-weight:700; color:" + P[3] + "; text-transform:uppercase; letter-spacing:0.8px; margin-bottom:8px;\">Zonage de l'unité · " + Text(nSib) + " zones · " + haTxt(totSib) + "</div>"
    + "<div style=\"display:flex; align-items:center; gap:14px;\"><div style=\"width:84px; height:84px; flex-shrink:0; border-radius:50%; background:conic-gradient(" + grad + "); display:flex; align-items:center; justify-content:center;\">"
    + "<div style=\"width:54px; height:54px; background:white; border-radius:50%; display:flex; align-items:center; justify-content:center; text-align:center;\"><div><div style=\"font-size:11px; font-weight:700; color:" + ACCENT + ";\">" + IIf(IsEmpty(share), "", Text(share) + " %") + "</div><div style=\"font-size:8px; color:#888;\">cette zone</div></div></div></div>"
    + "<div style=\"flex:1;\">" + legend + "</div></div></div>"
}

// ---------- parent card ------------------------------------------------------------------------------------
var parentCard = ""
if (!IsEmpty(parent)) {
  var pst = cat(STATUS, parent.status_std, null)
  var prow = row("Nom", "<b>" + txt(DefaultValue(parent.name, parent.reference)) + "</b>" + IIf(!isBlank(parent.reference) && parent.reference != parent.name, " · " + txt(parent.reference), ""))
    + row("Type", txt(parent.sub_type_raw)) + row("Attributaire / communauté", txt(DefaultValue(parent.holder, parent.community)))
    + row("Statut", IIf(IsEmpty(pst), "", "<span style=\"background:" + pst[1] + "; color:" + pst[2] + "; padding:2px 8px; border-radius:6px; font-size:11px; font-weight:700;\">" + pst[0] + "</span>"))
    + row("Superficie", haTxt(IIf(isBlank(parent.area_adm_ha), parent.area_calc_ha, parent.area_adm_ha)))
    + row("Documents", IIf(!isBlank(parent.doc_count) && parent.doc_count > 0, Text(parent.doc_count) + " document(s) — voir la fiche de l'unité", ""))
  parentCard = section(P[2], P[3], table(prow))
} else if (isBlank(f.parent_uid)) {
  parentCard = section(P[2], "#9e9e9e", "<div style=\"font-size:11px; color:#888;\">Unité parente non identifiée" + IIf(isBlank(f.parent_ref), "", " (référence source : " + txt(f.parent_ref) + ")") + ".</div>")
}

var zoneRows = row("Affectation (source)", txt(f.zone_type_raw)) + row("Raison / usage", txt(f.zone_reason)) + row("Code", txt(f.zone_code)) + row("Statut (source)", txt(f.status_raw))
  + row("Exploitant", txt(f.operator)) + row("Superficie SIG (source)", haTxt(f.area_sig_ha)) + row("Superficie administrative", haTxt(f.area_adm_ha)) + row("Superficie calculée", haTxt(f.area_calc_ha))
  + row("Date du plan", dateTxt(f.date_plan)) + row("Programme", txt(f.programme)) + row("Financement / agence", txt(DefaultValue(f.funder, "")) + IIf(isBlank(f.agency), "", " · " + txt(f.agency)))
  + row("Partenaire", txt(f.partner)) + row("Année de référence", IIf(isBlank(f.year_ref), "", Text(f.year_ref)))

var footer = "<div style=\"text-align:center; font-size:10px; color:#aaa; margin-top:10px; padding-top:8px; border-top:1px solid #eee;\">Source : " + txt(f.src_layer)
  + IIf(isBlank(f.src_file), "", " · " + txt(f.src_file)) + IIf(isBlank(f.src_vintage), "", " (" + txt(f.src_vintage) + ")") + IIf(IsEmpty(f.loaded_at), "", " &nbsp;|&nbsp; chargé le " + dateTxt(f.loaded_at))
  + " &nbsp;|&nbsp; situation " + txt(f.situation) + "</div>"

var popup = "<div style=\"font-family:Segoe UI,sans-serif; font-size:13px; color:#1a1a2e;\">" + banner + chipsHtml + meaning + crumbHtml + tiles + donut + parentCard
  + section("Zone", ACCENT, table(zoneRows)) + footer + "</div>"
return { type: "text", text: popup }

renderer.valueExpression:
// =====================================================================================
//  Symbology · unique values on an Arcade expression, for the three zoning layers
//  (CB_Concession_Zoning, CB_Community_Forest_Zoning, CB_Local_Territory_Zoning).
//  Map Viewer: Styles > + Expression > paste > Types (unique symbols).
//  Pro: Symbology > Unique Values > Set an expression.
//  Returns the display label; apply the colours listed in README_arcade.md (same palette as the popups).
// =====================================================================================
var LABEL = {
  'production':            'Production (exploitation ligneuse)',
  'conservation':          'Conservation',
  'protection':            'Protection',
  'community_development': 'Développement rural / communautaire',
  'agriculture':           'Agriculture et agroforesterie',
  'habitat':               'Habitat',
  'savanna_protection':    'Mise en défens / reboisement',
  'concession':            'Zone concédée (titres tiers)',
  'community_forest':      'Forêt communautaire',
  'conflict':              'Zone conflictuelle',
  'research':              'Recherche',
  'unclassified':          'Non classée',
  'other':                 'Autre'
};
var k = $feature.zone_type_std;
if (IsEmpty(k) || !HasKey(LABEL, k)) { return 'Non classée'; }
if ($feature.retired == 1) { return 'Retiré de la source'; }
return LABEL[k];

expressionInfo.expression:
// ============================================================
//  CB_Local_Territories (PSAT terroirs villageois) — popup content (Arcade element)
//  Reads "CB_Local_Territory_Zoning" from the web map by name (or SOURCE = "portal" + ITEM_ID).
// ============================================================
Expects($feature, "*")

var SOURCE      = "map"
var PORTAL_URL  = "https://geosmarthosting.undp.org/portal"
var ITEM_ID     = "PASTE_ITEM_ID_HERE"
var NAME_ZONING = "Local territories - Zoning";  var ID_ZONING = 5
var ACCENT      = "#37474f"

function isBlank(x) { return IsEmpty(x) || Text(x) == "" || Text(x) == "null" }
function txt(x) { if (isBlank(x)) { return "" } var s = Text(x); s = Replace(s, "&", "&amp;"); s = Replace(s, "<", "&lt;"); return Replace(s, ">", "&gt;") }
function haTxt(x) { if (isBlank(x)) { return "" } var n = Number(x); if (IsNan(n) || n <= 0) { return "" } return Text(Round(n, 0), "#,###") + " ha" }
function dateTxt(x) { if (IsEmpty(x)) { return "" } return Text(Date(x), "DD MMM YYYY") }
function cat(dict, key, dflt) { if (!isBlank(key) && HasKey(dict, key)) { return dict[key] } return dflt }
function fsGet(name, id, fields, geom) {
  if (SOURCE == "portal" && ITEM_ID != "PASTE_ITEM_ID_HERE") { return FeatureSetByPortalItem(Portal(PORTAL_URL), ITEM_ID, id, fields, geom) }
  return FeatureSetByName($map, name, fields, geom)
}
function row(label, value) {
  if (isBlank(value)) { return "" }
  return "<tr><td style=\"color:#666; width:44%; padding:4px 6px 4px 0; font-size:12px; vertical-align:top;\">" + label + "</td><td style=\"font-weight:600; font-size:12px; padding:4px 0; vertical-align:top;\">" + value + "</td></tr>"
}
function table(rows) { if (isBlank(rows)) { return "" } return "<table style=\"width:100%; border-collapse:collapse;\">" + rows + "</table>" }
function section(title, accent, body) {
  if (isBlank(body)) { return "" }
  return "<div style=\"background:#f7fafa; border-left:4px solid " + accent + "; border-radius:4px; margin-bottom:10px; padding:8px 10px 8px 8px;\">"
       + "<div style=\"font-size:10px; font-weight:700; color:" + accent + "; text-transform:uppercase; letter-spacing:0.8px; margin-bottom:8px;\">" + title + "</div>" + body + "</div>"
}
function chip(label, bg, fg) { return "<div style=\"background:" + bg + "; color:" + fg + "; padding:5px 10px; border-radius:6px; font-size:11px; font-weight:700;\">" + label + "</div>" }
function tile(value, label, color) {
  return "<div style=\"flex:1 1 30%; min-width:80px; background:#f5f9f9; border:1px solid #e0e0e0; border-radius:6px; padding:8px 4px; text-align:center;\">"
       + "<div style=\"font-size:16px; font-weight:700; color:" + color + ";\">" + value + "</div><div style=\"font-size:9px; color:#666; text-transform:uppercase; letter-spacing:0.5px; margin-top:2px;\">" + label + "</div></div>"
}
function distBar(label, value, color, maxv) {
  if (isBlank(value) || value <= 0 || maxv <= 0) { return "" }
  var pct = Round((value / maxv) * 100, 0)
  return "<div style=\"margin-bottom:6px;\"><div style=\"display:flex; justify-content:space-between; font-size:10px; color:#555; margin-bottom:2px;\"><span style=\"font-weight:600;\">" + label + "</span>"
       + "<span style=\"font-weight:700; color:" + color + ";\">" + haTxt(value) + " (" + pct + " %)</span></div>"
       + "<div style=\"background:#e0e0e0; border-radius:4px; height:12px; width:100%; overflow:hidden;\"><div style=\"background:" + color + "; height:12px; width:" + pct + "%; border-radius:4px;\"></div></div></div>"
}

var ZONE = { "production": ["Production", "#c98a2b"], "conservation": ["Conservation", "#2e7d32"], "protection": ["Protection", "#00695c"], "community_development": ["Développement rural", "#a0522d"],
  "agriculture": ["Agriculture", "#d4b106"], "habitat": ["Habitat", "#8d6e63"], "savanna_protection": ["Mise en défens / reboisement", "#7cb342"], "concession": ["Zone concédée", "#5d4037"],
  "community_forest": ["Forêt communautaire", "#43a047"], "conflict": ["Zone conflictuelle", "#d32f2f"], "research": ["Recherche", "#7e57c2"], "unclassified": ["Non classée", "#bdbdbd"], "other": ["Autre", "#607d8b"] }
var STATUS = { "attributed": ["Validé / reconnu", "#e8f5e9", "#2e7d32"], "provisional": ["Provisoire", "#fff8e1", "#ff8f00"], "final": ["Définitif", "#e8f5e9", "#1b5e20"], "in_process": ["En cours", "#e3f2fd", "#1565c0"],
  "not_attributed": ["Non validé", "#eceff1", "#607d8b"], "rejected": ["Rejeté", "#ffebee", "#c62828"], "expired": ["Expiré", "#efebe9", "#6d4c41"], "unknown": ["Non renseigné", "#eceff1", "#546e7a"] }

var f = $feature
var name = DefaultValue(f.name, "Terroir sans nom")
var banner = "<div style=\"background:" + ACCENT + "; color:white; padding:10px 12px; border-radius:6px 6px 0 0; margin:0 0 10px 0;\">"
  + "<div style=\"font-size:15px; font-weight:700;\">" + txt(name) + "</div>"
  + "<div style=\"font-size:11px; opacity:0.9; margin-top:2px;\">🇨🇩 " + txt(f.country) + IIf(!isBlank(f.community) && f.community != name, " — groupement " + txt(f.community), "") + "</div>"
  + "<div style=\"font-size:10px; opacity:0.9; margin-top:4px; text-transform:uppercase; letter-spacing:0.8px;\">" + txt(DefaultValue(f.sub_type_raw, "Terroir villageois")) + IIf(isBlank(f.programme), "", " · " + txt(f.programme)) + "</div></div>"

var st = cat(STATUS, f.status_std, null)
var chips = ""
if (!IsEmpty(st)) { chips += chip(st[0], st[1], st[2]) }
if (!isBlank(f.year_ref)) { chips += chip("PSAT " + Text(f.year_ref), "#eceff1", "#455a64") }
if (!isBlank(f.cld) && Lower(f.cld) != "non") { chips += chip("&#127968; CLD " + txt(f.cld), "#e0f7fa", "#00838f") }
if (f.geom_quality == "bbox") { chips += chip("&#9888; Emprise approximative", "#fbe9e7", "#d84315") }
if (f.retired == 1) { chips += chip("Retiré de la source", "#ffebee", "#c62828") }
var chipsHtml = IIf(chips == "", "", "<div style=\"display:flex; gap:6px; margin-bottom:10px; flex-wrap:wrap;\">" + chips + "</div>")

var crumbs = txt(f.country)
if (!isBlank(f.province)) { crumbs += " › " + txt(f.province) }
if (!isBlank(f.admin2)) { crumbs += " › Territoire de " + txt(f.admin2) }
if (!isBlank(f.admin3)) { crumbs += " › Secteur " + txt(f.admin3) }
if (!isBlank(f.admin4)) { crumbs += " › Groupement " + txt(f.admin4) }
var crumbHtml = "<div style=\"background:#eceff1; border-radius:6px; padding:7px 8px; margin-bottom:10px; font-size:12px; color:" + ACCENT + "; font-weight:500;\">&#128205; " + crumbs + "</div>"

// ---------- zoning of the PSAT -----------------------------------------------------------------------
var uid = f.src_uid
var rows = null; var nZones = 0; var tot = 0; var mine = null
var zs = fsGet(NAME_ZONING, ID_ZONING, ["parent_uid", "zone_type_std", "zone_type_raw", "zone_reason", "area_calc_ha", "retired"], false)
if (!IsEmpty(zs)) {
  mine = Filter(zs, "parent_uid = @uid AND retired = 0")
  nZones = Count(mine)
  if (nZones > 0) {
    rows = OrderBy(GroupBy(mine, ["zone_type_std"], [{ name: "n", expression: "1", statistic: "COUNT" }, { name: "ha", expression: "area_calc_ha", statistic: "SUM" }]), "ha DESC")
    for (var r in rows) { tot += DefaultValue(r.ha, 0) }
  }
}

var area = IIf(isBlank(f.area_sig_ha) || f.area_sig_ha <= 0, f.area_calc_ha, f.area_sig_ha)
var tiles = "<div style=\"display:flex; gap:6px; margin-bottom:10px; flex-wrap:wrap;\">"
  + tile(DefaultValue(haTxt(area), "—"), "Superficie du terroir", ACCENT)
  + tile(IIf(nZones > 0, Text(nZones), "—"), "Zones du PSAT", "#2e7d32")
  + tile(IIf(tot > 0 && !isBlank(area) && area > 0, Text(Round(100 * tot / area, 0)) + " %", "—"), "Terroir zoné", "#1565c0")
  + tile(IIf(!isBlank(f.beneficiaries) && f.beneficiaries > 0, Text(f.beneficiaries, "#,###"), "—"), "Bénéficiaires", "#607d8b") + "</div>"

var zoningCard = ""
if (nZones > 0 && tot > 0) {
  var grad = ""; var cum = 0; var legend = ""
  for (var r in rows) {
    var zz = cat(ZONE, r.zone_type_std, ["Autre", "#607d8b"])
    var sh = Round(100 * DefaultValue(r.ha, 0) / tot, 1)
    var start = cum; cum = Round(cum + sh, 1)
    if (grad != "") { grad += ", " }
    grad += zz[1] + " " + start + "% " + cum + "%"
    legend += distBar(zz[0] + " (" + Text(r.n) + ")", r.ha, zz[1], tot)
  }
  if (cum < 100) { grad += ", #e0e0e0 " + cum + "% 100%" }
  zoningCard = "<div style=\"background:#f7fafa; border-left:4px solid #2e7d32; border-radius:4px; margin-bottom:10px; padding:8px 10px 8px 8px;\">"
    + "<div style=\"font-size:10px; font-weight:700; color:#2e7d32; text-transform:uppercase; letter-spacing:0.8px; margin-bottom:8px;\">Plan simple d'aménagement du territoire · " + Text(nZones) + " zones · " + haTxt(tot) + "</div>"
    + "<div style=\"display:flex; align-items:flex-start; gap:14px;\"><div style=\"width:90px; height:90px; flex-shrink:0; border-radius:50%; background:conic-gradient(" + grad + "); display:flex; align-items:center; justify-content:center;\">"
    + "<div style=\"width:58px; height:58px; background:white; border-radius:50%; display:flex; align-items:center; justify-content:center; text-align:center;\"><div><div style=\"font-size:12px; font-weight:700; color:#2e7d32;\">" + Text(nZones) + "</div><div style=\"font-size:8px; color:#888;\">zones</div></div></div></div>"
    + "<div style=\"flex:1;\">" + legend + "</div></div></div>"
  // declared usages (distinct reasons)
  var gr = OrderBy(GroupBy(mine, ["zone_type_raw", "zone_reason"], [{ name: "ha", expression: "area_calc_ha", statistic: "SUM" }]), "ha DESC")
  var det = ""
  for (var r in gr) {
    if (!isBlank(r.zone_reason)) { det += "<div style=\"font-size:11px; padding:3px 0; border-bottom:1px dashed #e0e0e0;\"><b>" + txt(r.zone_type_raw) + "</b> — " + txt(r.zone_reason) + " <span style=\"color:#999;\">(" + haTxt(r.ha) + ")</span></div>" }
  }
  zoningCard += section("Usages déclarés dans le PSAT", "#a0522d", det)
} else {
  zoningCard = section("Plan simple d'aménagement du territoire", "#9e9e9e", "<div style=\"font-size:11px; color:#888;\">Aucun zonage rattaché à ce terroir (ajoutez la couche <b>CB_Local_Territory_Zoning</b> à la carte si elle n'y est pas).</div>")
}

var rowsT = row("Financement", txt(f.funder)) + row("Agence", txt(f.agency)) + row("Partenaire de mise en œuvre", txt(f.partner)) + row("Comité local de développement", txt(f.cld))
  + row("Statut (source)", txt(f.status_raw)) + row("Superficie SIG (source)", haTxt(f.area_sig_ha)) + row("Superficie calculée", haTxt(f.area_calc_ha)) + row("Fichier source", txt(f.src_file))
var footer = "<div style=\"text-align:center; font-size:10px; color:#aaa; margin-top:10px; padding-top:8px; border-top:1px solid #eee;\">Source : " + txt(f.src_layer)
  + IIf(IsEmpty(f.loaded_at), "", " &nbsp;|&nbsp; chargé le " + dateTxt(f.loaded_at)) + " &nbsp;|&nbsp; situation " + txt(f.situation) + "</div>"

var popup = "<div style=\"font-family:Segoe UI,sans-serif; font-size:13px; color:#1a1a2e;\">" + banner + chipsHtml + crumbHtml + tiles + zoningCard
  + section("Terroir et appui", ACCENT, table(rowsT)) + footer + "</div>"
return { type: "text", text: popup }

// ============================================================
//  Zoning popup — one expression for CB_Concession_Zoning (1), CB_Community_Forest_Zoning (3)
//  and CB_Local_Territory_Zoning (5); the parent layer is derived from $feature.layer.
//  Reads the parent layer and the sibling zones FROM THE WEB MAP by name (or SOURCE = "portal").
// ============================================================
Expects($feature, "*")

var SOURCE     = "map"
var PORTAL_URL = "https://geosmarthosting.undp.org/portal"
var ITEM_ID    = "PASTE_ITEM_ID_HERE"
var PARENT = { "concession_zoning": ["CB_Logging_Concessions", 0, "Concession / titre forestier", "#5d4037"],
               "community_forest_zoning": ["Community forests - Limits", 2, "Forêt communautaire", "#1b5e20"],
               "local_territory_zoning": ["Local territories - Limits", 4, "Terroir villageois (PSAT)", "#37474f"] }
var SELF = { "concession_zoning": ["CB_Concession_Zoning", 1], "community_forest_zoning": ["CB_Community_Forest_Zoning", 3], "local_territory_zoning": ["CB_Local_Territory_Zoning", 5] }

function isBlank(x) { return IsEmpty(x) || Text(x) == "" || Text(x) == "null" }
function txt(x) { if (isBlank(x)) { return "" } var s = Text(x); s = Replace(s, "&", "&amp;"); s = Replace(s, "<", "&lt;"); return Replace(s, ">", "&gt;") }
function haTxt(x) { if (isBlank(x)) { return "" } var n = Number(x); if (IsNan(n) || n <= 0) { return "" } return Text(Round(n, 0), "#,###") + " ha" }
function dateTxt(x) { if (IsEmpty(x)) { return "" } return Text(Date(x), "DD MMM YYYY") }
function cat(dict, key, dflt) { if (!isBlank(key) && HasKey(dict, key)) { return dict[key] } return dflt }
function fsGet(name, id, fields, geom) {
  if (SOURCE == "portal" && ITEM_ID != "PASTE_ITEM_ID_HERE") { return FeatureSetByPortalItem(Portal(PORTAL_URL), ITEM_ID, id, fields, geom) }
  return FeatureSetByName($map, name, fields, geom)
}
function row(label, value) {
  if (isBlank(value)) { return "" }
  return "<tr><td style=\"color:#666; width:44%; padding:4px 6px 4px 0; font-size:12px; vertical-align:top;\">" + label + "</td><td style=\"font-weight:600; font-size:12px; padding:4px 0; vertical-align:top;\">" + value + "</td></tr>"
}
function table(rows) { if (isBlank(rows)) { return "" } return "<table style=\"width:100%; border-collapse:collapse;\">" + rows + "</table>" }
function section(title, accent, body) {
  if (isBlank(body)) { return "" }
  return "<div style=\"background:#f7fafa; border-left:4px solid " + accent + "; border-radius:4px; margin-bottom:10px; padding:8px 10px 8px 8px;\">"
       + "<div style=\"font-size:10px; font-weight:700; color:" + accent + "; text-transform:uppercase; letter-spacing:0.8px; margin-bottom:8px;\">" + title + "</div>" + body + "</div>"
}
function chip(label, bg, fg) { return "<div style=\"background:" + bg + "; color:" + fg + "; padding:5px 10px; border-radius:6px; font-size:11px; font-weight:700;\">" + label + "</div>" }
function tile(value, label, color) {
  return "<div style=\"flex:1 1 30%; min-width:80px; background:#f5f9f9; border:1px solid #e0e0e0; border-radius:6px; padding:8px 4px; text-align:center;\">"
       + "<div style=\"font-size:16px; font-weight:700; color:" + color + ";\">" + value + "</div><div style=\"font-size:9px; color:#666; text-transform:uppercase; letter-spacing:0.5px; margin-top:2px;\">" + label + "</div></div>"
}

var ZONE = { "production": ["Production", "#c98a2b", "Exploitation forestière / production ligneuse"], "conservation": ["Conservation", "#2e7d32", "Conservation de la biodiversité"],
  "protection": ["Protection", "#00695c", "Protection (berges, pentes, sites sacrés, aires protégées)"], "community_development": ["Développement rural / communautaire", "#a0522d", "Usages des communautés (chasse, pêche, cueillette, PFNL)"],
  "agriculture": ["Agriculture", "#d4b106", "Cultures, élevage, agroforesterie, pisciculture"], "habitat": ["Habitat", "#8d6e63", "Villages, campements"],
  "savanna_protection": ["Mise en défens / reboisement", "#7cb342", "Savanes mises en défens, reboisement, RNA"], "concession": ["Zone concédée", "#5d4037", "Concessions et titres tiers"],
  "community_forest": ["Forêt communautaire", "#43a047", "CFCL / forêt des communautés locales"], "conflict": ["Zone conflictuelle", "#d32f2f", "Litiges"],
  "research": ["Recherche", "#7e57c2", "Recherche scientifique"], "unclassified": ["Non classée", "#bdbdbd", "Zonage non renseigné dans la source"], "other": ["Autre", "#607d8b", "Autre affectation"] }
var STATUS = { "attributed": ["Attribuée / validée", "#e8f5e9", "#2e7d32"], "provisional": ["Provisoire", "#fff8e1", "#ff8f00"], "final": ["Définitive", "#e8f5e9", "#1b5e20"], "in_process": ["En cours", "#e3f2fd", "#1565c0"],
  "not_attributed": ["Non attribuée", "#eceff1", "#607d8b"], "rejected": ["Rejetée", "#ffebee", "#c62828"], "expired": ["Expirée", "#efebe9", "#6d4c41"], "unknown": ["Non renseigné", "#eceff1", "#546e7a"] }
var FLAG = { "CMR": "🇨🇲", "CAF": "🇨🇫", "COD": "🇨🇩", "COG": "🇨🇬", "GNQ": "🇬🇶", "GAB": "🇬🇦" }

var f = $feature
var lay = DefaultValue(f.layer, "concession_zoning")
var P = cat(PARENT, lay, ["CB_Logging_Concessions", 0, "Unité parente", "#5d4037"])
var S = cat(SELF, lay, ["CB_Concession_Zoning", 1])
var z = cat(ZONE, f.zone_type_std, ["Autre", "#607d8b", ""])
var ACCENT = z[1]
var title = DefaultValue(f.zone_name, DefaultValue(f.zone_type_raw, z[0]))

var banner = "<div style=\"background:" + ACCENT + "; color:white; padding:10px 12px; border-radius:6px 6px 0 0; margin:0 0 10px 0;\">"
  + "<div style=\"font-size:15px; font-weight:700;\">" + txt(title) + "</div>"
  + "<div style=\"font-size:11px; opacity:0.9; margin-top:2px;\">" + cat(FLAG, f.iso3, "") + " " + txt(f.country) + IIf(!isBlank(f.parent_name), " — " + txt(f.parent_name), "") + "</div>"
  + "<div style=\"font-size:10px; opacity:0.9; margin-top:4px; text-transform:uppercase; letter-spacing:0.8px;\">" + txt(z[0]) + " · " + txt(f.sub_type_raw) + "</div></div>"

var st = cat(STATUS, f.status_std, null)
var chips = chip(txt(z[0]), "#fff", ACCENT)
if (!IsEmpty(st)) { chips += chip(st[0], st[1], st[2]) }
if (f.geom_quality == "bbox") { chips += chip("&#9888; Emprise approximative", "#fbe9e7", "#d84315") }
if (isBlank(f.parent_uid)) { chips += chip("Unité parente non identifiée", "#eceff1", "#607d8b") }
if (f.retired == 1) { chips += chip("Retiré de la source", "#ffebee", "#c62828") }
var chipsHtml = "<div style=\"display:flex; gap:6px; margin-bottom:10px; flex-wrap:wrap;\">" + chips + "</div>"

var crumbs = txt(f.country)
if (!isBlank(f.province)) { crumbs += " › " + txt(f.province) }
if (!isBlank(f.admin2)) { crumbs += " › " + txt(f.admin2) }
if (!isBlank(f.admin3)) { crumbs += " › " + txt(f.admin3) }
if (!isBlank(f.admin4)) { crumbs += " › " + txt(f.admin4) }
var crumbHtml = "<div style=\"background:#f1f8e9; border-radius:6px; padding:7px 8px; margin-bottom:10px; font-size:12px; color:#33691e; font-weight:500;\">&#128205; " + crumbs + "</div>"

// ---------- parent and siblings ---------------------------------------------------------------------
var puid = f.parent_uid
var parent = null; var sib = null; var nSib = 0; var totSib = 0; var rows = null
if (!isBlank(puid)) {
  var pfs = fsGet(P[0], P[1], ["src_uid", "name", "reference", "holder", "community", "status_std", "area_calc_ha", "area_adm_ha", "sub_type_raw", "doc_count"], false)
  if (!IsEmpty(pfs)) { parent = First(Filter(pfs, "src_uid = @puid")) }
  var zfs = fsGet(S[0], S[1], ["parent_uid", "zone_type_std", "area_calc_ha", "retired"], false)
  if (!IsEmpty(zfs)) {
    sib = Filter(zfs, "parent_uid = @puid AND retired = 0")
    nSib = Count(sib)
    if (nSib > 0) {
      rows = OrderBy(GroupBy(sib, ["zone_type_std"], [{ name: "n", expression: "1", statistic: "COUNT" }, { name: "ha", expression: "area_calc_ha", statistic: "SUM" }]), "ha DESC")
      for (var r in rows) { totSib += DefaultValue(r.ha, 0) }
    }
  }
}

var area = f.area_sig_ha
if (isBlank(area) || area <= 0) { area = f.area_adm_ha }
if (isBlank(area) || area <= 0) { area = f.area_calc_ha }
var share = IIf(totSib > 0 && !isBlank(f.area_calc_ha), Round(100 * f.area_calc_ha / totSib, 1), null)
var tiles = "<div style=\"display:flex; gap:6px; margin-bottom:10px; flex-wrap:wrap;\">"
  + tile(DefaultValue(haTxt(area), "—"), "Superficie de la zone", ACCENT)
  + tile(IIf(IsEmpty(share), "—", Text(share) + " %"), "Part de l'unité", "#2e7d32")
  + tile(IIf(nSib > 0, Text(nSib), "—"), "Zones dans l'unité", "#607d8b") + "</div>"

var meaning = "<div style=\"font-size:11px; color:#4b5563; margin:-4px 0 10px 0;\">" + txt(z[2]) + "</div>"

// ---------- donut of the unit ---------------------------------------------------------------------------
var donut = ""
if (nSib > 1 && totSib > 0) {
  var grad = ""; var cum = 0; var legend = ""
  for (var r in rows) {
    var zz = cat(ZONE, r.zone_type_std, ["Autre", "#607d8b", ""])
    var sh = Round(100 * DefaultValue(r.ha, 0) / totSib, 1)
    var start = cum; cum = Round(cum + sh, 1)
    if (grad != "") { grad += ", " }
    grad += zz[1] + " " + start + "% " + cum + "%"
    var me = IIf(r.zone_type_std == f.zone_type_std, " &#9664;", "")
    legend += "<div style=\"display:flex; justify-content:space-between; font-size:11px; margin-bottom:3px;\"><span><span style=\"display:inline-block; width:10px; height:10px; background:" + zz[1] + "; border-radius:2px; margin-right:6px;\"></span>"
      + txt(zz[0]) + " <span style=\"color:#999;\">(" + Text(r.n) + ")</span>" + me + "</span><span style=\"font-weight:700; color:" + zz[1] + ";\">" + haTxt(r.ha) + " · " + sh + " %</span></div>"
  }
  if (cum < 100) { grad += ", #e0e0e0 " + cum + "% 100%" }
  donut = "<div style=\"background:#f7fafa; border-left:4px solid " + P[3] + "; border-radius:4px; margin-bottom:10px; padding:8px 10px 8px 8px;\">"
    + "<div style=\"font-size:10px; font-weight:700; color:" + P[3] + "; text-transform:uppercase; letter-spacing:0.8px; margin-bottom:8px;\">Zonage de l'unité · " + Text(nSib) + " zones · " + haTxt(totSib) + "</div>"
    + "<div style=\"display:flex; align-items:center; gap:14px;\"><div style=\"width:84px; height:84px; flex-shrink:0; border-radius:50%; background:conic-gradient(" + grad + "); display:flex; align-items:center; justify-content:center;\">"
    + "<div style=\"width:54px; height:54px; background:white; border-radius:50%; display:flex; align-items:center; justify-content:center; text-align:center;\"><div><div style=\"font-size:11px; font-weight:700; color:" + ACCENT + ";\">" + IIf(IsEmpty(share), "", Text(share) + " %") + "</div><div style=\"font-size:8px; color:#888;\">cette zone</div></div></div></div>"
    + "<div style=\"flex:1;\">" + legend + "</div></div></div>"
}

// ---------- parent card ------------------------------------------------------------------------------------
var parentCard = ""
if (!IsEmpty(parent)) {
  var pst = cat(STATUS, parent.status_std, null)
  var prow = row("Nom", "<b>" + txt(DefaultValue(parent.name, parent.reference)) + "</b>" + IIf(!isBlank(parent.reference) && parent.reference != parent.name, " · " + txt(parent.reference), ""))
    + row("Type", txt(parent.sub_type_raw)) + row("Attributaire / communauté", txt(DefaultValue(parent.holder, parent.community)))
    + row("Statut", IIf(IsEmpty(pst), "", "<span style=\"background:" + pst[1] + "; color:" + pst[2] + "; padding:2px 8px; border-radius:6px; font-size:11px; font-weight:700;\">" + pst[0] + "</span>"))
    + row("Superficie", haTxt(IIf(isBlank(parent.area_adm_ha), parent.area_calc_ha, parent.area_adm_ha)))
    + row("Documents", IIf(!isBlank(parent.doc_count) && parent.doc_count > 0, Text(parent.doc_count) + " document(s) — voir la fiche de l'unité", ""))
  parentCard = section(P[2], P[3], table(prow))
} else if (isBlank(f.parent_uid)) {
  parentCard = section(P[2], "#9e9e9e", "<div style=\"font-size:11px; color:#888;\">Unité parente non identifiée" + IIf(isBlank(f.parent_ref), "", " (référence source : " + txt(f.parent_ref) + ")") + ".</div>")
}

var zoneRows = row("Affectation (source)", txt(f.zone_type_raw)) + row("Raison / usage", txt(f.zone_reason)) + row("Code", txt(f.zone_code)) + row("Statut (source)", txt(f.status_raw))
  + row("Exploitant", txt(f.operator)) + row("Superficie SIG (source)", haTxt(f.area_sig_ha)) + row("Superficie administrative", haTxt(f.area_adm_ha)) + row("Superficie calculée", haTxt(f.area_calc_ha))
  + row("Date du plan", dateTxt(f.date_plan)) + row("Programme", txt(f.programme)) + row("Financement / agence", txt(DefaultValue(f.funder, "")) + IIf(isBlank(f.agency), "", " · " + txt(f.agency)))
  + row("Partenaire", txt(f.partner)) + row("Année de référence", IIf(isBlank(f.year_ref), "", Text(f.year_ref)))

var footer = "<div style=\"text-align:center; font-size:10px; color:#aaa; margin-top:10px; padding-top:8px; border-top:1px solid #eee;\">Source : " + txt(f.src_layer)
  + IIf(isBlank(f.src_file), "", " · " + txt(f.src_file)) + IIf(isBlank(f.src_vintage), "", " (" + txt(f.src_vintage) + ")") + IIf(IsEmpty(f.loaded_at), "", " &nbsp;|&nbsp; chargé le " + dateTxt(f.loaded_at))
  + " &nbsp;|&nbsp; situation " + txt(f.situation) + "</div>"

var popup = "<div style=\"font-family:Segoe UI,sans-serif; font-size:13px; color:#1a1a2e;\">" + banner + chipsHtml + meaning + crumbHtml + tiles + donut + parentCard
  + section("Zone", ACCENT, table(zoneRows)) + footer + "</div>"
return { type: "text", text: popup }

renderer.valueExpression:
// =====================================================================================
//  Symbology · unique values on an Arcade expression, for the three zoning layers
//  (CB_Concession_Zoning, CB_Community_Forest_Zoning, CB_Local_Territory_Zoning).
//  Map Viewer: Styles > + Expression > paste > Types (unique symbols).
//  Pro: Symbology > Unique Values > Set an expression.
//  Returns the display label; apply the colours listed in README_arcade.md (same palette as the popups).
// =====================================================================================
var LABEL = {
  'production':            'Production (exploitation ligneuse)',
  'conservation':          'Conservation',
  'protection':            'Protection',
  'community_development': 'Développement rural / communautaire',
  'agriculture':           'Agriculture et agroforesterie',
  'habitat':               'Habitat',
  'savanna_protection':    'Mise en défens / reboisement',
  'concession':            'Zone concédée (titres tiers)',
  'community_forest':      'Forêt communautaire',
  'conflict':              'Zone conflictuelle',
  'research':              'Recherche',
  'unclassified':          'Non classée',
  'other':                 'Autre'
};
var k = $feature.zone_type_std;
if (IsEmpty(k) || !HasKey(LABEL, k)) { return 'Non classée'; }
if ($feature.retired == 1) { return 'Retiré de la source'; }
return LABEL[k];

expressionInfo.expression:
// ============================================================
//  CB_Protected_Areas — popup content (Arcade element)
//  Reads the table "CB_Documents" and the layers "CB_Logging_Concessions" / "CB_Community_Forests"
//  from the web map by name (or SOURCE = "portal" + ITEM_ID) for documents and overlaps.
// ============================================================
Expects($feature, "*")

var SOURCE     = "map"
var PORTAL_URL = "https://geosmarthosting.undp.org/portal"
var ITEM_ID    = "PASTE_ITEM_ID_HERE"
var NAME_DOCS  = "CB_Documents";            var ID_DOCS = 7
var NAME_CONC  = "CB_Logging_Concessions";  var ID_CONC = 0
var NAME_CF    = "CB_Community_Forests";    var ID_CF   = 2

function isBlank(x) { return IsEmpty(x) || Text(x) == "" || Text(x) == "null" }
function txt(x) { if (isBlank(x)) { return "" } var s = Text(x); s = Replace(s, "&", "&amp;"); s = Replace(s, "<", "&lt;"); return Replace(s, ">", "&gt;") }
function haTxt(x) { if (isBlank(x)) { return "" } var n = Number(x); if (IsNan(n) || n <= 0) { return "" } return Text(Round(n, 0), "#,###") + " ha" }
function km2Txt(x) { if (isBlank(x)) { return "" } var n = Number(x); if (IsNan(n) || n <= 0) { return "" } return Text(Round(n / 100, 0), "#,###") + " km²" }
function dateTxt(x) { if (IsEmpty(x)) { return "" } return Text(Date(x), "DD MMM YYYY") }
function cat(dict, key, dflt) { if (!isBlank(key) && HasKey(dict, key)) { return dict[key] } return dflt }
function fsGet(name, id, fields, geom) {
  if (SOURCE == "portal" && ITEM_ID != "PASTE_ITEM_ID_HERE") { return FeatureSetByPortalItem(Portal(PORTAL_URL), ITEM_ID, id, fields, geom) }
  return FeatureSetByName($map, name, fields, geom)
}
function row(label, value) {
  if (isBlank(value)) { return "" }
  return "<tr><td style=\"color:#666; width:44%; padding:4px 6px 4px 0; font-size:12px; vertical-align:top;\">" + label + "</td><td style=\"font-weight:600; font-size:12px; padding:4px 0; vertical-align:top;\">" + value + "</td></tr>"
}
function table(rows) { if (isBlank(rows)) { return "" } return "<table style=\"width:100%; border-collapse:collapse;\">" + rows + "</table>" }
function section(title, accent, body) {
  if (isBlank(body)) { return "" }
  return "<div style=\"background:#f7fafa; border-left:4px solid " + accent + "; border-radius:4px; margin-bottom:10px; padding:8px 10px 8px 8px;\">"
       + "<div style=\"font-size:10px; font-weight:700; color:" + accent + "; text-transform:uppercase; letter-spacing:0.8px; margin-bottom:8px;\">" + title + "</div>" + body + "</div>"
}
function chip(label, bg, fg) { return "<div style=\"background:" + bg + "; color:" + fg + "; padding:5px 10px; border-radius:6px; font-size:11px; font-weight:700;\">" + label + "</div>" }
function tile(value, label, color) {
  return "<div style=\"flex:1 1 30%; min-width:80px; background:#f5f9f9; border:1px solid #e0e0e0; border-radius:6px; padding:8px 4px; text-align:center;\">"
       + "<div style=\"font-size:16px; font-weight:700; color:" + color + ";\">" + value + "</div><div style=\"font-size:9px; color:#666; text-transform:uppercase; letter-spacing:0.5px; margin-top:2px;\">" + label + "</div></div>"
}
function bar(label, value, color, maxv) {
  if (isBlank(value) || value <= 0 || maxv <= 0) { return "" }
  var pct = Round((value / maxv) * 100, 0)
  return "<div style=\"margin-bottom:6px;\"><div style=\"display:flex; justify-content:space-between; font-size:10px; color:#555; margin-bottom:2px;\"><span style=\"font-weight:600;\">" + label + "</span><span style=\"font-weight:700; color:" + color + ";\">" + haTxt(value) + "</span></div>"
       + "<div style=\"background:#e0e0e0; border-radius:4px; height:12px; width:100%; overflow:hidden;\"><div style=\"background:" + color + "; height:12px; width:" + pct + "%; border-radius:4px;\"></div></div></div>"
}
function docIcon(name) {
  var n = Lower(Text(name))
  if (Find(".pdf", n) > -1) { return "&#128196;" }
  if (Find(".doc", n) > -1) { return "&#128221;" }
  if (Find(".xls", n) > -1) { return "&#128202;" }
  if (Find(".zip", n) > -1 || Find(".shp", n) > -1 || Find(".kml", n) > -1) { return "&#128506;" }
  if (Find(".jpg", n) > -1 || Find(".png", n) > -1) { return "&#128444;" }
  return "&#128196;"
}

var FLAG = { "CMR": "🇨🇲", "CAF": "🇨🇫", "COD": "🇨🇩", "COG": "🇨🇬", "GNQ": "🇬🇶", "GAB": "🇬🇦" }
var SUBTYPE = { "national_park": ["Parc national", "#1b5e20", "&#127966;"], "world_heritage": ["Patrimoine mondial", "#4a148c", "&#127963;"], "biosphere_reserve": ["Réserve de biosphère", "#00695c", "&#127757;"],
  "ramsar": ["Site Ramsar (zone humide)", "#0277bd", "&#128167;"], "sanctuary": ["Sanctuaire", "#2e7d32", "&#129421;"], "hunting_zone": ["Zone d'intérêt cynégétique", "#8d6e63", "&#127919;"],
  "wildlife_reserve": ["Réserve de faune", "#388e3c", "&#128024;"], "forest_reserve": ["Réserve forestière", "#558b2f", "&#127795;"], "community_reserve": ["Réserve communautaire", "#43a047", "&#127968;"],
  "botanical_garden": ["Jardin botanique / zoologique", "#7cb342", "&#127807;"], "natural_monument": ["Monument naturel", "#6d4c41", "&#129704;"], "strict_reserve": ["Réserve naturelle intégrale", "#004d40", "&#128274;"],
  "nature_reserve": ["Réserve naturelle", "#2e7d32", "&#127794;"], "marine_protected_area": ["Aire marine protégée", "#01579b", "&#128032;"], "other_protected_area": ["Aire protégée", "#607d8b", "&#128737;"], "other": ["Aire protégée", "#607d8b", "&#128737;"] }
var IUCN = { "IA": "Ia · Réserve naturelle intégrale", "IB": "Ib · Zone de nature sauvage", "II": "II · Parc national", "III": "III · Monument naturel", "IV": "IV · Gestion des habitats et espèces",
  "V": "V · Paysage protégé", "VI": "VI · Utilisation durable des ressources", "NOT APPLICABLE": "Non applicable", "NOT REPORTED": "Non renseignée", "NOT ASSIGNED": "Non assignée" }
var STATUS = { "attributed": ["Désignée", "#e8f5e9", "#2e7d32"], "provisional": ["Provisoire", "#fff8e1", "#ff8f00"], "final": ["Définitive", "#e8f5e9", "#1b5e20"], "in_process": ["Proposée / en cours", "#e3f2fd", "#1565c0"],
  "not_attributed": ["Non désignée", "#eceff1", "#607d8b"], "rejected": ["Rejetée", "#ffebee", "#c62828"], "expired": ["Déclassée", "#efebe9", "#6d4c41"], "unknown": ["Statut non renseigné", "#eceff1", "#546e7a"] }
var MGMT = { "approved": ["Plan d'aménagement approuvé", "#e8f5e9", "#2e7d32"], "in_preparation": ["Plan d'aménagement en cours", "#fff8e1", "#ff8f00"], "under_revision": ["Plan en révision", "#e3f2fd", "#1565c0"],
  "not_planned": ["Sans plan d'aménagement", "#eceff1", "#607d8b"], "unknown": ["Aménagement non renseigné", "#eceff1", "#90a4ae"] }
var DOCCAT = { "attribution_decree": ["Décrets, arrêtés et actes de création", "#5e35b1"], "convention": ["Conventions et contrats", "#1565c0"], "management_plan": ["Plans d'aménagement et de gestion", "#2e7d32"],
  "simple_management_plan": ["Plans simples de gestion", "#2e7d32"], "specifications": ["Cahiers des charges", "#00838f"], "certificate": ["Certificats et permis", "#ef6c00"], "map": ["Cartes", "#3949ab"],
  "attestation": ["Attestations", "#6d4c41"], "minutes": ["Procès-verbaux", "#546e7a"], "application": ["Dossiers", "#8d6e63"], "evaluation": ["Rapports et évaluations", "#7b1fa2"], "other": ["Autres documents", "#78909c"] }
var NATIVE_WDPA = [["original_name", "Nom original"], ["wdpa_pid", "Identifiant WDPA (parcelle)"], ["reported_area", "Superficie déclarée (km²)"], ["gis_area", "Superficie SIG (km²)"], ["reported_marine_area", "Superficie marine déclarée (km²)"],
  ["gis_marine_area", "Superficie marine SIG (km²)"], ["no_take", "Zone de non-prélèvement"], ["no_take_area", "Superficie non-prélèvement (km²)"], ["legal_status_updated_at", "Mise à jour du statut légal"], ["management_plan", "Plan de gestion"],
  ["international_criteria", "Critères internationaux"], ["verif", "Vérification WDPA"], ["is_green_list", "Liste verte UICN"], ["is_oecm", "Autre mesure de conservation (OECM)"], ["marine", "Marine"], ["owner_type", "Type de propriétaire"], ["supplementary_info", "Informations complémentaires"]]
var NATIVE_NAT = { "CMR": [["desc_type", "Type (atlas national)"], ["partenar", "Partenaire"], ["statu_crea", "Statut de création"], ["statu_amgt", "Statut d'aménagement"], ["date_prop", "Date de proposition"], ["date_crea", "Date de création"], ["date_amgt", "Date d'aménagement"], ["sup_mar_ha", "Superficie marine (ha)"]],
  "COD": [["desc_type", "Type (atlas national)"], ["nom_orig", "Nom original"], ["province", "Province"], ["desig_type", "Type de désignation"], ["desig_eng", "Désignation (anglais)"], ["statu_leg", "Statut légal"], ["date_desig", "Date de désignation"], ["type_gouv", "Type de gouvernance"], ["aut_gest", "Autorité de gestion"], ["aut_amgt", "Autorité d'aménagement"], ["statu_amgt", "Statut d'aménagement"], ["wdpapid", "WDPA PID"]],
  "COG": [["desc_type", "Type (atlas national)"], ["departemen", "Département"], ["aut_gest", "Autorité de gestion"]],
  "GAB": [["desc_type", "Type (atlas national)"], ["nom_comple", "Nom complet"], ["code_ap", "Code de l'aire protégée"], ["statu_crea", "Statut de création"], ["annee_crea", "Année de création"], ["annee_prop", "Année de proposition"], ["statu_amgt", "Statut d'aménagement"], ["auth_gest", "Autorité de gestion"], ["type_gouv", "Gouvernance"], ["sup_mar_ha", "Superficie marine (ha)"]],
  "CAF": [["desc_type", "Type (atlas national)"], ["gestionair", "Gestionnaire"], ["bailleur", "Bailleur"], ["statu_crea", "Statut de création"], ["date_crea", "Date de création"], ["statu_amgt", "Statut d'aménagement"], ["date_amgt", "Date d'aménagement"]] }

var f = $feature
var iso = f.iso3
var stype = cat(SUBTYPE, f.sub_type_std, ["Aire protégée", "#607d8b", "&#128737;"])
var ACCENT = stype[1]
var fromWdpa = Find(":wdpa:", f.src_uid) > -1
var st = cat(STATUS, f.status_std, null); var mg = cat(MGMT, f.status_mgmt_std, null)

var banner = "<div style=\"background:" + ACCENT + "; color:white; padding:10px 12px; border-radius:6px 6px 0 0; margin:0 0 10px 0;\">"
  + "<div style=\"font-size:15px; font-weight:700;\">" + stype[2] + " " + txt(DefaultValue(f.name, "Sans nom")) + "</div>"
  + "<div style=\"font-size:11px; opacity:0.9; margin-top:2px;\">" + cat(FLAG, iso, "") + " " + txt(f.country) + IIf(!isBlank(f.mgmt_authority), " — " + txt(f.mgmt_authority), "") + "</div>"
  + "<div style=\"font-size:10px; opacity:0.9; margin-top:4px; text-transform:uppercase; letter-spacing:0.8px;\">" + txt(DefaultValue(f.designation, stype[0])) + IIf(isBlank(f.wdpa_id), "", " · WDPA " + txt(f.wdpa_id)) + "</div></div>"

var chips = chip(stype[0], "#fff", ACCENT)
if (!isBlank(f.iucn_category)) { chips += chip("UICN " + txt(f.iucn_category), "#eceff1", "#37474f") }
if (!IsEmpty(st)) { chips += chip(st[0], st[1], st[2]) }
if (!IsEmpty(mg)) { chips += chip(mg[0], mg[1], mg[2]) }
if (f.green_list == 1) { chips += chip("&#127793; Liste verte UICN", "#e8f5e9", "#00c853") }
if (f.is_marine == 1) { chips += chip("&#127754; Marine", "#e1f5fe", "#0277bd") }
if (f.is_oecm == 1) { chips += chip("OECM", "#f3e5f5", "#6a1b9a") }
if (!isBlank(f.parent_ref) && Find("transboundary", f.parent_ref) > -1) { chips += chip("Transfrontalière", "#fff3e0", "#ef6c00") }
if (f.retired == 1) { chips += chip("Retiré de la source", "#ffebee", "#c62828") }
var chipsHtml = "<div style=\"display:flex; gap:6px; margin-bottom:10px; flex-wrap:wrap;\">" + chips + "</div>"

var crumbs = txt(f.country)
if (!isBlank(f.province)) { crumbs += " › " + txt(f.province) }
if (!isBlank(f.admin2)) { crumbs += " › " + txt(f.admin2) }
var crumbHtml = "<div style=\"background:#e8f5e9; border-radius:6px; padding:7px 8px; margin-bottom:10px; font-size:12px; color:#2e7d32; font-weight:500;\">&#128205; " + crumbs + "</div>"

// ---------- related data ---------------------------------------------------------------------------
var uid = f.src_uid
var docs = null; var nDocs = 0
var dtb = fsGet(NAME_DOCS, ID_DOCS, ["parent_uid", "title", "category_std", "url", "size_bytes", "date_doc", "file_name", "retired"], false)
if (!IsEmpty(dtb)) { docs = OrderBy(Filter(dtb, "parent_uid = @uid AND retired = 0"), "category_std ASC, date_doc DESC, title ASC"); nDocs = Count(docs) }
if (nDocs == 0 && !isBlank(f.doc_count)) { nDocs = f.doc_count }
var over = null; var nConc = 0; var overcf = null; var nCf = 0
var conc = fsGet(NAME_CONC, ID_CONC, ["name", "sub_type_raw", "holder", "retired"], true)
if (!IsEmpty(conc)) { over = Filter(Intersects(conc, Geometry(f)), "retired = 0"); nConc = Count(over) }
var cfs = fsGet(NAME_CF, ID_CF, ["name", "sub_type_raw", "community", "retired"], true)
if (!IsEmpty(cfs)) { overcf = Filter(Intersects(cfs, Geometry(f)), "retired = 0"); nCf = Count(overcf) }

var area = f.area_adm_ha; var areaLbl = "Superficie déclarée"
if (isBlank(area) || area <= 0) { area = f.area_sig_ha; areaLbl = "Superficie SIG" }
if (isBlank(area) || area <= 0) { area = f.area_calc_ha; areaLbl = "Superficie calculée" }
var tiles = "<div style=\"display:flex; gap:6px; margin-bottom:10px; flex-wrap:wrap;\">"
  + tile(DefaultValue(haTxt(area), "—"), areaLbl + IIf(isBlank(area), "", " · " + km2Txt(area)), ACCENT)
  + tile(IIf(!isBlank(f.legal_status_year), Text(f.legal_status_year), IIf(IsEmpty(f.date_attr), "—", Text(Date(f.date_attr), "YYYY"))), "Désignation", "#607d8b")
  + tile(IIf(nDocs > 0, Text(nDocs), "—"), "Documents", "#1565c0")
  + tile(IIf(nConc + nCf > 0, Text(nConc + nCf), "0"), "Chevauchements", IIf(nConc + nCf > 0, "#d84315", "#4caf50")) + "</div>"

var maxA = 0
var arrA = [f.area_adm_ha, f.area_sig_ha, f.area_calc_ha, f.marine_area_ha]
for (var ai in arrA) { var av = arrA[ai]; if (!isBlank(av) && av > maxA) { maxA = av } }
var areaCard = section("Superficies", "#1565c0", bar("Déclarée", f.area_adm_ha, "#607d8b", maxA) + bar("SIG (source)", f.area_sig_ha, "#1565c0", maxA) + bar("Calculée (géodésique)", f.area_calc_ha, ACCENT, maxA) + bar("Dont marine", f.marine_area_ha, "#0277bd", maxA))

var iucnKey = Upper(DefaultValue(f.iucn_category, ""))
var govRows = row("Désignation", txt(f.designation) + IIf(isBlank(f.designation_type), "", " <span style=\"color:#888;\">(" + txt(f.designation_type) + ")</span>")) + row("Catégorie UICN", txt(cat(IUCN, iucnKey, f.iucn_category)))
  + row("Statut légal", txt(f.legal_status)) + row("Gouvernance", txt(f.governance)) + row("Autorité de gestion", txt(f.mgmt_authority)) + row("Aménagement (source)", txt(f.status_mgmt_raw))
  + row("Critères internationaux", txt(f.int_criteria)) + row("Royaume biogéographique", txt(f.realm)) + row("Non-prélèvement", txt(f.no_take)) + row("Vérification WDPA", txt(f.verification)) + row("Sites liés", txt(f.parent_ref))
var dateRows = row("Date de désignation", dateTxt(f.date_attr)) + row("Proposition", dateTxt(f.date_conv_prov)) + row("Plan d'aménagement", dateTxt(f.date_plan))

var native = Dictionary()
if (!isBlank(f.src_attrs_json)) { native = Dictionary(f.src_attrs_json) }
var fields = IIf(fromWdpa, NATIVE_WDPA, cat(NATIVE_NAT, iso, []))
var nativeRows = ""
for (var i in fields) {
  var key = fields[i][0]
  if (HasKey(native, key) && !isBlank(native[key])) {
    var v = native[key]
    if (TypeOf(v) == "Number" && v > 100000000000) { v = dateTxt(v) }
    if (TypeOf(v) == "Boolean") { v = IIf(v, "oui", "non") }
    nativeRows += row(fields[i][1], txt(v))
  }
}

var links = ""
if (!isBlank(f.wdpa_url)) { links += "<div style=\"font-size:12px; margin-bottom:4px;\">&#127760; <a href=\"" + f.wdpa_url + "\" target=\"_blank\" style=\"color:#1565c0;\">Fiche Protected Planet (WDPA " + txt(f.wdpa_id) + ") &#8599;</a></div>" }

var docsCard = ""
if (!IsEmpty(docs) && Count(docs) > 0) {
  var lastCat = ""; var list = ""; var k = 0
  for (var d in docs) {
    k += 1
    if (k > 60) { break }
    if (d.category_std != lastCat) { var cc = cat(DOCCAT, d.category_std, ["Documents", "#78909c"]); list += "<div style=\"font-size:10px; font-weight:700; color:" + cc[1] + "; text-transform:uppercase; letter-spacing:0.6px; margin:8px 0 4px 0;\">" + cc[0] + "</div>"; lastCat = d.category_std }
    var meta = ""
    if (!isBlank(d.size_bytes)) { meta += Text(Round(d.size_bytes / 1048576, 1)) + " Mo" }
    if (!IsEmpty(d.date_doc)) { meta += IIf(meta == "", "", " · ") + Text(Date(d.date_doc), "YYYY") }
    list += "<div style=\"display:flex; align-items:center; gap:8px; background:#fff; border:1px solid #e0e0e0; border-radius:6px; padding:6px 8px; margin-bottom:4px;\"><div style=\"font-size:16px;\">" + docIcon(d.file_name) + "</div>"
      + "<div style=\"flex:1; min-width:0;\"><div style=\"font-size:12px; font-weight:600; color:#1a1a2e;\">" + txt(DefaultValue(d.title, d.file_name)) + "</div><div style=\"font-size:10px; color:#888;\">" + txt(DefaultValue(d.file_name, "")) + IIf(meta == "", "", " · " + meta) + "</div></div>"
      + "<a href=\"" + d.url + "\" target=\"_blank\" style=\"background:#1565c0; color:#fff; padding:4px 10px; border-radius:6px; font-size:11px; font-weight:700; text-decoration:none; white-space:nowrap;\">Ouvrir &#8599;</a></div>"
  }
  docsCard = section("Documents · " + Text(Count(docs)), "#1565c0", list)
} else if (nDocs > 0) {
  docsCard = section("Documents · " + Text(nDocs), "#1565c0", "<div style=\"font-size:11px; color:#888;\">" + Text(nDocs) + " document(s) référencé(s). Ajoutez la table <b>CB_Documents</b> à la carte (ou renseignez ITEM_ID) pour afficher les liens.</div>")
}

var overCard = ""
if (nConc + nCf > 0) {
  var items = ""; var k2 = 0
  for (var o in over) { k2 += 1; if (k2 <= 8) { items += "<div style=\"font-size:11px; padding:3px 0; border-bottom:1px dashed #e0e0e0;\">&#129683; <b>" + txt(DefaultValue(o.name, o.sub_type_raw)) + "</b>" + IIf(isBlank(o.holder), "", " <span style=\"color:#888;\">· " + txt(o.holder) + "</span>") + "</div>" } }
  k2 = 0
  for (var o in overcf) { k2 += 1; if (k2 <= 8) { items += "<div style=\"font-size:11px; padding:3px 0; border-bottom:1px dashed #e0e0e0;\">&#127968; <b>" + txt(DefaultValue(o.name, o.sub_type_raw)) + "</b>" + IIf(isBlank(o.community), "", " <span style=\"color:#888;\">· " + txt(o.community) + "</span>") + "</div>" } }
  if (nConc + nCf > 16) { items += "<div style=\"font-size:10px; color:#999; margin-top:4px;\">liste limitée aux 8 premiers de chaque type</div>" }
  overCard = section("Chevauchements · " + Text(nConc) + " titre(s) forestier(s), " + Text(nCf) + " forêt(s) communautaire(s)", "#d84315", items)
}

var footer = "<div style=\"text-align:center; font-size:10px; color:#aaa; margin-top:10px; padding-top:8px; border-top:1px solid #eee;\">Source : " + txt(f.src_layer) + IIf(isBlank(f.src_vintage), "", " (" + txt(f.src_vintage) + ")")
  + IIf(IsEmpty(f.src_last_edit), "", " &nbsp;|&nbsp; édition source " + dateTxt(f.src_last_edit)) + IIf(IsEmpty(f.loaded_at), "", " &nbsp;|&nbsp; chargé le " + dateTxt(f.loaded_at))
  + IIf(isBlank(f.dedup_of), "", " &nbsp;|&nbsp; doublon de " + txt(f.dedup_of)) + " &nbsp;|&nbsp; situation " + txt(f.situation) + "</div>"

var popup = "<div style=\"font-family:Segoe UI,sans-serif; font-size:13px; color:#1a1a2e;\">" + banner + chipsHtml + crumbHtml + tiles + areaCard
  + section("Désignation et gouvernance", ACCENT, table(govRows)) + section("Dates", "#607d8b", table(dateRows))
  + section(IIf(fromWdpa, "Fiche WDPA (Protected Planet)", "Détails de l'atlas national · " + txt(f.country)), "#00838f", table(nativeRows) + links)
  + docsCard + overCard + footer + "</div>"
return { type: "text", text: popup }

// ============================================================
//  CB_Community_Forests — popup content (Arcade element)
//  House style (banner, chips, tiles, breadcrumb, PSG tracker, donut, document cards).
//  Reads "CB_Community_Forest_Zoning" and the table "CB_Documents" from the web map
//  by name (add them to the map, hidden is fine) or set SOURCE = "portal" + ITEM_ID.
// ============================================================
Expects($feature, "*")

var SOURCE      = "map"
var PORTAL_URL  = "https://geosmarthosting.undp.org/portal"
var ITEM_ID     = "PASTE_ITEM_ID_HERE"
var NAME_ZONING = "Community forest - Zoning";  var ID_ZONING = 3
var NAME_DOCS   = "CB_Documents";                var ID_DOCS   = 7
var ACCENT      = "#1b5e20"

// ---------- helpers ------------------------------------------------------------------------
function isBlank(x) { return IsEmpty(x) || Text(x) == "" || Text(x) == "null" }
function txt(x) { if (isBlank(x)) { return "" } var s = Text(x); s = Replace(s, "&", "&amp;"); s = Replace(s, "<", "&lt;"); return Replace(s, ">", "&gt;") }
function haTxt(x) { if (isBlank(x)) { return "" } var n = Number(x); if (IsNan(n) || n <= 0) { return "" } return Text(Round(n, 0), "#,###") + " ha" }
function dateTxt(x) { if (IsEmpty(x)) { return "" } return Text(Date(x), "DD MMM YYYY") }
function cat(dict, key, dflt) { if (!isBlank(key) && HasKey(dict, key)) { return dict[key] } return dflt }
function fsGet(name, id, fields, geom) {
  if (SOURCE == "portal" && ITEM_ID != "PASTE_ITEM_ID_HERE") { return FeatureSetByPortalItem(Portal(PORTAL_URL), ITEM_ID, id, fields, geom) }
  return FeatureSetByName($map, name, fields, geom)
}
function row(label, value) {
  if (isBlank(value)) { return "" }
  return "<tr><td style=\"color:#666; width:44%; padding:4px 6px 4px 0; font-size:12px; vertical-align:top;\">" + label + "</td>"
       + "<td style=\"font-weight:600; font-size:12px; padding:4px 0; vertical-align:top;\">" + value + "</td></tr>"
}
function table(rows) { if (isBlank(rows)) { return "" } return "<table style=\"width:100%; border-collapse:collapse;\">" + rows + "</table>" }
function section(title, accent, body) {
  if (isBlank(body)) { return "" }
  return "<div style=\"background:#f7fafa; border-left:4px solid " + accent + "; border-radius:4px; margin-bottom:10px; padding:8px 10px 8px 8px;\">"
       + "<div style=\"font-size:10px; font-weight:700; color:" + accent + "; text-transform:uppercase; letter-spacing:0.8px; margin-bottom:8px;\">" + title + "</div>" + body + "</div>"
}
function chip(label, bg, fg) { return "<div style=\"background:" + bg + "; color:" + fg + "; padding:5px 10px; border-radius:6px; font-size:11px; font-weight:700;\">" + label + "</div>" }
function tile(value, label, color) {
  return "<div style=\"flex:1 1 30%; min-width:80px; background:#f5f9f9; border:1px solid #e0e0e0; border-radius:6px; padding:8px 4px; text-align:center;\">"
       + "<div style=\"font-size:16px; font-weight:700; color:" + color + ";\">" + value + "</div>"
       + "<div style=\"font-size:9px; color:#666; text-transform:uppercase; letter-spacing:0.5px; margin-top:2px;\">" + label + "</div></div>"
}
function bar(label, value, color, maxv) {
  if (isBlank(value) || value <= 0 || maxv <= 0) { return "" }
  var pct = Round((value / maxv) * 100, 0)
  return "<div style=\"margin-bottom:6px;\"><div style=\"display:flex; justify-content:space-between; font-size:10px; color:#555; margin-bottom:2px;\">"
       + "<span style=\"font-weight:600;\">" + label + "</span><span style=\"font-weight:700; color:" + color + ";\">" + haTxt(value) + "</span></div>"
       + "<div style=\"background:#e0e0e0; border-radius:4px; height:12px; width:100%; overflow:hidden;\"><div style=\"background:" + color + "; height:12px; width:" + pct + "%; border-radius:4px;\"></div></div></div>"
}
function docIcon(name) {
  var n = Lower(Text(name))
  if (Find(".pdf", n) > -1) { return "&#128196;" }
  if (Find(".doc", n) > -1) { return "&#128221;" }
  if (Find(".xls", n) > -1) { return "&#128202;" }
  if (Find(".zip", n) > -1 || Find(".shp", n) > -1 || Find(".kml", n) > -1) { return "&#128506;" }
  if (Find(".jpg", n) > -1 || Find(".png", n) > -1 || Find(".jpeg", n) > -1) { return "&#128444;" }
  return "&#128196;"
}

// ---------- vocabularies -------------------------------------------------------------------
var FLAG = { "CMR": "🇨🇲", "CAF": "🇨🇫", "COD": "🇨🇩", "COG": "🇨🇬", "GNQ": "🇬🇶", "GAB": "🇬🇦" }
var SUBTYPE = { "community_forest": "Forêt communautaire", "cfcl": "Concession forestière des communautés locales (CFCL)", "cfcl_application": "Demande de CFCL en instruction",
  "communal_forest": "Forêt communale", "bosque_comunal": "Bosque comunal" }
var STATUS = { "attributed": ["Attribuée", "#e8f5e9", "#2e7d32"], "provisional": ["Convention provisoire", "#fff8e1", "#ff8f00"], "final": ["Convention définitive", "#e8f5e9", "#1b5e20"],
  "in_process": ["En cours d'instruction", "#e3f2fd", "#1565c0"], "not_attributed": ["Non attribuée", "#eceff1", "#607d8b"], "rejected": ["Rejetée", "#ffebee", "#c62828"],
  "expired": ["Expirée / résiliée", "#efebe9", "#6d4c41"], "unknown": ["Statut non renseigné", "#eceff1", "#546e7a"] }
var MGMT = { "approved": ["PSG approuvé", "#e8f5e9", "#2e7d32"], "in_preparation": ["PSG en élaboration", "#fff8e1", "#ff8f00"], "under_revision": ["PSG en révision", "#e3f2fd", "#1565c0"],
  "not_planned": ["Sans plan de gestion", "#eceff1", "#607d8b"], "unknown": ["PSG non renseigné", "#eceff1", "#90a4ae"] }
var ZONE = { "production": ["Production", "#c98a2b"], "conservation": ["Conservation", "#2e7d32"], "protection": ["Protection", "#00695c"],
  "community_development": ["Développement rural", "#a0522d"], "agriculture": ["Agriculture", "#d4b106"], "habitat": ["Habitat", "#8d6e63"],
  "savanna_protection": ["Mise en défens / reboisement", "#7cb342"], "concession": ["Zone concédée", "#5d4037"], "community_forest": ["Forêt communautaire", "#43a047"],
  "conflict": ["Zone conflictuelle", "#d32f2f"], "research": ["Recherche", "#7e57c2"], "unclassified": ["Non classée", "#bdbdbd"], "other": ["Autre", "#607d8b"] }
var DOCCAT = { "attribution_decree": ["Arrêtés, décrets et lettres d'attribution", "#5e35b1"], "convention": ["Conventions et contrats", "#1565c0"], "management_plan": ["Plans d'aménagement", "#2e7d32"],
  "simple_management_plan": ["Plans simples de gestion", "#2e7d32"], "specifications": ["Cahiers des charges", "#00838f"], "certificate": ["Certificats et permis", "#ef6c00"], "map": ["Cartes et données géographiques", "#3949ab"],
  "attestation": ["Attestations et actes", "#6d4c41"], "minutes": ["Procès-verbaux", "#546e7a"], "application": ["Demandes et dossiers", "#8d6e63"], "evaluation": ["Rapports et évaluations", "#7b1fa2"], "other": ["Autres documents", "#78909c"] }
var NATIVE = {
  "CMR": [["type_attr", "Type d'attributaire (GIC, ASS, COOP…)"], ["statu_conv", "Statut de la convention"], ["statu_amgt", "Statut d'aménagement"], ["date_con_p", "Convention provisoire"],
          ["date_con_d", "Convention définitive"], ["date_pgs", "Plan simple de gestion"], ["sup_adm_ha", "Superficie administrative (ha)"], ["sup_sig_ha", "Superficie SIG (ha)"]],
  "COD": [["id", "N° dossier geocfcl"], ["application_stage", "Étape de la procédure"], ["status", "Statut"], ["approval_date", "Date d'attribution"], ["year_of_approval", "Année d'attribution"],
          ["request_approval_entity", "Entité d'approbation"], ["community_org_type", "Type d'organisation communautaire"], ["operating_mode", "Mode d'exploitation"], ["potential_mode", "Potentiel identifié"],
          ["smp_approved", "PSG approuvé"], ["management_plan_approval", "Approbation du PSG"], ["smp_approval_date", "Date d'approbation du PSG"], ["supporting_org", "ONG / expert accompagnateur"],
          ["supporting_org_2", "Accompagnateur 2"], ["supporting_org_3", "Accompagnateur 3"], ["supporting_org_type", "Type d'accompagnateur"], ["group", "Groupement"], ["sector", "Secteur / chefferie"],
          ["territory", "Territoire"], ["area", "Superficie déclarée (ha)"], ["modified", "Dernière mise à jour geocfcl"], ["num_for_com", "N° de concession (WRI)"], ["accompagnateur", "Accompagnateur (WRI)"],
          ["gestionnaire", "Gestionnaire (WRI)"], ["pg_simple", "PSG (WRI)"], ["mode_gestion", "Mode de gestion (WRI)"], ["Programme", "Programme"], ["Finance", "Financement"], ["Agence", "Agence"],
          ["Partenaire", "Partenaire"], ["Statut", "Statut (PIREDD)"], ["Foncier", "Sécurisation foncière"], ["Exploitati", "Exploitation"], ["Certificat", "Certification"]],
  "GNQ": [["codigo", "Código"], ["num_regis", "N° de registro"], ["nom_pblado", "Poblado"], ["local_dist", "Distrito"], ["fech_atrb", "Fecha de atribución"], ["texto_ofic", "Texto oficial"],
          ["auto_firma", "Autoridad firmante"], ["estad_atrb", "Estado de atribución"], ["empr_explo", "Empresa explotadora"], ["estad_expl", "Estado de explotación"], ["Sub_adm", "Superficie administrativa (ha)"]],
  "GAB": [["nom_ass", "Association"], ["nom_com", "Communauté"], ["nom_ste", "Société partenaire"], ["mode_expl", "Mode d'exploitation"], ["statu_conv", "Statut de la convention"],
          ["date_con_p", "Convention provisoire"], ["date_con_d", "Convention définitive"], ["date_psg", "Plan simple de gestion"], ["observatn", "Observations"], ["sup_adm_ha", "Superficie administrative (ha)"], ["sup_sig_ha", "Superficie SIG (ha)"]] }

// ---------- core values ------------------------------------------------------------------------
var f = $feature
var iso = f.iso3
var name = DefaultValue(f.name, DefaultValue(f.community, DefaultValue(f.reference, "Sans nom")))
var subType = cat(SUBTYPE, f.sub_type_std, DefaultValue(f.sub_type_raw, "Forêt communautaire"))
var st = cat(STATUS, f.status_std, null); var mg = cat(MGMT, f.status_mgmt_std, null)
var fromGeocfcl = Find(":geocfcl:", f.src_uid) > -1

// ---------- banner -------------------------------------------------------------------------------
var banner = "<div style=\"background:" + ACCENT + "; color:white; padding:10px 12px; border-radius:6px 6px 0 0; margin:0 0 10px 0;\">"
  + "<div style=\"font-size:15px; font-weight:700;\">" + txt(name) + "</div>"
  + "<div style=\"font-size:11px; opacity:0.9; margin-top:2px;\">" + cat(FLAG, iso, "") + " " + txt(f.country) + IIf(!isBlank(f.community) && f.community != name, " — communauté " + txt(f.community), "") + "</div>"
  + "<div style=\"font-size:10px; opacity:0.9; margin-top:4px; text-transform:uppercase; letter-spacing:0.8px;\">" + txt(subType) + "</div></div>"

// ---------- chips ----------------------------------------------------------------------------------
var chips = ""
if (!IsEmpty(st)) { chips += chip(st[0], st[1], st[2]) }
if (!IsEmpty(mg)) { chips += chip(mg[0], mg[1], mg[2]) }
if (!isBlank(f.application_stage)) { chips += chip(txt(f.application_stage), "#eceff1", "#455a64") }
if (!isBlank(f.tenure_status)) { chips += chip("&#128274; Foncier " + txt(f.tenure_status), "#f3e5f5", "#6a1b9a") }
if (f.country_check == "mismatch") { chips += chip("&#9888; Pays incohérent", "#fbe9e7", "#d84315") }
if (f.retired == 1) { chips += chip("Retiré de la source", "#ffebee", "#c62828") }
var chipsHtml = IIf(chips == "", "", "<div style=\"display:flex; gap:6px; margin-bottom:10px; flex-wrap:wrap;\">" + chips + "</div>")

// ---------- CFCL procedure tracker (DRC geocfcl records) --------------------------------------------
var tracker = ""
if (fromGeocfcl) {
  var stages = ["Identification communautaire", "Affichage public", "Enquête publique", "Attribution", "Gestion et exploitation"]
  var reach = 0
  var stg = Lower(DefaultValue(f.application_stage, ""))
  if (Find("identification", stg) > -1) { reach = 1 }
  if (Find("affichage", stg) > -1) { reach = 2 }
  if (Find("enqu", stg) > -1) { reach = 3 }
  if (f.status_std == "attributed") { reach = 4 }
  if (Find("gestion", stg) > -1) { reach = 5 }
  var fill = IIf(Find("contestation", stg) > -1, "#c62828", ACCENT)
  var steps = ""
  for (var i = 1; i <= 5; i++) { steps += "<div style=\"flex:1; height:9px; border-radius:3px; background:" + IIf(i <= reach, fill, "#e0e0e0") + ";\"></div>" }
  tracker = "<div style=\"background:#f5f9f9; border-radius:6px; padding:8px 12px; margin-bottom:10px; border:1px solid #e0e0e0;\">"
    + "<div style=\"display:flex; justify-content:space-between; font-size:9px; color:#999; margin-bottom:4px; text-transform:uppercase; letter-spacing:0.5px;\"><span>Demande</span><span>Gestion</span></div>"
    + "<div style=\"display:flex; gap:3px;\">" + steps + "</div>"
    + "<div style=\"text-align:center; font-size:11px; font-weight:700; color:" + fill + "; margin-top:5px;\">Étape " + Text(reach) + " sur 5 — " + txt(DefaultValue(f.application_stage, f.status_raw)) + "</div></div>"
}

// ---------- breadcrumb -------------------------------------------------------------------------------
var crumbs = txt(f.country)
if (!isBlank(f.province)) { crumbs += " › " + txt(f.province) }
if (!isBlank(f.admin2)) { crumbs += " › " + txt(f.admin2) }
if (!isBlank(f.admin3)) { crumbs += " › " + txt(f.admin3) }
if (!isBlank(f.admin4)) { crumbs += " › " + txt(f.admin4) }
var crumbHtml = "<div style=\"background:#e8f5e9; border-radius:6px; padding:7px 8px; margin-bottom:10px; font-size:12px; color:#2e7d32; font-weight:500;\">&#128205; " + crumbs + "</div>"

// ---------- related data -----------------------------------------------------------------------------
var uid = f.src_uid
var zoneRows = null; var nZones = 0; var totZones = 0
var zs = fsGet(NAME_ZONING, ID_ZONING, ["parent_uid", "zone_type_std", "area_calc_ha", "retired"], false)
if (!IsEmpty(zs)) {
  var mine = Filter(zs, "parent_uid = @uid AND retired = 0")
  nZones = Count(mine)
  if (nZones > 0) {
    zoneRows = OrderBy(GroupBy(mine, ["zone_type_std"], [{ name: "n", expression: "1", statistic: "COUNT" }, { name: "ha", expression: "area_calc_ha", statistic: "SUM" }]), "ha DESC")
    for (var z in zoneRows) { totZones += DefaultValue(z.ha, 0) }
  }
}
var docs = null; var nDocs = 0
var dt = fsGet(NAME_DOCS, ID_DOCS, ["parent_uid", "title", "category_std", "url", "size_bytes", "date_doc", "file_name", "retired"], false)
if (!IsEmpty(dt)) { docs = OrderBy(Filter(dt, "parent_uid = @uid AND retired = 0"), "category_std ASC, date_doc DESC, title ASC"); nDocs = Count(docs) }
if (nDocs == 0 && !isBlank(f.doc_count)) { nDocs = f.doc_count }

// ---------- tiles ----------------------------------------------------------------------------------------
var area = f.area_adm_ha; var areaLbl = "Superficie administrative"
if (isBlank(area) || area <= 0) { area = f.area_sig_ha; areaLbl = "Superficie SIG" }
if (isBlank(area) || area <= 0) { area = f.area_calc_ha; areaLbl = "Superficie calculée" }
var attrDate = IIf(IsEmpty(f.date_attr), f.date_conv_def, f.date_attr)
var tiles = "<div style=\"display:flex; gap:6px; margin-bottom:10px; flex-wrap:wrap;\">"
  + tile(DefaultValue(haTxt(area), "—"), areaLbl, ACCENT)
  + tile(IIf(nZones > 0, Text(nZones), "—"), "Zones du PSG", "#2e7d32")
  + tile(IIf(nDocs > 0, Text(nDocs), "—"), "Documents", "#1565c0")
  + tile(IIf(IsEmpty(attrDate), "—", Text(Date(attrDate), "YYYY")), "Attribution", "#607d8b") + "</div>"

// ---------- zoning donut ---------------------------------------------------------------------------------------
var zoningCard = ""
if (nZones > 0 && totZones > 0) {
  var grad = ""; var cum = 0; var legend = ""
  for (var z in zoneRows) {
    var zz = cat(ZONE, z.zone_type_std, ["Autre", "#607d8b"])
    var share = Round(100 * DefaultValue(z.ha, 0) / totZones, 1)
    var start = cum; cum = Round(cum + share, 1)
    if (grad != "") { grad += ", " }
    grad += zz[1] + " " + start + "% " + cum + "%"
    legend += "<div style=\"display:flex; justify-content:space-between; font-size:11px; margin-bottom:3px;\">"
      + "<span><span style=\"display:inline-block; width:10px; height:10px; background:" + zz[1] + "; border-radius:2px; margin-right:6px;\"></span>" + txt(zz[0]) + " <span style=\"color:#999;\">(" + Text(z.n) + ")</span></span>"
      + "<span style=\"font-weight:700; color:" + zz[1] + ";\">" + haTxt(z.ha) + " · " + share + " %</span></div>"
  }
  if (cum < 100) { grad += ", #e0e0e0 " + cum + "% 100%" }
  zoningCard = "<div style=\"background:#f7fafa; border-left:4px solid #2e7d32; border-radius:4px; margin-bottom:10px; padding:8px 10px 8px 8px;\">"
    + "<div style=\"font-size:10px; font-weight:700; color:#2e7d32; text-transform:uppercase; letter-spacing:0.8px; margin-bottom:8px;\">Zonage du plan simple de gestion · " + Text(nZones) + " zone(s)</div>"
    + "<div style=\"display:flex; align-items:center; gap:14px;\">"
    + "<div style=\"width:84px; height:84px; flex-shrink:0; border-radius:50%; background:conic-gradient(" + grad + "); display:flex; align-items:center; justify-content:center;\">"
    + "<div style=\"width:54px; height:54px; background:white; border-radius:50%; display:flex; align-items:center; justify-content:center; text-align:center;\">"
    + "<div><div style=\"font-size:11px; font-weight:700; color:#2e7d32;\">" + Text(Round(totZones / 1000, 1)) + "k</div><div style=\"font-size:8px; color:#888;\">ha zonés</div></div></div></div>"
    + "<div style=\"flex:1;\">" + legend + "</div></div></div>"
}

// ---------- area comparison ---------------------------------------------------------------------------------------
var maxA = 0
var arrA = [f.area_adm_ha, f.area_sig_ha, f.area_calc_ha, totZones]
for (var ai in arrA) { var av = arrA[ai]; if (!isBlank(av) && av > maxA) { maxA = av } }
var areaCard = section("Comparaison des superficies", "#1565c0",
    bar("Déclarée / administrative", f.area_adm_ha, "#607d8b", maxA) + bar("SIG (source)", f.area_sig_ha, "#1565c0", maxA)
  + bar("Calculée (géodésique)", f.area_calc_ha, ACCENT, maxA) + bar("Zonée dans le PSG", totZones, "#2e7d32", maxA))

// ---------- documents ------------------------------------------------------------------------------------------------
var docsCard = ""
if (!IsEmpty(docs) && Count(docs) > 0) {
  var lastCat = ""; var list = ""; var k = 0
  for (var d in docs) {
    k += 1
    if (k > 60) { break }
    if (d.category_std != lastCat) {
      var cc = cat(DOCCAT, d.category_std, ["Documents", "#78909c"])
      list += "<div style=\"font-size:10px; font-weight:700; color:" + cc[1] + "; text-transform:uppercase; letter-spacing:0.6px; margin:8px 0 4px 0;\">" + cc[0] + "</div>"
      lastCat = d.category_std
    }
    var meta = ""
    if (!isBlank(d.size_bytes)) { meta += Text(Round(d.size_bytes / 1048576, 1)) + " Mo" }
    if (!IsEmpty(d.date_doc)) { meta += IIf(meta == "", "", " · ") + Text(Date(d.date_doc), "YYYY") }
    list += "<div style=\"display:flex; align-items:center; gap:8px; background:#fff; border:1px solid #e0e0e0; border-radius:6px; padding:6px 8px; margin-bottom:4px;\">"
      + "<div style=\"font-size:16px;\">" + docIcon(d.file_name) + "</div>"
      + "<div style=\"flex:1; min-width:0;\"><div style=\"font-size:12px; font-weight:600; color:#1a1a2e;\">" + txt(DefaultValue(d.title, d.file_name)) + "</div>"
      + "<div style=\"font-size:10px; color:#888;\">" + txt(DefaultValue(d.file_name, "")) + IIf(meta == "", "", " · " + meta) + "</div></div>"
      + "<a href=\"" + d.url + "\" target=\"_blank\" style=\"background:#1565c0; color:#fff; padding:4px 10px; border-radius:6px; font-size:11px; font-weight:700; text-decoration:none; white-space:nowrap;\">Ouvrir &#8599;</a></div>"
  }
  if (Count(docs) > 60) { list += "<div style=\"font-size:10px; color:#999;\">… " + Text(Count(docs) - 60) + " autre(s) document(s) non affiché(s)</div>" }
  docsCard = section("Documents · " + Text(Count(docs)), "#1565c0", list)
} else if (nDocs > 0) {
  docsCard = section("Documents · " + Text(nDocs), "#1565c0", "<div style=\"font-size:11px; color:#888;\">" + Text(nDocs) + " document(s) référencé(s). Ajoutez la table <b>CB_Documents</b> à la carte (ou renseignez ITEM_ID) pour afficher les liens.</div>")
}

// ---------- sections ----------------------------------------------------------------------------------------------------
var actorRows = row("Communauté / attributaire", txt(DefaultValue(f.community, f.holder))) + row("Gestionnaire", IIf(!isBlank(f.holder) && f.holder != f.community, txt(f.holder), ""))
  + row("Exploitant / société", txt(f.operator)) + row("Accompagnement", txt(f.supporting_org)) + row("Mode de gestion", txt(f.mgmt_mode)) + row("Référence", txt(f.reference))
  + row("Statut (source)", txt(f.status_raw)) + row("Plan simple de gestion", txt(f.psg_status))
if (fromGeocfcl && !isBlank(f.src_oid)) {
  actorRows += row("Base de données CFCL", "<a href=\"https://rdc.geocfcl.org/applications/" + Text(f.src_oid) + "/\" target=\"_blank\" style=\"color:#1565c0;\">Ouvrir le dossier sur rdc.geocfcl.org &#8599;</a>")
}
var dateRows = row("Attribution", dateTxt(f.date_attr)) + row("Convention provisoire", dateTxt(f.date_conv_prov)) + row("Convention définitive", dateTxt(f.date_conv_def))
  + row("Plan simple de gestion", dateTxt(f.date_plan)) + row("Échéance", dateTxt(f.date_expiry))
var native = Dictionary()
if (!isBlank(f.src_attrs_json)) { native = Dictionary(f.src_attrs_json) }
var fields = cat(NATIVE, iso, [])
var nativeRows = ""
for (var i in fields) {
  var key = fields[i][0]
  if (HasKey(native, key) && !isBlank(native[key])) {
    var v = native[key]
    if (TypeOf(v) == "Number" && v > 100000000000) { v = dateTxt(v) }
    if (TypeOf(v) == "Boolean") { v = IIf(v, "oui", "non") }
    nativeRows += row(fields[i][1], txt(v))
  }
}
var footer = "<div style=\"text-align:center; font-size:10px; color:#aaa; margin-top:10px; padding-top:8px; border-top:1px solid #eee;\">Source : " + txt(f.src_layer)
  + IIf(isBlank(f.src_vintage), "", " (" + txt(f.src_vintage) + ")") + IIf(IsEmpty(f.src_last_edit), "", " &nbsp;|&nbsp; édition source " + dateTxt(f.src_last_edit))
  + IIf(IsEmpty(f.loaded_at), "", " &nbsp;|&nbsp; chargé le " + dateTxt(f.loaded_at)) + IIf(isBlank(f.dedup_of), "", " &nbsp;|&nbsp; doublon de " + txt(f.dedup_of))
  + IIf(f.geom_quality == "multipart", " &nbsp;|&nbsp; géométrie multi-parties", "") + " &nbsp;|&nbsp; situation " + txt(f.situation) + "</div>"

var popup = "<div style=\"font-family:Segoe UI,sans-serif; font-size:13px; color:#1a1a2e;\">"
  + banner + chipsHtml + tracker + crumbHtml + tiles + zoningCard + areaCard
  + section("Communauté et gestion", ACCENT, table(actorRows))
  + section("Dates", "#607d8b", table(dateRows))
  + section("Attributs nationaux · " + txt(f.country), "#00838f", table(nativeRows))
  + docsCard + footer + "</div>"
return { type: "text", text: popup }

// ============================================================
//  Zoning popup — one expression for CB_Concession_Zoning (1), CB_Community_Forest_Zoning (3)
//  and CB_Local_Territory_Zoning (5); the parent layer is derived from $feature.layer.
//  Reads the parent layer and the sibling zones FROM THE WEB MAP by name (or SOURCE = "portal").
// ============================================================
Expects($feature, "*")

var SOURCE     = "map"
var PORTAL_URL = "https://geosmarthosting.undp.org/portal"
var ITEM_ID    = "PASTE_ITEM_ID_HERE"
var PARENT = { "concession_zoning": ["Logging concessions - Limits", 0, "Concession / titre forestier", "#5d4037"],
               "community_forest_zoning": ["Community forests - Limits", 2, "Forêt communautaire", "#1b5e20"],
               "local_territory_zoning": ["CB_Local_Territories", 4, "Terroir villageois (PSAT)", "#37474f"] }
var SELF = { "concession_zoning": ["CB_Concession_Zoning", 1], "community_forest_zoning": ["Community forests - Zoning", 3], "local_territory_zoning": ["CB_Local_Territory_Zoning", 5] }

function isBlank(x) { return IsEmpty(x) || Text(x) == "" || Text(x) == "null" }
function txt(x) { if (isBlank(x)) { return "" } var s = Text(x); s = Replace(s, "&", "&amp;"); s = Replace(s, "<", "&lt;"); return Replace(s, ">", "&gt;") }
function haTxt(x) { if (isBlank(x)) { return "" } var n = Number(x); if (IsNan(n) || n <= 0) { return "" } return Text(Round(n, 0), "#,###") + " ha" }
function dateTxt(x) { if (IsEmpty(x)) { return "" } return Text(Date(x), "DD MMM YYYY") }
function cat(dict, key, dflt) { if (!isBlank(key) && HasKey(dict, key)) { return dict[key] } return dflt }
function fsGet(name, id, fields, geom) {
  if (SOURCE == "portal" && ITEM_ID != "PASTE_ITEM_ID_HERE") { return FeatureSetByPortalItem(Portal(PORTAL_URL), ITEM_ID, id, fields, geom) }
  return FeatureSetByName($map, name, fields, geom)
}
function row(label, value) {
  if (isBlank(value)) { return "" }
  return "<tr><td style=\"color:#666; width:44%; padding:4px 6px 4px 0; font-size:12px; vertical-align:top;\">" + label + "</td><td style=\"font-weight:600; font-size:12px; padding:4px 0; vertical-align:top;\">" + value + "</td></tr>"
}
function table(rows) { if (isBlank(rows)) { return "" } return "<table style=\"width:100%; border-collapse:collapse;\">" + rows + "</table>" }
function section(title, accent, body) {
  if (isBlank(body)) { return "" }
  return "<div style=\"background:#f7fafa; border-left:4px solid " + accent + "; border-radius:4px; margin-bottom:10px; padding:8px 10px 8px 8px;\">"
       + "<div style=\"font-size:10px; font-weight:700; color:" + accent + "; text-transform:uppercase; letter-spacing:0.8px; margin-bottom:8px;\">" + title + "</div>" + body + "</div>"
}
function chip(label, bg, fg) { return "<div style=\"background:" + bg + "; color:" + fg + "; padding:5px 10px; border-radius:6px; font-size:11px; font-weight:700;\">" + label + "</div>" }
function tile(value, label, color) {
  return "<div style=\"flex:1 1 30%; min-width:80px; background:#f5f9f9; border:1px solid #e0e0e0; border-radius:6px; padding:8px 4px; text-align:center;\">"
       + "<div style=\"font-size:16px; font-weight:700; color:" + color + ";\">" + value + "</div><div style=\"font-size:9px; color:#666; text-transform:uppercase; letter-spacing:0.5px; margin-top:2px;\">" + label + "</div></div>"
}

var ZONE = { "production": ["Production", "#c98a2b", "Exploitation forestière / production ligneuse"], "conservation": ["Conservation", "#2e7d32", "Conservation de la biodiversité"],
  "protection": ["Protection", "#00695c", "Protection (berges, pentes, sites sacrés, aires protégées)"], "community_development": ["Développement rural / communautaire", "#a0522d", "Usages des communautés (chasse, pêche, cueillette, PFNL)"],
  "agriculture": ["Agriculture", "#d4b106", "Cultures, élevage, agroforesterie, pisciculture"], "habitat": ["Habitat", "#8d6e63", "Villages, campements"],
  "savanna_protection": ["Mise en défens / reboisement", "#7cb342", "Savanes mises en défens, reboisement, RNA"], "concession": ["Zone concédée", "#5d4037", "Concessions et titres tiers"],
  "community_forest": ["Forêt communautaire", "#43a047", "CFCL / forêt des communautés locales"], "conflict": ["Zone conflictuelle", "#d32f2f", "Litiges"],
  "research": ["Recherche", "#7e57c2", "Recherche scientifique"], "unclassified": ["Non classée", "#bdbdbd", "Zonage non renseigné dans la source"], "other": ["Autre", "#607d8b", "Autre affectation"] }
var STATUS = { "attributed": ["Attribuée / validée", "#e8f5e9", "#2e7d32"], "provisional": ["Provisoire", "#fff8e1", "#ff8f00"], "final": ["Définitive", "#e8f5e9", "#1b5e20"], "in_process": ["En cours", "#e3f2fd", "#1565c0"],
  "not_attributed": ["Non attribuée", "#eceff1", "#607d8b"], "rejected": ["Rejetée", "#ffebee", "#c62828"], "expired": ["Expirée", "#efebe9", "#6d4c41"], "unknown": ["Non renseigné", "#eceff1", "#546e7a"] }
var FLAG = { "CMR": "🇨🇲", "CAF": "🇨🇫", "COD": "🇨🇩", "COG": "🇨🇬", "GNQ": "🇬🇶", "GAB": "🇬🇦" }

var f = $feature
var lay = DefaultValue(f.layer, "concession_zoning")
var P = cat(PARENT, lay, ["Logging concessions - Limits", 0, "Unité parente", "#5d4037"])
var S = cat(SELF, lay, ["Logging concessions - Zoning", 1])
var z = cat(ZONE, f.zone_type_std, ["Autre", "#607d8b", ""])
var ACCENT = z[1]
var title = DefaultValue(f.zone_name, DefaultValue(f.zone_type_raw, z[0]))

var banner = "<div style=\"background:" + ACCENT + "; color:white; padding:10px 12px; border-radius:6px 6px 0 0; margin:0 0 10px 0;\">"
  + "<div style=\"font-size:15px; font-weight:700;\">" + txt(title) + "</div>"
  + "<div style=\"font-size:11px; opacity:0.9; margin-top:2px;\">" + cat(FLAG, f.iso3, "") + " " + txt(f.country) + IIf(!isBlank(f.parent_name), " — " + txt(f.parent_name), "") + "</div>"
  + "<div style=\"font-size:10px; opacity:0.9; margin-top:4px; text-transform:uppercase; letter-spacing:0.8px;\">" + txt(z[0]) + " · " + txt(f.sub_type_raw) + "</div></div>"

var st = cat(STATUS, f.status_std, null)
var chips = chip(txt(z[0]), "#fff", ACCENT)
if (!IsEmpty(st)) { chips += chip(st[0], st[1], st[2]) }
if (f.geom_quality == "bbox") { chips += chip("&#9888; Emprise approximative", "#fbe9e7", "#d84315") }
if (isBlank(f.parent_uid)) { chips += chip("Unité parente non identifiée", "#eceff1", "#607d8b") }
if (f.retired == 1) { chips += chip("Retiré de la source", "#ffebee", "#c62828") }
var chipsHtml = "<div style=\"display:flex; gap:6px; margin-bottom:10px; flex-wrap:wrap;\">" + chips + "</div>"

var crumbs = txt(f.country)
if (!isBlank(f.province)) { crumbs += " › " + txt(f.province) }
if (!isBlank(f.admin2)) { crumbs += " › " + txt(f.admin2) }
if (!isBlank(f.admin3)) { crumbs += " › " + txt(f.admin3) }
if (!isBlank(f.admin4)) { crumbs += " › " + txt(f.admin4) }
var crumbHtml = "<div style=\"background:#f1f8e9; border-radius:6px; padding:7px 8px; margin-bottom:10px; font-size:12px; color:#33691e; font-weight:500;\">&#128205; " + crumbs + "</div>"

// ---------- parent and siblings ---------------------------------------------------------------------
var puid = f.parent_uid
var parent = null; var sib = null; var nSib = 0; var totSib = 0; var rows = null
if (!isBlank(puid)) {
  var pfs = fsGet(P[0], P[1], ["src_uid", "name", "reference", "holder", "community", "status_std", "area_calc_ha", "area_adm_ha", "sub_type_raw", "doc_count"], false)
  if (!IsEmpty(pfs)) { parent = First(Filter(pfs, "src_uid = @puid")) }
  var zfs = fsGet(S[0], S[1], ["parent_uid", "zone_type_std", "area_calc_ha", "retired"], false)
  if (!IsEmpty(zfs)) {
    sib = Filter(zfs, "parent_uid = @puid AND retired = 0")
    nSib = Count(sib)
    if (nSib > 0) {
      rows = OrderBy(GroupBy(sib, ["zone_type_std"], [{ name: "n", expression: "1", statistic: "COUNT" }, { name: "ha", expression: "area_calc_ha", statistic: "SUM" }]), "ha DESC")
      for (var r in rows) { totSib += DefaultValue(r.ha, 0) }
    }
  }
}

var area = f.area_sig_ha
if (isBlank(area) || area <= 0) { area = f.area_adm_ha }
if (isBlank(area) || area <= 0) { area = f.area_calc_ha }
var share = IIf(totSib > 0 && !isBlank(f.area_calc_ha), Round(100 * f.area_calc_ha / totSib, 1), null)
var tiles = "<div style=\"display:flex; gap:6px; margin-bottom:10px; flex-wrap:wrap;\">"
  + tile(DefaultValue(haTxt(area), "—"), "Superficie de la zone", ACCENT)
  + tile(IIf(IsEmpty(share), "—", Text(share) + " %"), "Part de l'unité", "#2e7d32")
  + tile(IIf(nSib > 0, Text(nSib), "—"), "Zones dans l'unité", "#607d8b") + "</div>"

var meaning = "<div style=\"font-size:11px; color:#4b5563; margin:-4px 0 10px 0;\">" + txt(z[2]) + "</div>"

// ---------- donut of the unit ---------------------------------------------------------------------------
var donut = ""
if (nSib > 1 && totSib > 0) {
  var grad = ""; var cum = 0; var legend = ""
  for (var r in rows) {
    var zz = cat(ZONE, r.zone_type_std, ["Autre", "#607d8b", ""])
    var sh = Round(100 * DefaultValue(r.ha, 0) / totSib, 1)
    var start = cum; cum = Round(cum + sh, 1)
    if (grad != "") { grad += ", " }
    grad += zz[1] + " " + start + "% " + cum + "%"
    var me = IIf(r.zone_type_std == f.zone_type_std, " &#9664;", "")
    legend += "<div style=\"display:flex; justify-content:space-between; font-size:11px; margin-bottom:3px;\"><span><span style=\"display:inline-block; width:10px; height:10px; background:" + zz[1] + "; border-radius:2px; margin-right:6px;\"></span>"
      + txt(zz[0]) + " <span style=\"color:#999;\">(" + Text(r.n) + ")</span>" + me + "</span><span style=\"font-weight:700; color:" + zz[1] + ";\">" + haTxt(r.ha) + " · " + sh + " %</span></div>"
  }
  if (cum < 100) { grad += ", #e0e0e0 " + cum + "% 100%" }
  donut = "<div style=\"background:#f7fafa; border-left:4px solid " + P[3] + "; border-radius:4px; margin-bottom:10px; padding:8px 10px 8px 8px;\">"
    + "<div style=\"font-size:10px; font-weight:700; color:" + P[3] + "; text-transform:uppercase; letter-spacing:0.8px; margin-bottom:8px;\">Zonage de l'unité · " + Text(nSib) + " zones · " + haTxt(totSib) + "</div>"
    + "<div style=\"display:flex; align-items:center; gap:14px;\"><div style=\"width:84px; height:84px; flex-shrink:0; border-radius:50%; background:conic-gradient(" + grad + "); display:flex; align-items:center; justify-content:center;\">"
    + "<div style=\"width:54px; height:54px; background:white; border-radius:50%; display:flex; align-items:center; justify-content:center; text-align:center;\"><div><div style=\"font-size:11px; font-weight:700; color:" + ACCENT + ";\">" + IIf(IsEmpty(share), "", Text(share) + " %") + "</div><div style=\"font-size:8px; color:#888;\">cette zone</div></div></div></div>"
    + "<div style=\"flex:1;\">" + legend + "</div></div></div>"
}

// ---------- parent card ------------------------------------------------------------------------------------
var parentCard = ""
if (!IsEmpty(parent)) {
  var pst = cat(STATUS, parent.status_std, null)
  var prow = row("Nom", "<b>" + txt(DefaultValue(parent.name, parent.reference)) + "</b>" + IIf(!isBlank(parent.reference) && parent.reference != parent.name, " · " + txt(parent.reference), ""))
    + row("Type", txt(parent.sub_type_raw)) + row("Attributaire / communauté", txt(DefaultValue(parent.holder, parent.community)))
    + row("Statut", IIf(IsEmpty(pst), "", "<span style=\"background:" + pst[1] + "; color:" + pst[2] + "; padding:2px 8px; border-radius:6px; font-size:11px; font-weight:700;\">" + pst[0] + "</span>"))
    + row("Superficie", haTxt(IIf(isBlank(parent.area_adm_ha), parent.area_calc_ha, parent.area_adm_ha)))
    + row("Documents", IIf(!isBlank(parent.doc_count) && parent.doc_count > 0, Text(parent.doc_count) + " document(s) — voir la fiche de l'unité", ""))
  parentCard = section(P[2], P[3], table(prow))
} else if (isBlank(f.parent_uid)) {
  parentCard = section(P[2], "#9e9e9e", "<div style=\"font-size:11px; color:#888;\">Unité parente non identifiée" + IIf(isBlank(f.parent_ref), "", " (référence source : " + txt(f.parent_ref) + ")") + ".</div>")
}

var zoneRows = row("Affectation (source)", txt(f.zone_type_raw)) + row("Raison / usage", txt(f.zone_reason)) + row("Code", txt(f.zone_code)) + row("Statut (source)", txt(f.status_raw))
  + row("Exploitant", txt(f.operator)) + row("Superficie SIG (source)", haTxt(f.area_sig_ha)) + row("Superficie administrative", haTxt(f.area_adm_ha)) + row("Superficie calculée", haTxt(f.area_calc_ha))
  + row("Date du plan", dateTxt(f.date_plan)) + row("Programme", txt(f.programme)) + row("Financement / agence", txt(DefaultValue(f.funder, "")) + IIf(isBlank(f.agency), "", " · " + txt(f.agency)))
  + row("Partenaire", txt(f.partner)) + row("Année de référence", IIf(isBlank(f.year_ref), "", Text(f.year_ref)))

var footer = "<div style=\"text-align:center; font-size:10px; color:#aaa; margin-top:10px; padding-top:8px; border-top:1px solid #eee;\">Source : " + txt(f.src_layer)
  + IIf(isBlank(f.src_file), "", " · " + txt(f.src_file)) + IIf(isBlank(f.src_vintage), "", " (" + txt(f.src_vintage) + ")") + IIf(IsEmpty(f.loaded_at), "", " &nbsp;|&nbsp; chargé le " + dateTxt(f.loaded_at))
  + " &nbsp;|&nbsp; situation " + txt(f.situation) + "</div>"

var popup = "<div style=\"font-family:Segoe UI,sans-serif; font-size:13px; color:#1a1a2e;\">" + banner + chipsHtml + meaning + crumbHtml + tiles + donut + parentCard
  + section("Zone", ACCENT, table(zoneRows)) + footer + "</div>"
return { type: "text", text: popup }

renderer.valueExpression:
// =====================================================================================
//  Symbology · unique values on an Arcade expression, for the three zoning layers
//  (CB_Concession_Zoning, CB_Community_Forest_Zoning, CB_Local_Territory_Zoning).
//  Map Viewer: Styles > + Expression > paste > Types (unique symbols).
//  Pro: Symbology > Unique Values > Set an expression.
//  Returns the display label; apply the colours listed in README_arcade.md (same palette as the popups).
// =====================================================================================
var LABEL = {
  'production':            'Production (exploitation ligneuse)',
  'conservation':          'Conservation',
  'protection':            'Protection',
  'community_development': 'Développement rural / communautaire',
  'agriculture':           'Agriculture et agroforesterie',
  'habitat':               'Habitat',
  'savanna_protection':    'Mise en défens / reboisement',
  'concession':            'Zone concédée (titres tiers)',
  'community_forest':      'Forêt communautaire',
  'conflict':              'Zone conflictuelle',
  'research':              'Recherche',
  'unclassified':          'Non classée',
  'other':                 'Autre'
};
var k = $feature.zone_type_std;
if (IsEmpty(k) || !HasKey(LABEL, k)) { return 'Non classée'; }
if ($feature.retired == 1) { return 'Retiré de la source'; }
return LABEL[k];

expressionInfo.expression:
// ============================================================
// PES Contracts Full Popup
// Existing four-layer deployment
//
// Main layer:
//   - PES Contracts
//
// Optional lookup layer in the same web map:
//   - PES Applications - Points
//
// IMPORTANT:
// The previous line Expects($feature, "*") was removed because
// some ArcGIS Enterprise / Arcade popup test profiles reject the
// wildcard and return: Unexpected token '*'.
// ============================================================


// ============================================================
// HELPERS
// ============================================================

function hasField(fieldName) {
    return HasKey($feature, fieldName);
}

function val(fieldName) {
    if (hasField(fieldName)) {
        return $feature[fieldName];
    }

    return null;
}

function objVal(obj, fieldName) {
    if (obj == null) {
        return null;
    }

    if (HasKey(obj, fieldName)) {
        return obj[fieldName];
    }

    return null;
}

function firstValue(primaryValue, fallbackValue) {
    if (
        IsEmpty(primaryValue) ||
        primaryValue == null ||
        primaryValue == "" ||
        primaryValue == "[]" ||
        primaryValue == "Na" ||
        primaryValue == "NA" ||
        primaryValue == "N/A" ||
        primaryValue == "null"
    ) {
        return fallbackValue;
    }

    return primaryValue;
}

function isBlank(x) {
    if (
        IsEmpty(x) ||
        x == null ||
        x == "" ||
        x == "[]" ||
        x == "Na" ||
        x == "NA" ||
        x == "N/A" ||
        x == "null"
    ) {
        return true;
    }

    return false;
}

function txt(x) {
    if (isBlank(x)) {
        return "";
    }

    return Text(x);
}

function numField(fieldName) {
    var x = val(fieldName);

    if (isBlank(x)) {
        return 0;
    }

    var n = Number(x);

    if (IsNan(n)) {
        return 0;
    }

    return n;
}

function numValue(x) {
    if (isBlank(x)) {
        return 0;
    }

    var n = Number(x);

    if (IsNan(n)) {
        return 0;
    }

    return n;
}

function dateTxt(fieldName) {
    var x = val(fieldName);

    if (isBlank(x)) {
        return "";
    }

    return Text(Date(x), "DD MMM YYYY");
}

function dateValueTxt(x) {
    if (isBlank(x)) {
        return "";
    }

    return Text(Date(x), "DD MMM YYYY");
}

function areaTxt(x, decimals) {
    var n = Number(x);

    if (IsNan(n) || n == 0) {
        return "";
    }

    return Text(Round(n, decimals)) + " ha";
}

function pctTxt(x, decimals) {
    var n = Number(x);

    if (IsNan(n) || n == 0) {
        return "";
    }

    return Text(Round(n, decimals)) + "%";
}

function numberTxt(x, decimals) {
    var n = Number(x);

    if (IsNan(n) || n == 0) {
        return "";
    }

    return Text(Round(n, decimals));
}

function containsTxt(sourceText, searchText) {
    if (isBlank(sourceText)) {
        return false;
    }

    return Find(Lower(Text(searchText)), Lower(Text(sourceText)), 0) > -1;
}

function cleanList(raw) {
    if (isBlank(raw)) {
        return "";
    }

    var s = Text(raw);
    s = Replace(s, "[", "");
    s = Replace(s, "]", "");
    s = Replace(s, "\"", "");

    var items = Split(s, ",");
    var result = "";

    for (var i = 0; i < Count(items); i++) {
        var item = Trim(items[i]);

        if (!isBlank(item)) {
            if (result != "") {
                result = result + "<br>";
            }

            result = result + item;
        }
    }

    return result;
}

function extractValue(entry, keyName) {
    var pattern = "\"" + keyName + "\":";
    var parts = Split(entry, pattern);

    if (Count(parts) <= 1) {
        return "";
    }

    var right = Trim(parts[1]);

    if (Left(right, 1) == "\"") {
        var quotedParts = Split(right, "\"");

        if (Count(quotedParts) > 1) {
            return quotedParts[1];
        }
    }

    var commaPos = Find(",", right, 0);
    var bracePos = Find("}", right, 0);
    var endPos = -1;

    if (commaPos > -1 && bracePos > -1) {
        if (commaPos < bracePos) {
            endPos = commaPos;
        } else {
            endPos = bracePos;
        }
    } else if (commaPos > -1) {
        endPos = commaPos;
    } else if (bracePos > -1) {
        endPos = bracePos;
    }

    if (endPos > -1) {
        return Trim(Left(right, endPos));
    }

    return Trim(right);
}

function densityList(raw, wantedType) {
    if (isBlank(raw)) {
        return "";
    }

    var s = Text(raw);
    s = Replace(s, "[", "");
    s = Replace(s, "]", "");

    var entries = Split(s, "},{");
    var result = "";

    for (var i = 0; i < Count(entries); i++) {
        var entry = entries[i];

        if (Left(entry, 1) != "{") {
            entry = "{" + entry;
        }

        if (Right(entry, 1) != "}") {
            entry = entry + "}";
        }

        var name = extractValue(entry, "Name");
        var itemType = extractValue(entry, "Type");
        var density = extractValue(entry, "Density");

        if (!isBlank(name)) {
            if (isBlank(wantedType) || Lower(itemType) == Lower(wantedType)) {
                if (result != "") {
                    result = result + "<br>";
                }

                if (!isBlank(density)) {
                    result = result + name + " - " + density + "/ha";
                } else {
                    result = result + name;
                }
            }
        }
    }

    return result;
}

function aggregatorList(raw) {
    if (isBlank(raw)) {
        return "";
    }

    var s = Text(raw);
    s = Replace(s, "[", "");
    s = Replace(s, "]", "");

    var entries = Split(s, "},{");
    var result = "";

    for (var i = 0; i < Count(entries); i++) {
        var entry = entries[i];

        if (Left(entry, 1) != "{") {
            entry = "{" + entry;
        }

        if (Right(entry, 1) != "}") {
            entry = entry + "}";
        }

        var full = extractValue(entry, "EntityFullName");
        var acronym = extractValue(entry, "EntityAcronym");

        if (!isBlank(full)) {
            if (result != "") {
                result = result + "<br>";
            }

            result = result + full;

            if (!isBlank(acronym)) {
                result = result + " (" + acronym + ")";
            }
        }
    }

    return result;
}

function row(label, value) {
    if (isBlank(value) || value == 0 || value == "0") {
        return "";
    }

    return "<tr>"
        + "<td style=\"color:#666; width:48%; padding:4px 0; font-size:12px; vertical-align:top;\">" + label + "</td>"
        + "<td style=\"font-weight:600; font-size:12px; padding:4px 0; vertical-align:top;\">" + value + "</td>"
        + "</tr>";
}

function table(rows) {
    if (isBlank(rows)) {
        return "";
    }

    return "<table style=\"width:100%; border-collapse:collapse;\">" + rows + "</table>";
}

function section(title, accentColor, body) {
    if (isBlank(body)) {
        return "";
    }

    return "<div style=\"background:#f7fafa; border-left:4px solid " + accentColor + "; border-radius:4px; margin-bottom:10px; padding:8px 0px 8px 8px;\">"
        + "<div style=\"font-size:10px; font-weight:700; color:" + accentColor + "; text-transform:uppercase; letter-spacing:0.8px; margin-bottom:8px;\">" + title + "</div>"
        + body
        + "</div>";
}

function chip(labelText, bg, fg) {
    return "<div style=\"flex:1; text-align:center; background:" + bg + "; color:" + fg
        + "; padding:5px 4px; border-radius:6px; font-size:11px; font-weight:700;\">"
        + labelText
        + "</div>";
}

function areaBar(labelText, value, barColor, maxArea) {
    if (value <= 0 || maxArea <= 0) {
        return "";
    }

    var barW = Round((value / maxArea) * 200, 0);

    if (barW < 0) {
        barW = 0;
    }

    if (barW > 200) {
        barW = 200;
    }

    var emptyW = 200 - barW;

    return "<div style=\"margin-bottom:8px;\">"
        + "<div style=\"display:flex; justify-content:space-between; font-size:10px; color:#555; margin-bottom:3px;\">"
        + "<span style=\"font-weight:600;\">" + labelText + "</span>"
        + "<span style=\"font-weight:700; color:" + barColor + ";\">" + Round(value, 3) + " ha</span>"
        + "</div>"
        + "<div style=\"display:flex; height:14px; border-radius:4px; overflow:hidden;\">"
        + "<div style=\"width:" + barW + "px; background:" + barColor + "; height:14px;\"></div>"
        + "<div style=\"width:" + emptyW + "px; background:#e0e0e0; height:14px;\"></div>"
        + "</div>"
        + "</div>";
}


// ============================================================
// CORE CONTRACT VALUES
// ============================================================

var contractCode = txt(firstValue(val("contractcode"), val("ContractCode")));
var contractStatus = txt(firstValue(val("contractstatus"), val("ContractStatus")));
var contractStart = firstValue(val("contractstartdate"), val("ContractStartDate"));
var contractEnd = firstValue(val("contractenddate"), val("ContractEndDate"));
var contractDuration = txt(firstValue(val("contractduration"), val("ContractDuration")));

var applicationCode = txt(firstValue(val("applicationcode"), firstValue(val("ApplicationCode"), val("applicationid"))));
var applicationId = txt(firstValue(val("applicationid"), val("ApplicationId")));

var declaredArea = numValue(firstValue(val("areadeclaredbyplanter"), val("AreaDeclaredByPlanter")));
var contractedArea = numValue(firstValue(val("contractedpesarea"), val("ContractedPESArea")));

var plantedArea = numValue(firstValue(val("plantedareameasured"), val("PlantedAreaMeasured")));
var unplantedArea = numValue(firstValue(val("unplantedarea"), val("UnplantedArea")));
var observedTrees = numValue(firstValue(val("observednumberoftrees"), val("ObservedNumberOfTrees")));

var observedCoverPct = numValue(firstValue(val("observedlandcoverpercentage"), val("ObservedLandCoverPercentage")));
var observedCoverHa = numValue(firstValue(val("observedlandcoverha"), val("ObservedLandCoverHa")));
var observedTreeDensity = numValue(firstValue(val("observedtreedensity"), val("ObservedTreeDensity")));
var observedBasalArea = numValue(firstValue(val("observedbasalarea"), val("ObservedBasalArea")));

var initialCoverHa = numValue(firstValue(val("initiallandcoverinha"), val("InitialLandCoverInHa")));
var initialCoverPct = numValue(firstValue(val("initiallandcoverinpercentage"), val("InitialLandCoverInPercentage")));

var hasMonitoring = numValue(firstValue(val("hasmonitoring"), val("HasMonitoring")));
var overdue = numValue(firstValue(val("monitoringoverdue"), val("MonitoringOverdue")));

var visitTotal = numValue(firstValue(val("visitcount"), val("VisitCount")));
var visitsDone = numValue(firstValue(val("visitscompleted"), val("VisitsCompleted")));

var activityType = txt(firstValue(val("activitytype"), val("ActivityType")));
var activityText = Lower(activityType);


// ============================================================
// OPTIONAL APPLICATION LOOKUP FROM POINTS VIEW
// ============================================================

var app = null;

if (!isBlank(contractCode)) {
    var appFs = Filter(
        FeatureSetByName(
            $map,
            "PES Applications - Points",
            [
                "applicationcode",
                "applicationid",
                "contractcode",
                "stage",
                "stageorder",
                "stagecategory",
                "applicationstatus",
                "applicationdate",
                "estimatedarea",
                "activitytype",
                "country",
                "province",
                "territory",
                "village",
                "beneficiarytype",
                "beneficiarystatus",
                "beneficiarygender",
                "familysituation",
                "dependents",
                "numberofcommunitymembers",
                "projectname",
                "implementingorgname",
                "implementingorgacronym",
                "supportingaggregator"
            ],
            false
        ),
        "contractcode = @contractCode"
    );

    app = First(appFs);
}


// ============================================================
// ENRICHED VALUES FROM CONTRACT OR APPLICATION
// ============================================================

applicationCode = txt(firstValue(applicationCode, firstValue(objVal(app, "applicationcode"), objVal(app, "applicationid"))));

var stageName = txt(firstValue(val("stage"), objVal(app, "stage")));
var stageOrder = numValue(firstValue(val("stageorder"), objVal(app, "stageorder")));
var stageCategory = txt(firstValue(val("stagecategory"), objVal(app, "stagecategory")));
var applicationStatus = txt(firstValue(val("applicationstatus"), objVal(app, "applicationstatus")));
var applicationDate = firstValue(val("applicationdate"), objVal(app, "applicationdate"));

var estimatedArea = numValue(firstValue(val("estimatedarea"), objVal(app, "estimatedarea")));

activityType = txt(firstValue(activityType, objVal(app, "activitytype")));
activityText = Lower(activityType);

var country = txt(firstValue(val("country"), objVal(app, "country")));
var province = txt(firstValue(val("province"), objVal(app, "province")));
var territory = txt(firstValue(val("territory"), objVal(app, "territory")));
var village = txt(firstValue(val("village"), objVal(app, "village")));

var projectName = txt(firstValue(val("projectname"), objVal(app, "projectname")));
var implementingOrgName = txt(firstValue(val("implementingorgname"), objVal(app, "implementingorgname")));
var implementingOrgAcronym = txt(firstValue(val("implementingorgacronym"), objVal(app, "implementingorgacronym")));
var supportingAggregator = firstValue(val("supportingaggregator"), objVal(app, "supportingaggregator"));

var beneficiaryType = txt(firstValue(val("beneficiarytype"), objVal(app, "beneficiarytype")));
var beneficiaryStatus = txt(firstValue(val("beneficiarystatus"), objVal(app, "beneficiarystatus")));
var beneficiaryGender = txt(firstValue(val("beneficiarygender"), objVal(app, "beneficiarygender")));
var familySituation = txt(firstValue(val("familysituation"), objVal(app, "familysituation")));
var dependents = txt(firstValue(val("dependents"), objVal(app, "dependents")));
var numberCommunityMembers = txt(firstValue(val("numberofcommunitymembers"), objVal(app, "numberofcommunitymembers")));


// ============================================================
// ACTIVITY GROUP AND LABELS
// ============================================================

var activityGroup = "generic";

if (
    activityType == "Agroforestry" ||
    containsTxt(activityText, "agroforestry") ||
    containsTxt(activityText, "agroforesterie")
) {
    activityGroup = "agroforestry";
}

if (
    activityType == "Reforestation" ||
    containsTxt(activityText, "reforestation") ||
    containsTxt(activityText, "reboisement")
) {
    activityGroup = "reforestation";
}

if (
    activityType == "NaturalRegenerationSavannah" ||
    activityType == "Natural Regeneration" ||
    containsTxt(activityText, "natural regeneration") ||
    containsTxt(activityText, "regeneration") ||
    containsTxt(activityText, "régénération")
) {
    activityGroup = "natural_regeneration";
}

var activityLabel = "PES Activity";
var mainAreaLabel = "Achieved Area";
var gapAreaLabel = "Gap Area";
var monitoringTitle = "PES Monitoring";

if (activityGroup == "agroforestry") {
    activityLabel = "Agroforestry";
    mainAreaLabel = "Agroforestry Planted Area";
    gapAreaLabel = "Unplanted / Gap Area";
    monitoringTitle = "Agroforestry Monitoring";
}

if (activityGroup == "reforestation") {
    activityLabel = "Reforestation";
    mainAreaLabel = "Planted / Restored Area";
    gapAreaLabel = "Unplanted / Failed Area";
    monitoringTitle = "Reforestation Monitoring";
}

if (activityGroup == "natural_regeneration") {
    activityLabel = "Natural Regeneration - Savannah";
    mainAreaLabel = "Observed Land Cover";
    gapAreaLabel = "Remaining / Non-covered Area";
    monitoringTitle = "Natural Regeneration Monitoring";
}


// ============================================================
// STATUS CHIPS
// ============================================================

var chipsHtml = "";

var conBg = "#fff3e0";
var conFg = "#e65100";

if (contractStatus == "Active") {
    conBg = "#e8f5e9";
    conFg = "#2e7d32";
}

if (contractStatus == "Completed") {
    conBg = "#e3f2fd";
    conFg = "#1565c0";
}

if (contractStatus == "Cancelled" || contractStatus == "Terminated") {
    conBg = "#ffebee";
    conFg = "#c62828";
}

chipsHtml = chipsHtml + chip("Contract: " + DefaultValue(contractStatus, "No status"), conBg, conFg);

if (!isBlank(stageName)) {
    var stageBg = "#eceff1";
    var stageFg = "#607d8b";

    if (stageOrder == 5) {
        stageBg = "#fff8e1";
        stageFg = "#ff8f00";
    }

    if (stageOrder == 6) {
        stageBg = "#f9fbe7";
        stageFg = "#9e9d24";
    }

    if (stageOrder == 7) {
        stageBg = "#e8f5e9";
        stageFg = "#2e7d32";
    }

    if (stageCategory == "Rejected") {
        stageBg = "#ffebee";
        stageFg = "#c62828";
    }

    if (stageCategory == "Archived") {
        stageBg = "#eeeeee";
        stageFg = "#757575";
    }

    chipsHtml = chipsHtml + chip("Stage: " + stageName, stageBg, stageFg);
}

if (overdue == 1) {
    chipsHtml = chipsHtml + chip("&#9888; Visit overdue", "#fbe9e7", "#d84315");
}

var fireCat = txt(firstValue(val("fireriskcategory"), val("FireRiskCategory")));

if (fireCat == "High") {
    chipsHtml = chipsHtml + chip("&#128293; Fire risk: High", "#fff3e0", "#ef6c00");
}

if (fireCat == "Very High") {
    chipsHtml = chipsHtml + chip("&#128293; Fire risk: Very High", "#fbe9e7", "#c62828");
}


// ============================================================
// CONTRACT TIMELINE
// ============================================================

var contractTimeline = "";

if (!isBlank(contractStart) && !isBlank(contractEnd)) {
    var startMs = Number(Date(contractStart));
    var endMs = Number(Date(contractEnd));
    var nowMs = Number(Now());

    var progress = 0;

    if (!IsNan(startMs) && !IsNan(endMs) && endMs > startMs) {
        progress = Round(((nowMs - startMs) / (endMs - startMs)) * 100, 0);
    }

    if (progress < 0) {
        progress = 0;
    }

    if (progress > 100) {
        progress = 100;
    }

    var daysLeft = Round((endMs - nowMs) / 86400000, 0);
    var remaining = "Contract ended";

    if (!IsNan(daysLeft) && daysLeft > 0) {
        remaining = daysLeft + " days remaining";
    }

    var progressColor = "#4caf50";

    if (progress > 75) {
        progressColor = "#ff9800";
    }

    if (progress >= 100) {
        progressColor = "#f44336";
    }

    contractTimeline =
        "<div style=\"background:#f5f9f9; border-radius:6px; padding:8px 12px; margin-bottom:10px; border:1px solid #e0e0e0;\">"
        + "<div style=\"display:flex; justify-content:space-between; font-size:11px; color:#666; margin-bottom:4px;\">"
        + "<span>" + dateValueTxt(contractStart) + "</span>"
        + "<span style=\"font-weight:700; color:" + progressColor + ";\">" + progress + "% complete</span>"
        + "<span>" + dateValueTxt(contractEnd) + "</span>"
        + "</div>"
        + "<div style=\"background:#e0e0e0; border-radius:6px; height:10px; width:100%; overflow:hidden;\">"
        + "<div style=\"background:" + progressColor + "; height:10px; width:" + progress + "%; border-radius:6px;\"></div>"
        + "</div>"
        + "<div style=\"text-align:center; font-size:10px; color:#888; margin-top:4px;\">" + remaining + "</div>"
        + "</div>";
}


// ============================================================
// VISIT SCHEDULE TRACKER
// ============================================================

var visitTracker = "";

if (visitTotal > 0) {
    var visitSegments = "";

    if (visitTotal <= 16) {
        for (var v = 1; v <= visitTotal; v++) {
            var segColor = "#e0e0e0";

            if (v <= visitsDone) {
                segColor = "#2e7d32";
            }

            visitSegments = visitSegments + "<div style=\"flex:1; height:10px; border-radius:2px; background:" + segColor + ";\"></div>";
        }

        visitSegments = "<div style=\"display:flex; gap:3px;\">" + visitSegments + "</div>";
    } else {
        var visitPct = Round((visitsDone / visitTotal) * 100, 0);

        visitSegments =
            "<div style=\"background:#e0e0e0; border-radius:6px; height:10px; width:100%; overflow:hidden;\">"
            + "<div style=\"background:#2e7d32; height:10px; width:" + visitPct + "%; border-radius:6px;\"></div>"
            + "</div>";
    }

    var nextLine = "";

    if (!isBlank(val("nextvisitduedate"))) {
        var daysToNext = Round(DateDiff(Date(val("nextvisitduedate")), Now(), "days"), 0);

        if (daysToNext >= 0) {
            nextLine = "Next visit: " + dateTxt("nextvisitduedate") + " - in " + daysToNext + " days";
        } else {
            nextLine = "<span style=\"color:#d84315; font-weight:700;\">Next visit was due "
                + dateTxt("nextvisitduedate") + " - " + Abs(daysToNext) + " days ago</span>";
        }
    } else if (overdue == 1) {
        nextLine = "<span style=\"color:#d84315; font-weight:700;\">Remaining visits have no scheduled date</span>";
    } else if (visitsDone >= visitTotal) {
        nextLine = "Visit schedule completed";
    }

    var lastLine = "";

    if (!isBlank(val("monitoringdate"))) {
        var daysSince = Round(DateDiff(Now(), Date(val("monitoringdate")), "days"), 0);
        lastLine = "Last visit: " + dateTxt("monitoringdate") + " - " + daysSince + " days ago";
    }

    var visitColor = "#2e7d32";

    if (overdue == 1) {
        visitColor = "#d84315";
    }

    visitTracker =
        "<div style=\"background:#f7fafa; border-left:4px solid " + visitColor + "; border-radius:4px; margin-bottom:10px; padding:8px 12px 8px 8px;\">"
        + "<div style=\"font-size:10px; font-weight:700; color:" + visitColor + "; text-transform:uppercase; letter-spacing:0.8px; margin-bottom:6px;\">Monitoring Visits</div>"
        + "<div style=\"display:flex; justify-content:space-between; font-size:11px; color:#555; margin-bottom:5px;\">"
        + "<span>Completed</span>"
        + "<span style=\"font-weight:700; color:" + visitColor + ";\">" + visitsDone + " of " + visitTotal + "</span>"
        + "</div>"
        + visitSegments
        + "<div style=\"font-size:10px; color:#666; margin-top:6px;\">" + lastLine + "</div>"
        + "<div style=\"font-size:10px; color:#666; margin-top:2px;\">" + nextLine + "</div>"
        + "</div>";
}


// ============================================================
// LOCATION BREADCRUMB
// ============================================================

var crumbs = "";

if (!isBlank(country)) {
