expressionInfo.expression:
// ============================================================
// PES Applications Popup
// For existing Applications Points / Applications Polygons views
//
// Assumes the web map contains:
//   - PES Applications - Points
//   - PES Applications - Polygons
//   - PES Contracts
//
// Contract details are read live from "PES Contracts" using ContractCode.
// Current land-cover results are shown only after three calendar months.
// ============================================================

Expects($feature, "*");

// ============================================================
// HELPERS
// ============================================================

function hasField(fieldName) {
    return HasKey($feature, fieldName);
}

function val(fieldName) {
    if (hasField(fieldName)) {
        return $feature[fieldName];
    }
    return null;
}

function isBlank(x) {
    if (
        IsEmpty(x) ||
        x == null ||
        x == "" ||
        x == "[]" ||
        x == "Na" ||
        x == "NA" ||
        x == "N/A" ||
        x == "null"
    ) {
        return true;
    }
    return false;
}

function txt(x) {
    if (isBlank(x)) {
        return "";
    }
    return Text(x);
}

function num(fieldName) {
    var x = val(fieldName);
    if (isBlank(x)) {
        return 0;
    }
    var n = Number(x);
    if (IsNan(n)) {
        return 0;
    }
    return n;
}

function numValue(x) {
    if (isBlank(x)) {
        return 0;
    }
    var n = Number(x);
    if (IsNan(n)) {
        return 0;
    }
    return n;
}

function dateTxt(fieldName) {
    var x = val(fieldName);
    if (isBlank(x)) {
        return "";
    }
    return Text(Date(x), "DD MMM YYYY");
}

function dateValueTxt(x) {
    if (isBlank(x)) {
        return "";
    }
    return Text(Date(x), "DD MMM YYYY");
}

function areaTxt(x, decimals) {
    var n = Number(x);
    if (IsNan(n) || n == 0) {
        return "";
    }
    return Text(Round(n, decimals)) + " ha";
}

function pctTxt(x, decimals) {
    var n = Number(x);
    if (IsNan(n) || n == 0) {
        return "";
    }
    return Text(Round(n, decimals)) + "%";
}

function numberTxt(x, decimals) {
    var n = Number(x);
    if (IsNan(n) || n == 0) {
        return "";
    }
    return Text(Round(n, decimals));
}

function containsTxt(sourceText, searchText) {
    if (isBlank(sourceText)) {
        return false;
    }
    return Find(Lower(Text(searchText)), Lower(Text(sourceText)), 0) > -1;
}

function cleanList(raw) {
    if (isBlank(raw)) {
        return "";
    }
    var s = Text(raw);
    s = Replace(s, "[", "");
    s = Replace(s, "]", "");
    s = Replace(s, "\"", "");
    var items = Split(s, ",");
    var result = "";
    for (var i = 0; i < Count(items); i++) {
        var item = Trim(items[i]);
        if (!isBlank(item)) {
            if (result != "") {
                result = result + "<br>";
            }
            result = result + item;
        }
    }
    return result;
}

function extractValue(entry, keyName) {
    var pattern = "\"" + keyName + "\":";
    var parts = Split(entry, pattern);
    if (Count(parts) <= 1) {
        return "";
    }
    var right = Trim(parts[1]);
    if (Left(right, 1) == "\"") {
        var quotedParts = Split(right, "\"");
        if (Count(quotedParts) > 1) {
            return quotedParts[1];
        }
    }
    var commaPos = Find(",", right, 0);
    var bracePos = Find("}", right, 0);
    var endPos = -1;
    if (commaPos > -1 && bracePos > -1) {
        if (commaPos < bracePos) {
            endPos = commaPos;
        } else {
            endPos = bracePos;
        }
    } else if (commaPos > -1) {
        endPos = commaPos;
    } else if (bracePos > -1) {
        endPos = bracePos;
    }
    if (endPos > -1) {
        return Trim(Left(right, endPos));
    }
    return Trim(right);
}

function densityList(raw, wantedType) {
    if (isBlank(raw)) {
        return "";
    }
    var s = Text(raw);
    s = Replace(s, "[", "");
    s = Replace(s, "]", "");
    var entries = Split(s, "},{");
    var result = "";
    for (var i = 0; i < Count(entries); i++) {
        var entry = entries[i];
        if (Left(entry, 1) != "{") {
            entry = "{" + entry;
        }
        if (Right(entry, 1) != "}") {
            entry = entry + "}";
        }
        var name = extractValue(entry, "Name");
        var itemType = extractValue(entry, "Type");
        var density = extractValue(entry, "Density");
        if (!isBlank(name)) {
            if (isBlank(wantedType) || Lower(itemType) == Lower(wantedType)) {
                if (result != "") {
                    result = result + "<br>";
                }
                if (!isBlank(density)) {
                    result = result + name + " - " + density + "/ha";
                } else {
                    result = result + name;
                }
            }
        }
    }
    return result;
}

function aggregatorList(raw) {
    if (isBlank(raw)) {
        return "";
    }
    var s = Text(raw);
    s = Replace(s, "[", "");
    s = Replace(s, "]", "");
    var entries = Split(s, "},{");
    var result = "";
    for (var i = 0; i < Count(entries); i++) {
        var entry = entries[i];
        if (Left(entry, 1) != "{") {
            entry = "{" + entry;
        }
        if (Right(entry, 1) != "}") {
            entry = entry + "}";
        }
        var full = extractValue(entry, "EntityFullName");
        var acronym = extractValue(entry, "EntityAcronym");
        if (!isBlank(full)) {
            if (result != "") {
                result = result + "<br>";
            }
            result = result + full;
            if (!isBlank(acronym)) {
                result = result + " (" + acronym + ")";
            }
        }
    }
    return result;
}

function row(label, value) {
    if (isBlank(value) || value == 0 || value == "0") {
        return "";
    }
    return "<tr>"
        + "<td style=\"color:#666; width:48%; padding:4px 0; font-size:12px; vertical-align:top;\">" + label + "</td>"
        + "<td style=\"font-weight:600; font-size:12px; padding:4px 0; vertical-align:top;\">" + value + "</td>"
        + "</tr>";
}

function table(rows) {
    if (isBlank(rows)) {
        return "";
    }
    return "<table style=\"width:100%; border-collapse:collapse;\">" + rows + "</table>";
}

function section(title, accentColor, body) {
    if (isBlank(body)) {
        return "";
    }
    return "<div style=\"background:#f7fafa; border-left:4px solid " + accentColor + "; border-radius:4px; margin-bottom:10px; padding:8px 0px 8px 8px;\">"
        + "<div style=\"font-size:10px; font-weight:700; color:" + accentColor + "; text-transform:uppercase; letter-spacing:0.8px; margin-bottom:8px;\">" + title + "</div>"
        + body
        + "</div>";
}

function chip(labelText, bg, fg) {
    return "<div style=\"flex:1; text-align:center; background:" + bg + "; color:" + fg
        + "; padding:5px 4px; border-radius:6px; font-size:11px; font-weight:700;\">"
        + labelText
        + "</div>";
}

function areaBar(labelText, value, barColor, maxArea) {
    if (value <= 0 || maxArea <= 0) {
        return "";
    }
    var barW = Round((value / maxArea) * 200, 0);
    if (barW < 0) {
        barW = 0;
    }
    if (barW > 200) {
        barW = 200;
    }
    var emptyW = 200 - barW;
    return "<div style=\"margin-bottom:8px;\">"
        + "<div style=\"display:flex; justify-content:space-between; font-size:10px; color:#555; margin-bottom:3px;\">"
        + "<span style=\"font-weight:600;\">" + labelText + "</span>"
        + "<span style=\"font-weight:700; color:" + barColor + ";\">" + Round(value, 3) + " ha</span>"
        + "</div>"
        + "<div style=\"display:flex; height:14px; border-radius:4px; overflow:hidden;\">"
        + "<div style=\"width:" + barW + "px; background:" + barColor + "; height:14px;\"></div>"
        + "<div style=\"width:" + emptyW + "px; background:#e0e0e0; height:14px;\"></div>"
        + "</div>"
        + "</div>";
}

// ============================================================
// CORE VALUES
// ============================================================

var applicationCode = txt(DefaultValue(val("applicationcode"), val("applicationid")));
var contractCode = txt(val("contractcode"));
var stageName = txt(val("stage"));
var stageOrder = num("stageorder");
var stageCategory = txt(val("stagecategory"));
var isContract = num("iscontract");
var hasMonitoring = num("hasmonitoring");
var overdue = num("monitoringoverdue");
var applicationStatus = txt(val("applicationstatus"));
var activityType = txt(val("activitytype"));
var activityText = Lower(activityType);
var activityGroup = "generic";

if (
    activityType == "Agroforestry" ||
    containsTxt(activityText, "agroforestry") ||
    containsTxt(activityText, "agroforesterie")
) {
    activityGroup = "agroforestry";
}

if (
    activityType == "Reforestation" ||
    containsTxt(activityText, "reforestation") ||
    containsTxt(activityText, "reboisement")
) {
    activityGroup = "reforestation";
}

if (
    activityType == "NaturalRegenerationSavannah" ||
    activityType == "Natural Regeneration" ||
    containsTxt(activityText, "natural regeneration") ||
    containsTxt(activityText, "regeneration") ||
    containsTxt(activityText, "régénération")
) {
    activityGroup = "natural_regeneration";
}

var activityLabel = "PES Activity";
var mainAreaLabel = "Achieved Area";
var gapAreaLabel = "Gap Area";
var monitoringTitle = "PES Monitoring";

if (activityGroup == "agroforestry") {
    activityLabel = "Agroforestry";
    mainAreaLabel = "Agroforestry Planted Area";
    gapAreaLabel = "Unplanted / Gap Area";
    monitoringTitle = "Agroforestry Monitoring";
}
if (activityGroup == "reforestation") {
    activityLabel = "Reforestation";
    mainAreaLabel = "Planted / Restored Area";
    gapAreaLabel = "Unplanted / Failed Area";
    monitoringTitle = "Reforestation Monitoring";
}
if (activityGroup == "natural_regeneration") {
    activityLabel = "Natural Regeneration - Savannah";
    mainAreaLabel = "Observed Land Cover";
    gapAreaLabel = "Remaining / Non-covered Area";
    monitoringTitle = "Natural Regeneration Monitoring";
}

// ============================================================
// LIVE CONTRACT LOOKUP FROM PES CONTRACTS
// ============================================================

var con = null;
var conStart = null;
var conEnd = null;
var conStatus = "";
var conDuration = "";
var conDeclaredArea = 0;
var conContractedArea = 0;
var conTreeDensity = "";

if (!isBlank(contractCode)) {
    var cfs = Filter(
        FeatureSetByName(
            $map,
            "PES Contracts",
            [
                "contractcode",
                "contractstatus",
                "contractstartdate",
                "contractenddate",
                "contractduration",
                "areadeclaredbyplanter",
                "contractedpesarea",
                "treedensity"
            ],
            false
        ),
        "contractcode = @contractCode"
    );
    con = First(cfs);
    if (con != null) {
        conStart = con["contractstartdate"];
        conEnd = con["contractenddate"];
        conStatus = txt(con["contractstatus"]);
        conDuration = txt(con["contractduration"]);
        conDeclaredArea = numValue(con["areadeclaredbyplanter"]);
        conContractedArea = numValue(con["contractedpesarea"]);
        conTreeDensity = txt(con["treedensity"]);
    }
}

// ============================================================
// STATUS CHIPS
// ============================================================

var stageBg = "#eceff1";
var stageFg = "#607d8b";
if (stageOrder == 5) { stageBg = "#fff8e1"; stageFg = "#ff8f00"; }
if (stageOrder == 6) { stageBg = "#f9fbe7"; stageFg = "#9e9d24"; }
if (stageOrder == 7) { stageBg = "#e8f5e9"; stageFg = "#2e7d32"; }
if (stageCategory == "Rejected") { stageBg = "#ffebee"; stageFg = "#c62828"; }
if (stageCategory == "Archived") { stageBg = "#eeeeee"; stageFg = "#757575"; }
if (stageCategory == "Unknown") { stageBg = "#eceff1"; stageFg = "#546e7a"; }

var chipsHtml = chip("Stage: " + stageName, stageBg, stageFg);
if (!isBlank(conStatus)) {
    var conBg = "#fff3e0";
    var conFg = "#e65100";
    if (conStatus == "Active") { conBg = "#e8f5e9"; conFg = "#2e7d32"; }
    chipsHtml = chipsHtml + chip("Contract: " + conStatus, conBg, conFg);
}
if (overdue == 1) {
    chipsHtml = chipsHtml + chip("Visit overdue", "#fbe9e7", "#d84315");
}

var fireCat = txt(val("fireriskcategory"));
if (fireCat == "High") {
    chipsHtml = chipsHtml + chip("Fire risk: High", "#fff3e0", "#ef6c00");
}
if (fireCat == "Very High") {
    chipsHtml = chipsHtml + chip("Fire risk: Very High", "#fbe9e7", "#c62828");
}

// ============================================================
// STAGE TRACKER
// ============================================================

var trackerFill = "#0d7377";
var trackerReach = 0;
var trackerNote = "";
if (stageOrder >= 1 && stageOrder <= 7) {
    trackerReach = stageOrder;
    trackerNote = "Stage " + stageOrder + " of 7 - " + stageName;
}
if (stageCategory == "Rejected") {
    trackerFill = "#c62828";
    trackerReach = Abs(stageOrder);
    trackerNote = stageName + " - stopped at step " + Abs(stageOrder) + " of 7";
}
if (stageCategory == "Archived") {
    trackerFill = "#9e9e9e";
    trackerReach = 0;
    trackerNote = "Archived";
}
if (stageCategory == "Unknown") {
    trackerNote = "Status: " + applicationStatus;
}

var stepsHtml = "";
for (var i = 1; i <= 7; i++) {
    var stepColor = "#e0e0e0";
    if (i <= trackerReach) {
        stepColor = trackerFill;
    }
    stepsHtml = stepsHtml + "<div style=\"flex:1; height:9px; border-radius:3px; background:" + stepColor + ";\"></div>";
}

var stageTracker =
    "<div style=\"background:#f5f9f9; border-radius:6px; padding:8px 12px; margin-bottom:10px; border:1px solid #e0e0e0;\">"
    + "<div style=\"display:flex; justify-content:space-between; font-size:9px; color:#999; margin-bottom:4px; text-transform:uppercase; letter-spacing:0.5px;\">"
    + "<span>Pre-application</span><span>Approved</span>"
    + "</div>"
    + "<div style=\"display:flex; gap:3px;\">" + stepsHtml + "</div>"
    + "<div style=\"text-align:center; font-size:11px; font-weight:700; color:" + trackerFill + "; margin-top:5px;\">" + trackerNote + "</div>"
    + "</div>";

// ============================================================
// LOCATION BREADCRUMB
// ============================================================

var crumbs = "";
if (!isBlank(val("country"))) { crumbs = txt(val("country")); }
if (!isBlank(val("province"))) { crumbs = crumbs + " › " + txt(val("province")); }
if (!isBlank(val("territory"))) { crumbs = crumbs + " › " + txt(val("territory")); }
if (!isBlank(val("village"))) { crumbs = crumbs + " › " + txt(val("village")); }
var crumbHtml = "";
if (!isBlank(crumbs)) {
    crumbHtml = "<div style=\"background:#e8f5e9; border-radius:6px; padding:7px 6px; margin-bottom:10px; font-size:12px; color:#2e7d32; font-weight:500;\">" + crumbs + "</div>";
}

// ============================================================
// CONTRACT TIMELINE FROM PES CONTRACTS
// ============================================================

var contractTimeline = "";
if (!isBlank(conStart) && !isBlank(conEnd)) {
    var startMs = Number(Date(conStart));
    var endMs = Number(Date(conEnd));
    var nowMs = Number(Now());
    var progress = 0;
    if (!IsNan(startMs) && !IsNan(endMs) && endMs > startMs) {
        progress = Round(((nowMs - startMs) / (endMs - startMs)) * 100, 0);
    }
    if (progress < 0) { progress = 0; }
    if (progress > 100) { progress = 100; }
    var daysLeft = Round((endMs - nowMs) / 86400000, 0);
    var remaining = "Contract ended";
    if (!IsNan(daysLeft) && daysLeft > 0) {
        remaining = daysLeft + " days remaining";
    }
    var progressColor = "#4caf50";
    if (progress > 75) { progressColor = "#ff9800"; }
    if (progress >= 100) { progressColor = "#f44336"; }
    contractTimeline =
        "<div style=\"background:#f5f9f9; border-radius:6px; padding:8px 12px; margin-bottom:10px; border:1px solid #e0e0e0;\">"
        + "<div style=\"display:flex; justify-content:space-between; font-size:11px; color:#666; margin-bottom:4px;\">"
        + "<span>" + dateValueTxt(conStart) + "</span>"
        + "<span style=\"font-weight:700; color:" + progressColor + ";\">" + progress + "% complete</span>"
        + "<span>" + dateValueTxt(conEnd) + "</span>"
        + "</div>"
        + "<div style=\"background:#e0e0e0; border-radius:6px; height:10px; width:100%; overflow:hidden;\">"
        + "<div style=\"background:" + progressColor + "; height:10px; width:" + progress + "%; border-radius:6px;\"></div>"
        + "</div>"
        + "<div style=\"text-align:center; font-size:10px; color:#888; margin-top:4px;\">" + remaining + "</div>"
        + "</div>";
}

// ============================================================
// VISIT SCHEDULE TRACKER
// ============================================================

var visitTotal = num("visitcount");
var visitsDone = num("visitscompleted");
var visitTracker = "";
if (visitTotal > 0) {
    var visitSegments = "";
    if (visitTotal <= 16) {
        for (var v = 1; v <= visitTotal; v++) {
            var segColor = "#e0e0e0";
            if (v <= visitsDone) { segColor = "#2e7d32"; }
            visitSegments = visitSegments + "<div style=\"flex:1; height:10px; border-radius:2px; background:" + segColor + ";\"></div>";
        }
        visitSegments = "<div style=\"display:flex; gap:3px;\">" + visitSegments + "</div>";
    } else {
        var visitPct = Round((visitsDone / visitTotal) * 100, 0);
        visitSegments =
            "<div style=\"background:#e0e0e0; border-radius:6px; height:10px; width:100%; overflow:hidden;\">"
            + "<div style=\"background:#2e7d32; height:10px; width:" + visitPct + "%; border-radius:6px;\"></div>"
            + "</div>";
    }
    var nextLine = "";
    if (!isBlank(val("nextvisitduedate"))) {
        var daysToNext = Round(DateDiff(Date(val("nextvisitduedate")), Now(), "days"), 0);
        if (daysToNext >= 0) {
            nextLine = "Next visit: " + dateTxt("nextvisitduedate") + " - in " + daysToNext + " days";
        } else {
            nextLine = "<span style=\"color:#d84315; font-weight:700;\">Next visit was due "
                + dateTxt("nextvisitduedate") + " - " + Abs(daysToNext) + " days ago</span>";
        }
    } else if (overdue == 1) {
        nextLine = "<span style=\"color:#d84315; font-weight:700;\">Remaining visits have no scheduled date</span>";
    } else if (visitsDone >= visitTotal) {
        nextLine = "Visit schedule completed";
    }
    var lastLine = "";
    if (!isBlank(val("monitoringdate"))) {
        var daysSince = Round(DateDiff(Now(), Date(val("monitoringdate")), "days"), 0);
        lastLine = "Last visit: " + dateTxt("monitoringdate") + " - " + daysSince + " days ago";
    }
    var visitColor = "#2e7d32";
    if (overdue == 1) { visitColor = "#d84315"; }
    visitTracker =
        "<div style=\"background:#f7fafa; border-left:4px solid " + visitColor + "; border-radius:4px; margin-bottom:10px; padding:8px 12px 8px 8px;\">"
        + "<div style=\"font-size:10px; font-weight:700; color:" + visitColor + "; text-transform:uppercase; letter-spacing:0.8px; margin-bottom:6px;\">Monitoring Visits</div>"
        + "<div style=\"display:flex; justify-content:space-between; font-size:11px; color:#555; margin-bottom:5px;\">"
        + "<span>Completed</span>"
        + "<span style=\"font-weight:700; color:" + visitColor + ";\">" + visitsDone + " of " + visitTotal + "</span>"
        + "</div>"
        + visitSegments
        + "<div style=\"font-size:10px; color:#666; margin-top:6px;\">" + lastLine + "</div>"
        + "<div style=\"font-size:10px; color:#666; margin-top:2px;\">" + nextLine + "</div>"
        + "</div>";
}

// ============================================================
// NUMERIC VALUES
// ============================================================

var estimatedArea = num("estimatedarea");
var declaredArea = conDeclaredArea;
var contractedArea = conContractedArea;
var plantedArea = num("plantedareameasured");
var unplantedArea = num("unplantedarea");
var observedTrees = num("observednumberoftrees");
var initialCoverHa = num("initiallandcoverinha");
var initialCoverPct = num("initiallandcoverinpercentage");
var observedCoverPct = num("observedlandcoverpercentage");
var observedCoverHa = num("observedlandcoverha");
var observedTreeDensity = num("observedtreedensity");
var observedBasalArea = num("observedbasalarea");
var totalMonitored = plantedArea + unplantedArea;
var plantedPct = 0;
var unplantedPct = 0;
if (totalMonitored > 0) {
    plantedPct = Round((plantedArea / totalMonitored) * 100, 1);
    unplantedPct = Round((unplantedArea / totalMonitored) * 100, 1);
}

// ============================================================
// PERFORMANCE VISUAL
// ============================================================

var visuals = "";
if (
    (activityGroup == "agroforestry" || activityGroup == "reforestation" || activityGroup == "generic") &&
    totalMonitored > 0
) {
    var donutColor = "#f44336";
    if (plantedPct >= 30 && plantedPct < 70) { donutColor = "#ff9800"; }
    if (plantedPct >= 70) { donutColor = "#4caf50"; }
    visuals =
        "<div style=\"background:#f7fafa; border-left:4px solid " + donutColor + "; border-radius:4px; margin-bottom:10px; padding:8px 0px 8px 8px;\">"
        + "<div style=\"font-size:10px; font-weight:700; color:" + donutColor + "; text-transform:uppercase; letter-spacing:0.8px; margin-bottom:8px;\">" + activityLabel + " Performance</div>"
        + "<div style=\"display:flex; align-items:center; gap:16px;\">"
        + "<div style=\"width:90px; height:90px; flex-shrink:0;\">"
        + "<div style=\"width:90px; height:90px; border-radius:50%; background:conic-gradient(#4caf50 0% " + plantedPct + "%, #ff9800 " + plantedPct + "% 100%); display:flex; align-items:center; justify-content:center;\">"
        + "<div style=\"width:58px; height:58px; background:white; border-radius:50%; display:flex; align-items:center; justify-content:center;\">"
        + "<div style=\"text-align:center;\"><div style=\"font-size:13px; font-weight:700; color:" + donutColor + ";\">" + plantedPct + "%</div>"
        + "<div style=\"font-size:8px; color:#888; line-height:1.2;\">achieved</div></div></div></div></div>"
        + "<div style=\"flex:1;\">"
        + "<div style=\"margin-bottom:8px;\"><div style=\"font-size:11px; color:#555;\">" + mainAreaLabel + "</div>"
        + "<div style=\"font-size:15px; font-weight:700; color:#4caf50;\">" + Round(plantedArea, 3) + " ha</div>"
        + "<div style=\"font-size:10px; color:#888;\">" + plantedPct + "% of monitored area</div></div>"
        + "<div><div style=\"font-size:11px; color:#555;\">" + gapAreaLabel + "</div>"
        + "<div style=\"font-size:15px; font-weight:700; color:#ff9800;\">" + Round(unplantedArea, 3) + " ha</div>"
        + "<div style=\"font-size:10px; color:#888;\">" + unplantedPct + "% of monitored area</div></div></div></div>"
        + "<div style=\"margin-top:8px; background:#fff; border-radius:4px; padding:5px 8px; border:1px solid #e0e0e0; text-align:center;\">"
        + "<span style=\"font-size:10px; color:#555;\">Total monitored area: </span>"
        + "<span style=\"font-size:11px; font-weight:700; color:#333;\">" + Round(totalMonitored, 3) + " ha</span></div></div>";
}

if (activityGroup == "natural_regeneration" && observedCoverPct > 0) {
    var coverColor = "#f44336";
    if (observedCoverPct >= 40 && observedCoverPct < 70) { coverColor = "#ff9800"; }
    if (observedCoverPct >= 70) { coverColor = "#4caf50"; }
    visuals =
        "<div style=\"background:#f7fafa; border-left:4px solid " + coverColor + "; border-radius:4px; margin-bottom:10px; padding:8px 0px 8px 8px;\">"
        + "<div style=\"font-size:10px; font-weight:700; color:" + coverColor + "; text-transform:uppercase; letter-spacing:0.8px; margin-bottom:8px;\">Natural Regeneration Progress</div>"
        + "<div style=\"display:flex; align-items:center; gap:16px;\">"
        + "<div style=\"width:90px; height:90px; flex-shrink:0;\"><div style=\"width:90px; height:90px; border-radius:50%; background:conic-gradient(#4caf50 0% " + observedCoverPct + "%, #e0e0e0 " + observedCoverPct + "% 100%); display:flex; align-items:center; justify-content:center;\">"
        + "<div style=\"width:58px; height:58px; background:white; border-radius:50%; display:flex; align-items:center; justify-content:center;\"><div style=\"text-align:center;\">"
        + "<div style=\"font-size:13px; font-weight:700; color:" + coverColor + ";\">" + Round(observedCoverPct, 1) + "%</div>"
        + "<div style=\"font-size:8px; color:#888; line-height:1.2;\">cover</div></div></div></div></div>"
        + "<div style=\"flex:1;\"><div style=\"font-size:11px; color:#555;\">Initial land cover</div>"
        + "<div style=\"font-size:14px; font-weight:700; color:#1565c0; margin-bottom:8px;\">" + Round(initialCoverPct, 1) + "% | " + Round(initialCoverHa, 3) + " ha</div>"
        + "<div style=\"font-size:11px; color:#555;\">Observed land cover</div>"
        + "<div style=\"font-size:14px; font-weight:700; color:#4caf50; margin-bottom:8px;\">" + Round(observedCoverPct, 1) + "% | " + Round(observedCoverHa, 3) + " ha</div>"
        + "<div style=\"font-size:11px; color:#555;\">Observed tree density / basal area</div>"
        + "<div style=\"font-size:13px; font-weight:700; color:#333;\">" + Round(observedTreeDensity, 2) + " | " + Round(observedBasalArea, 4) + "</div>"
        + "</div></div></div>";
}

// ============================================================
// AREA COMPARISON
// ============================================================

var achievedArea = plantedArea;
if (activityGroup == "natural_regeneration") { achievedArea = observedCoverHa; }
var maxArea = estimatedArea;
if (declaredArea > maxArea) { maxArea = declaredArea; }
if (contractedArea > maxArea) { maxArea = contractedArea; }
if (achievedArea > maxArea) { maxArea = achievedArea; }
var areaBars =
    areaBar("Estimated application area", estimatedArea, "#607d8b", maxArea)
    + areaBar("Declared by planter", declaredArea, "#1565c0", maxArea)
    + areaBar("Contracted", contractedArea, "#0d7377", maxArea)
    + areaBar(mainAreaLabel, achievedArea, "#4caf50", maxArea);
var areaComparison = "";
if (!isBlank(areaBars)) {
    areaComparison =
        "<div style=\"background:#f7fafa; border-left:4px solid #1565c0; border-radius:4px; margin-bottom:10px; padding:8px 0px 8px 8px;\">"
        + "<div style=\"font-size:10px; font-weight:700; color:#1565c0; text-transform:uppercase; letter-spacing:0.8px; margin-bottom:8px;\">Area Comparison</div>"
        + areaBars + "</div>";
}

// ============================================================
// LAND COVER AND FIRE RISK
// ============================================================

var lcApp = txt(val("landcoveratapplication"));
var lcAppPct = num("landcoveratapplicationpct");
var lcNow = txt(val("landcovercurrent"));
var lcNowPct = num("landcovercurrentpct");
var lcChanged = num("landcoverchanged");
var fireBurns = num("fireburncount");
var firePct = num("fireburnedpct");

// Current land cover is eligible only from the exact date obtained
// by adding three calendar months to the application date.
var showCurrentLandCover = false;
var applicationDateRaw = val("applicationdate");
if (!isBlank(applicationDateRaw)) {
    var applicationDateForComparison = Date(applicationDateRaw);
    var currentLandCoverAvailableDate = DateAdd(applicationDateForComparison, 3, "months");
    if (Now() >= currentLandCoverAvailableDate) {
        showCurrentLandCover = true;
    }
}

var hasApplicationLandCover = !isBlank(lcApp);
var hasCurrentLandCover = showCurrentLandCover && !isBlank(lcNow);
var hasVisibleLandCover = hasApplicationLandCover || hasCurrentLandCover;
var landFireCard = "";

if (hasVisibleLandCover || !isBlank(fireCat)) {
    var accent = "#607d8b";
    if (hasCurrentLandCover && lcChanged == 1) {
        accent = "#ff8f00";
    }

    var lcHtml = "";
    if (hasVisibleLandCover) {
        var applicationLandCoverHtml = "";
        var currentLandCoverHtml = "";
        var arrowHtml = "";
        var changeNoteHtml = "";

        if (hasApplicationLandCover) {
            applicationLandCoverHtml =
                "<div style=\"flex:1; background:#fff; border:1px solid #e0e0e0; border-radius:6px; padding:6px; text-align:center;\">"
                + "<div style=\"font-size:9px; color:#888; text-transform:uppercase; letter-spacing:.5px;\">At application</div>"
                + "<div style=\"font-size:12px; font-weight:700; color:#455a64; margin-top:2px;\">" + DefaultValue(lcApp, "-") + "</div>"
                + IIf(lcAppPct > 0, "<div style=\"font-size:9px; color:#999;\">" + Round(lcAppPct, 0) + "% of parcel</div>", "")
                + "</div>";
        }

        if (hasCurrentLandCover) {
            var arrowColor = "#9e9e9e";
            var currentBorderColor = "#e0e0e0";
            var currentTextColor = "#2e7d32";
            var changeNote = "unchanged";
            if (lcChanged == 1) {
                arrowColor = "#ff8f00";
                currentBorderColor = "#ffb74d";
                currentTextColor = "#e65100";
                changeNote = "changed";
            }
            if (hasApplicationLandCover) {
                arrowHtml = "<div style=\"font-size:16px; color:" + arrowColor + "; font-weight:700;\">&rarr;</div>";
            }
            currentLandCoverHtml =
                "<div style=\"flex:1; background:#fff; border:1px solid " + currentBorderColor + "; border-radius:6px; padding:6px; text-align:center;\">"
                + "<div style=\"font-size:9px; color:#888; text-transform:uppercase; letter-spacing:.5px;\">Current</div>"
                + "<div style=\"font-size:12px; font-weight:700; color:" + currentTextColor + "; margin-top:2px;\">" + DefaultValue(lcNow, "-") + "</div>"
                + IIf(lcNowPct > 0, "<div style=\"font-size:9px; color:#999;\">" + Round(lcNowPct, 0) + "% of parcel</div>", "")
                + "</div>";
            if (hasApplicationLandCover) {
                changeNoteHtml =
                    "<div style=\"font-size:10px; color:#888; margin-bottom:6px;\">Dominant land cover - "
                    + changeNote + " since application</div>";
            }
        }

        lcHtml =
            "<div style=\"display:flex; align-items:center; gap:8px; margin-bottom:6px;\">"
            + applicationLandCoverHtml + arrowHtml + currentLandCoverHtml + "</div>"
            + changeNoteHtml;
    }

    var fireHtml = "";
    if (!isBlank(fireCat)) {
        var fireBg = "#e8f5e9";
        var fireFg = "#2e7d32";
        if (fireCat == "Moderate") { fireBg = "#fff8e1"; fireFg = "#ff8f00"; }
        if (fireCat == "High") { fireBg = "#fff3e0"; fireFg = "#ef6c00"; }
        if (fireCat == "Very High") { fireBg = "#fbe9e7"; fireFg = "#c62828"; }
        var fireNote = "No burns recorded on the parcel in the last 5 years";
        if (fireBurns > 0) {
            fireNote = "Parcel burned " + Round(fireBurns, 0) + " time(s) in the last 5 years";
            if (firePct > 0) {
                fireNote = fireNote + " - " + Round(firePct, 0) + "% of the area affected";
            }
        }
        fireHtml =
            "<div style=\"display:flex; align-items:center; gap:8px;\">"
            + "<div style=\"background:" + fireBg + "; color:" + fireFg + "; padding:4px 10px; border-radius:6px; font-size:11px; font-weight:700;\">Fire risk: " + fireCat + "</div>"
            + "<div style=\"font-size:10px; color:#666;\">" + fireNote + "</div></div>";
    }

    var geeUpdateHtml = "<div style=\"font-size:9px; color:#aaa; margin-top:6px;\">Source: Google Earth Engine";
    if (!isBlank(val("geelastupdate"))) {
        geeUpdateHtml = geeUpdateHtml + " - updated " + dateTxt("geelastupdate");
    }
    geeUpdateHtml = geeUpdateHtml + "</div>";

    landFireCard =
        "<div style=\"background:#f7fafa; border-left:4px solid " + accent + "; border-radius:4px; margin-bottom:10px; padding:8px 12px 8px 8px;\">"
        + "<div style=\"font-size:10px; font-weight:700; color:" + accent + "; text-transform:uppercase; letter-spacing:.8px; margin-bottom:8px;\">Land Cover &amp; Fire Risk</div>"
        + lcHtml + fireHtml + geeUpdateHtml + "</div>";
}

// ============================================================
// TABLE SECTIONS
// ============================================================

var applicationRows =
    row("Application Code", applicationCode)
    + row("Application Status", applicationStatus)
    + row("Application Date", dateTxt("applicationdate"))
    + row("Activity Type", activityType)
    + row("Estimated Area", areaTxt(estimatedArea, 3));

var locationRows =
    row("Country", txt(val("country")))
    + row("Province", txt(val("province")))
    + row("Territory", txt(val("territory")))
    + row("Village", txt(val("village")));

var beneficiaryRows =
    row("Beneficiary Type", txt(val("beneficiarytype")))
    + row("Beneficiary Status", txt(val("beneficiarystatus")))
    + row("Gender", txt(val("beneficiarygender")))
    + row("Family Situation", txt(val("familysituation")))
    + row("Dependents", txt(val("dependents")))
    + row("Number of Community Members", txt(val("numberofcommunitymembers")));

var projectRows =
    row("Project Name", txt(val("projectname")))
    + row("Implementing Org.", txt(val("implementingorgname")))
    + row("Org. Acronym", txt(val("implementingorgacronym")))
    + row("Supporting Aggregator", aggregatorList(val("supportingaggregator")));

var contractRows = "";
if (!isBlank(contractCode) && con != null) {
    contractRows =
        row("Contract Code", contractCode)
        + row("Contract Status", conStatus)
        + row("Start", dateValueTxt(conStart))
        + row("End", dateValueTxt(conEnd))
        + row("Duration Years", conDuration)
        + row("Declared Area", areaTxt(conDeclaredArea, 3))
        + row("Contracted PES Area", areaTxt(conContractedArea, 3))
        + row("Planned Species and Density", densityList(conTreeDensity, ""));
}

var monitoringRows = "";
if (hasMonitoring == 1) {
    monitoringRows =
        row("Last Monitoring Date", dateTxt("monitoringdate"))
        + row("Monitoring Visit Code", txt(val("monitoringvisitcode")))
        + row("Contracted Area of Monitoring", areaTxt(num("contractedareaofmonitoring"), 3))
        + row(mainAreaLabel, areaTxt(plantedArea, 3))
        + row(gapAreaLabel, areaTxt(unplantedArea, 3))
        + row("Observed Trees Count", numberTxt(observedTrees, 0))
        + row("Observed Land Cover", areaTxt(observedCoverHa, 3))
        + row("Observed Land Cover %", pctTxt(observedCoverPct, 1))
        + row("Tree Species", cleanList(val("treespecies")));
}

// ============================================================
// GEOMETRY NOTE
// ============================================================

var geometryNote = "";
var geomSrc = txt(val("geometrysource"));
if (geomSrc == "monitoring_visit_shape") {
    geometryNote = "Polygon comes from the latest monitoring visit.";
}
if (geomSrc == "application_shape") {
    geometryNote = "Polygon comes from the application geometry.";
}
var geometryHtml = "";
if (geometryNote != "") {
    geometryHtml = "<div style=\"background:#fffde7; border-radius:6px; padding:6px 8px; margin-bottom:10px; font-size:10px; color:#795548;\">" + geometryNote + "</div>";
}

// ============================================================
// BUILD POPUP
// ============================================================

var popup =
    "<div style=\"font-family:Segoe UI,sans-serif; font-size:13px; color:#1a1a2e; padding:0;\">"
    + "<div style=\"background:#0d7377; color:white; padding:10px 12px; border-radius:6px 6px 0 0; margin:0 0 10px 0;\">"
    + "<div style=\"font-size:15px; font-weight:700;\">PES Application " + applicationCode + "</div>"
    + "<div style=\"font-size:11px; opacity:0.85; margin-top:2px;\">" + txt(val("projectname")) + " - " + txt(val("implementingorgacronym")) + "</div>"
    + "<div style=\"font-size:10px; opacity:0.9; margin-top:4px; text-transform:uppercase; letter-spacing:0.8px;\">" + activityLabel + "</div>"
    + "</div>"
    + "<div style=\"display:flex; gap:6px; margin-bottom:10px; flex-wrap:wrap;\">" + chipsHtml + "</div>"
    + stageTracker
    + crumbHtml
    + contractTimeline
    + visitTracker
    + landFireCard
    + visuals
    + areaComparison
    + section("Application", "#0d7377", table(applicationRows))
    + section("Location", "#14a085", table(locationRows))
    + section("Beneficiary Details", "#2196f3", table(beneficiaryRows))
    + section("Project Information", "#607d8b", table(projectRows))
    + section("Contract", "#9c27b0", table(contractRows))
    + section(monitoringTitle, "#ff9800", table(monitoringRows))
    + geometryHtml
    + "<div style=\"text-align:center; font-size:10px; color:#aaa; margin-top:10px; padding-top:8px; border-top:1px solid #eee;\">"
    + "Application: " + applicationCode
    + "&nbsp;|&nbsp; Contract: " + contractCode
    + "&nbsp;|&nbsp; Synced: " + dateTxt("lastapisync")
    + "</div>"
    + "</div>";

return {
    type: "text",
    text: popup
};

expressionInfos.expression:
// ============================================================
// PES Applications popup title
// Includes fallback to ApplicationId for older rows where
// ApplicationCode may still be NULL.
// ============================================================

var code = DefaultValue(
    $feature.ApplicationCode,
    DefaultValue($feature.ApplicationId, "Application")
);

var stage = DefaultValue($feature.Stage, "No stage");

return code + "  |  " + stage;

expressionInfo.expression:
var appID = $feature.ApplicationId;

return {
  type: "text",
  text: "<div style=\"font-family:Segoe UI,sans-serif; background:#f7fafa; border-left:4px solid #0d7377; border-radius:4px; padding:8px 0px 8px 8px; margin-bottom:4px;\">"
    + "<div style=\"font-size:10px; font-weight:700; color:#0d7377; text-transform:uppercase; letter-spacing:0.8px; margin-bottom:5px;\">APPLICATION ID</div>"
    + "<div style=\"background:#e0f7fa; border-radius:6px; padding:8px 12px;\">"
    + "<div style=\"font-size:14px; font-weight:700; color:#0d7377;\">" 
    + appID 
    + "</div>"
    + "</div>"
    + "</div>"
};

var ContractCode = $feature.ContractCode;

return {
  type: "text",
  text: "<div style=\"font-family:Segoe UI,sans-serif; background:#f7fafa; border-left:4px solid #0d7377; border-radius:4px; padding:8px 0px 8px 8px; margin-bottom:4px;\">"
    + "<div style=\"font-size:10px; font-weight:700; color:#0d7377; text-transform:uppercase; letter-spacing:0.8px; margin-bottom:5px;\">Contract Code</div>"
    + "<div style=\"background:#e0f7fa; border-radius:6px; padding:8px 12px;\">"
